/* --- 2. БАЗОВЫЕ СТИЛИ И СБРОС --- */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    font-family: 'Inter', sans-serif;
}

body {
    background: var(--bg-app);
    color: var(--text-main);
    min-height: 100vh;
    display: flex;
    overflow-x: hidden;
    -webkit-font-smoothing: antialiased;
}

/* --- 3. ГЛАВНЫЙ КАРКАС ПРИЛОЖЕНИЯ (LAYOUT) --- */
.app-container {
    display: flex;
    width: 100%;
    min-height: 100vh;
}

/* Боковое меню (Sidebar - Глубокое матовое стекло) */
.sidebar {
    width: var(--sidebar-width);
    background: rgba(20, 10, 35, 0.6);
    backdrop-filter: blur(30px);
    -webkit-backdrop-filter: blur(30px);
    padding: 30px 20px;
    display: flex;
    flex-direction: column;
    position: fixed;
    height: 100vh;
    left: 0;
    top: 0;
    z-index: 100;
    border-right: 1px solid var(--glass-border);
}

.sidebar-logo {
    display: flex;
    align-items: center;
    gap: 14px;
    color: var(--text-main);
    font-size: 1.5rem;
    font-weight: 800;
    margin-bottom: 50px;
}

.sidebar-logo span:first-child {
    font-size: 1.8rem;
    filter: drop-shadow(0 0 5px var(--primary-neon));
}

/* Профиль клиники */
.user-profile-badge {
    background: rgba(255, 255, 255, 0.03);
    border-radius: var(--radius-md);
    padding: 16px;
    margin-bottom: 35px;
    border: 1px solid rgba(255, 255, 255, 0.05);
}

.user-profile-badge h4 {
    color: var(--text-main);
    font-size: 1rem;
    font-weight: 600;
}

.user-profile-badge span {
    color: var(--text-muted);
    font-size: 0.8rem;
}

/* Навигация (Неоновые пункты) */
.sidebar-menu {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.menu-item a {
    display: flex;
    align-items: center;
    gap: 16px;
    color: var(--text-muted);
    text-decoration: none;
    padding: 14px 18px;
    border-radius: var(--radius-md);
    font-weight: 500;
    font-size: 1rem;
    transition: var(--transition);
}

.menu-item a:hover {
    color: var(--text-main);
    background: rgba(255, 255, 255, 0.04);
}

/* Активный пункт меню с неоновым свечением */
.menu-item.active a {
    color: #ffffff;
    background: var(--primary-neon);
    box-shadow: var(--primary-glow);
}

/* Главная контентная область */
.main-content {
    margin-left: var(--sidebar-width);
    flex-grow: 1;
    padding: 40px;
    max-width: calc(100% - var(--sidebar-width));
}

/* Верхняя шапка (Панель управления) */
.header-panel {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 40px;
}

.search-bar {
    width: 400px;
    position: relative;
}

.search-bar input {
    width: 100%;
    padding: 16px 24px;
    background: var(--glass-bg);
    backdrop-filter: var(--glass-blur);
    border: 1px solid var(--glass-border);
    border-radius: 30px;
    font-size: 0.95rem;
    color: var(--text-main);
    transition: var(--transition);
}

.search-bar input:focus {
    border-color: var(--primary-neon);
    background: rgba(255, 255, 255, 0.06);
    box-shadow: 0 0 15px rgba(163, 97, 255, 0.1);
}

/* --- 4. КНОПКИ И ПЕРЕКЛЮЧАТЕЛИ (NEON GLASS STYLE) --- */
.nav-buttons-group {
    display: flex;
    gap: 10px;
    background: rgba(255, 255, 255, 0.03);
    backdrop-filter: blur(10px);
    padding: 8px;
    border-radius: 40px;
    border: 1px solid var(--glass-border);
}

.btn-tab {
    padding: 12px 24px;
    border: none;
    background: transparent;
    border-radius: 30px;
    font-size: 0.95rem;
    font-weight: 600;
    color: var(--text-muted);
    cursor: pointer;
    transition: var(--transition);
}

.btn-tab:hover {
    color: var(--text-main);
}

.btn-tab.active {
    background: var(--primary-neon);
    color: #ffffff;
    box-shadow: var(--primary-glow);
}

/* Датапикер (Светящиеся стрелочки) */
.btn-arrow {
    width: 45px;
    height: 45px;
    border-radius: 50%;
    border: 1px solid var(--glass-border);
    background: var(--glass-bg);
    backdrop-filter: blur(5px);
    color: var(--text-main);
    font-size: 1.2rem;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: var(--transition);
}

.btn-arrow:hover {
    background: rgba(255, 255, 255, 0.08);
    border-color: var(--accent-neon);
    color: var(--accent-neon);
}

.current-date-title {
    font-size: 1.5rem;
    font-weight: 800;
    color: var(--text-main);
}

/* --- 5. МОДУЛЬ КАЛЕНДАРЯ (ULTRA GLASS GRID) --- */

/* Главная плашка календаря - Максимальное стекло */
.calendar-container {
    background: var(--glass-bg);
    backdrop-filter: var(--glass-blur);
    -webkit-backdrop-filter: var(--glass-blur);
    border: 1px solid var(--glass-border);
    border-radius: var(--radius-lg);
    padding: 30px;
    box-shadow: var(--shadow-premium);
    display: flex;
    flex-direction: column;
    overflow: hidden; 
}

/* Обертка для горизонтального скролла */
.calendar-grid-wrapper {
    width: 100%;
    overflow-x: auto;
    scroll-behavior: smooth;
    padding-bottom: 15px;
}

/* Неоновый скроллбар */
.calendar-grid-wrapper::-webkit-scrollbar {
    height: 7px;
}
.calendar-grid-wrapper::-webkit-scrollbar-thumb {
    background: rgba(163, 97, 255, 0.3);
    border-radius: 10px;
}
.calendar-grid-wrapper::-webkit-scrollbar-thumb:hover {
    background: var(--primary-neon);
    box-shadow: var(--primary-glow);
}

/* Сетка календаря */
.calendar-grid {
    display: grid;
    /* Время зафиксировано, колонки врачей не сжимаются меньше 240px */
    grid-template-columns: 80px repeat(auto-fill, minmax(240px, 1fr));
    gap: 15px;
    min-width: max-content; 
}

/* Липкая колонка времени (Тонированное стекло) */
.time-column-header,
.time-cell {
    position: sticky;
    left: 0;
    background: rgba(26, 11, 46, 0.9); /* Глубокий фон под цвет базы */
    backdrop-filter: blur(15px);
    z-index: 10;
    font-weight: 700;
    color: var(--text-muted);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.9rem;
}

.time-column-header {
    height: 80px;
    text-transform: uppercase;
}

/* Стеклянные карточки ветеринаров (Хай-тек шапки) */
.vet-column-header {
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: var(--radius-md);
    padding: 20px;
    transition: var(--transition);
    height: 80px;
    display: flex;
    flex-direction: column;
    justify-content: center;
}

.vet-name {
    font-weight: 700;
    color: var(--text-main);
    font-size: 1.05rem;
    margin-bottom: 3px;
}

.vet-spec {
    font-size: 0.8rem;
    color: var(--text-muted);
    font-weight: 500;
}

/* Эффект при наведении на врача (Неоновая рамка) */
.vet-column-header:hover {
    transform: translateY(-4px);
    background: rgba(255, 255, 255, 0.07);
    border-color: var(--primary-neon);
    box-shadow: 0 8px 30px rgba(163, 97, 255, 0.2);
}

/* Ячейки времени (Пустые) */
.appointment-cell {
    background: rgba(255, 255, 255, 0.02);
    border: 1px dashed rgba(255, 255, 255, 0.06);
    border-radius: var(--radius-md);
    min-height: 90px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: rgba(255, 255, 255, 0.15);
    font-size: 0.9rem;
    font-weight: 600;
    transition: var(--transition);
    cursor: pointer;
}

/* Эффект при наведении на пустую ячейку (Появляется неоновый плюс) */
.appointment-cell:hover {
    background: rgba(163, 97, 255, 0.05);
    border: 1px solid var(--primary-neon);
    color: var(--primary-neon);
    transform: scale(1.02);
    box-shadow: 0 0 15px rgba(163, 97, 255, 0.1);
}

/* --- 6. ТАБЛИЦЫ (ХАЙ-ТЕК СПИСКИ) --- */
.data-table-container {
    background: var(--glass-bg);
    backdrop-filter: var(--glass-blur);
    border: 1px solid var(--glass-border);
    border-radius: var(--radius-lg);
    padding: 25px;
    box-shadow: var(--shadow-premium);
}

.data-table th {
    padding: 16px 20px;
    color: var(--text-main);
    font-size: 0.85rem;
    font-weight: 700;
    text-transform: uppercase;
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
    text-align: left;
}

.data-table td {
    padding: 18px 20px;
    color: var(--text-muted);
    font-size: 0.95rem;
    border-bottom: 1px solid rgba(255, 255, 255, 0.03);
}

/* Неоновые статусы */
.badge-success { background: rgba(0, 255, 136, 0.1); color: var(--color-success); border: 1px solid rgba(0, 255, 136, 0.2); }
.badge-danger { background: rgba(255, 51, 51, 0.1); color: var(--color-danger); border: 1px solid rgba(255, 51, 51, 0.2); }


/* --- 7. ПАЦИЕНТЫ И МОДАЛКИ (GLASS MODAL ИСПРАВЛЕНИЕ) --- */
.patients-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    gap: 25px;
}

.patient-premium-card {
    background: var(--glass-bg);
    backdrop-filter: blur(15px);
    border: 1px solid var(--glass-border);
    border-radius: var(--radius-md);
    padding: 25px;
    transition: var(--transition);
}

.patient-premium-card:hover {
    transform: translateY(-5px);
    border-color: rgba(255, 255, 255, 0.15);
    background: rgba(255, 255, 255, 0.05);
    box-shadow: 0 15px 40px rgba(0, 0, 0, 0.3);
}

/* МОДАЛЬНЫЕ ОКНА (ULTRA GLASS ИСПРАВЛЕНИЕ АРТЕФАКТА, СМ. IMAGE_6.PNG) */
.modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(10, 5, 20, 0.7); /* Очень темный бэкдроп */
    backdrop-filter: blur(15px); /* Сильное размытие фона */
    -webkit-backdrop-filter: blur(15px);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
    opacity: 0;
    pointer-events: none;
    transition: var(--transition);
}

.modal-overlay.active {
    opacity: 1;
    pointer-events: auto;
}

.modal-window {
    background: rgba(25, 15, 40, 0.8);
    backdrop-filter: blur(40px); /* Сверхчеткое размытие внутри окна */
    -webkit-backdrop-filter: blur(40px);
    border: 1px solid rgba(255, 255, 255, 0.1);
    width: 100%;
    max-width: 550px;
    border-radius: var(--radius-lg);
    padding: 40px;
    box-shadow: 0 25px 60px rgba(0, 0, 0, 0.5);
    transform: scale(0.8);
    transition: var(--transition);
}

.modal-overlay.active .modal-window {
    transform: scale(1);
}

/* Главная Хайтек Кнопка */
.btn-primary {
    background: var(--primary-neon);
    color: #fff;
    padding: 16px 30px;
    border-radius: var(--radius-sm);
    font-weight: 700;
    font-size: 1rem;
    text-transform: uppercase;
    cursor: pointer;
    box-shadow: var(--primary-glow);
}

.btn-primary:hover {
    transform: translateY(-2px);
    box-shadow: 0 0 25px rgba(163, 97, 255, 0.6);
}
/* --- МИНИМАЛИСТИЧНАЯ ПАНЕЛЬ ВЕТЕРИНАРОВ (APPLE ULTRA-SLIM) --- */
aside[style*="width: 240px"] {
    width: 260px !important;
    background: rgba(255, 255, 255, 0.02) !important;
    border: 1px solid rgba(255, 255, 255, 0.05) !important;
    backdrop-filter: blur(20px) !important;
    border-radius: var(--radius-lg) !important;
    padding: 20px !important;
}

/* Сверхтонкие стеклянные плашки перетаскивания */
.calStaffDrag {
    background: rgba(255, 255, 255, 0.02) !important;
    border: 1px solid rgba(255, 255, 255, 0.04) !important;
    border-radius: var(--radius-md) !important;
    padding: 10px 14px !important;
    margin-bottom: 8px !important;
    box-shadow: none !important;
    display: flex;
    flex-direction: column;
    justify-content: center;
}
.calStaffDrag:hover {
    background: rgba(255, 255, 255, 0.06) !important;
    border-color: rgba(255, 255, 255, 0.15) !important;
    transform: translateX(4px);
}
.calStaffDragName {
    color: #fff !important;
    font-size: 0.85rem !important;
    font-weight: 600 !important;
}
.calStaffDragRole {
    color: var(--text-muted) !important;
    font-size: 0.7rem !important;
}

/* --- КРАСИВЫЙ СИНХРОННЫЙ ВЕРХНИЙ СКРОЛЛБАР --- */
.calendar-top-scrollbar-container {
    width: 100%;
    overflow-x: auto;
    overflow-y: hidden;
    margin-bottom: 10px;
}
/* Скрываем сам пустой блок, оставляем только трек полосы */
.calendar-top-scrollbar-container::-webkit-scrollbar {
    height: 5px;
}
.calendar-top-scrollbar-container::-webkit-scrollbar-track {
    background: rgba(255, 255, 255, 0.01);
}
.calendar-top-scrollbar-container::-webkit-scrollbar-thumb {
    background: rgba(163, 97, 255, 0.2);
    border-radius: 10px;
}
.calendar-top-scrollbar-container::-webkit-scrollbar-thumb:hover {
    background: var(--primary-neon);
}
/* Растянутый верхний блок */
.owner-hero {
    display: flex;
    justify-content: space-between;
    background: linear-gradient(135deg, rgba(76, 29, 149, 0.2), rgba(15, 23, 42, 0.4));
    border: 1px solid rgba(255, 255, 255, 0.1);
    padding: 30px;
    border-radius: 20px;
    margin-bottom: 30px;
    width: 100%;
}

