/* ==============================================================
   ГЛОБАЛЬНЫЙ МАКОВСКИЙ DOCK СНИЗУ
============================================================== */
.mac-dock {
    position: fixed;
    bottom: 20px;
    left: 50%;
    transform: translateX(-50%);
    z-index: 9999;
    
    /* СТЕКЛО, КОТОРОЕ МЕНЯЕТСЯ С ТЕМОЙ */
    background: rgba(255, 255, 255, 0.05); 
    backdrop-filter: blur(25px);
    -webkit-backdrop-filter: blur(25px);
    
    /* Добавляем обводку, которая тоже может быть акцентной */
    border: 1px solid rgba(255, 255, 255, 0.15);
    border-radius: 28px;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
    
    padding: 8px 16px;
    transition: background 0.3s ease;
}
/* При наведении подсвечиваем активным цветом */
.dock-menu .menu-item.active {
    background: var(--accent-glow) !important;
    border: 1px solid var(--accent-color) !important;
    box-shadow: 0 0 15px var(--accent-glow) !important;
}

.dock-menu {
    display: flex;
    list-style: none;
    margin: 0;
    padding: 0;
    gap: 8px;
    align-items: center;
}

.dock-menu .menu-item {
    border-radius: 20px;
    transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
}

.dock-menu .menu-item a {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 10px 18px;
    color: rgba(255, 255, 255, 0.5);
    text-decoration: none;
    font-size: 0.95rem;
    font-weight: 500;
    transition: all 0.2s ease;
}

.dock-menu .menu-item a .dock-icon {
    font-size: 1.2rem;
}

/* Эффекты наведения (Hover) */
.dock-menu .menu-item:hover {
    background: rgba(255, 255, 255, 0.08);
    transform: translateY(-2px);
}
.dock-menu .menu-item:hover a {
    color: #fff;
}

/* Активная вкладка */
.dock-menu .menu-item.active {
    background: rgba(168, 85, 247, 0.25);
    border: 1px solid rgba(168, 85, 247, 0.4);
    box-shadow: 0 0 15px rgba(168, 85, 247, 0.3);
}

.dock-menu .menu-item.active a {
    color: #fff;
    font-weight: 600;
}

/* Адаптация под телефоны */
@media (max-width: 768px) {
    .mac-dock {
        width: 90vw;
        padding: 6px 10px;
        bottom: 12px;
    }
    .dock-menu {
        justify-content: space-between;
        width: 100%;
        gap: 4px;
    }
    .dock-menu .menu-item a {
        padding: 12px;
        flex-direction: column;
        gap: 4px;
        font-size: 0.7rem;
    }
    .dock-menu .menu-item a .dock-text {
        display: none; /* Прячем текст на узких экранах, оставляем только иконки */
    }
    .dock-menu .menu-item a .dock-icon {
        font-size: 1.4rem;
    }
}
/* ==============================================================
   ДИНАМИЧЕСКИЕ ТЕМЫ ЧЕРЕЗ CSS-ПЕРЕМЕННЫЕ
============================================================== */

/* Дефолтная фиолетовая тема */
:root, body[data-theme="purple"] {
    --accent-color: #a855f7;
    --accent-glow: rgba(168, 85, 247, 0.4);
    --bg-gradient: linear-gradient(135deg, #130b2b 0%, #070412 100%);
    --card-bg: rgba(255, 255, 255, 0.02);
    --text-main: #ffffff;
}

/* Глубокая черная тема (OLED Black) */
body[data-theme="black"] {
    --accent-color: #f43f5e; /* Малиново-неоновый акцент */
    --accent-glow: rgba(244, 63, 94, 0.4);
    --bg-gradient: linear-gradient(180deg, #000000 0%, #09090b 100%);
    --card-bg: rgba(255, 255, 255, 0.01);
    --text-main: #f4f4f5;
}

/* Чистая белая тема (Светлый матовый VisionOS) */
/* --- БЕЛАЯ ТЕМА (iOS WATER GLASS STYLE) --- */
body[data-theme="white"] {
    --accent-color: #5856d6;
    --accent-glow: rgba(88, 86, 214, 0.2);
    --bg-gradient: #f2f2f7; /* Светлый iOS фон */
    --card-bg: rgba(255, 255, 255, 0.7); /* Полупрозрачность для эффекта воды */
    --text-main: #1c1c1e; /* Темно-серый текст Apple */
    --text-muted: #8e8e93;
    --input-bg: rgba(0, 0, 0, 0.05);
    --glass-border: rgba(0, 0, 0, 0.1);
}

/* --- СТЕКЛЯННЫЕ КАРТОЧКИ (VisionOS/iOS Style) --- */
.glass-card {
    background: var(--card-bg) !important;
    backdrop-filter: blur(20px) saturate(180%);
    -webkit-backdrop-filter: blur(20px) saturate(180%);
    border: 1px solid var(--glass-border) !important;
    border-radius: 20px;
    padding: 24px;
    color: var(--text-main) !important;
    box-shadow: 0 8px 30px rgba(0,0,0,0.04);
}

/* Сделаем Dock таким же "водянистым" */
.mac-dock {
    background: rgba(255, 255, 255, 0.6) !important;
    backdrop-filter: blur(30px) saturate(180%);
    -webkit-backdrop-filter: blur(30px) saturate(180%);
    border: 1px solid rgba(0,0,0,0.1) !important;
    box-shadow: 0 10px 30px rgba(0,0,0,0.1);
}

/* Неоновая синяя тема */
body[data-theme="blue"] {
    --accent-color: #06b6d4;
    --accent-glow: rgba(6, 182, 212, 0.4);
    --bg-gradient: linear-gradient(135deg, #041d30 0%, #020b14 100%);
    --card-bg: rgba(255, 255, 255, 0.02);
    --text-main: #ffffff;
}

/* Смарагдовая зеленая тема */
body[data-theme="green"] {
    --accent-color: #10b981;
    --accent-glow: rgba(16, 185, 129, 0.4);
    --bg-gradient: linear-gradient(135deg, #021e17 0%, #020a07 100%);
    --card-bg: rgba(255, 255, 255, 0.02);
    --text-main: #ffffff;
}

/* Привязываем глобальный фон к переменным */
body {
    background: var(--bg-gradient);
    color: var(--text-main);
    transition: background 0.5s ease, color 0.3s ease;
}

/* Элементы управления в настройках */
.theme-picker-container {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.theme-btn-pill {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px 16px;
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 12px;
    color: #fff;
    font-size: 0.95rem;
    font-weight: 500;
    cursor: pointer;
    text-align: left;
    transition: all 0.2s ease;
}

.theme-btn-pill:hover {
