/* Премиум Экран Входа */
.auth-overlay {
  position: fixed;
  top: 0; left: 0; width: 100vw; height: 100vh;
  background: radial-gradient(circle at 50% 50%, rgba(88, 28, 135, 0.4) 0%, rgba(15, 23, 42, 0.95) 100%);
  z-index: 999999;
  display: flex; align-items: center; justify-content: center;
  backdrop-filter: blur(20px); -webkit-backdrop-filter: blur(20px);
}

.auth-glass-panel {
  display: flex;
  width: 800px; max-width: 90vw; height: 480px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(168, 85, 247, 0.2);
  border-radius: 28px;
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.6), inset 0 1px 1px rgba(255, 255, 255, 0.1);
  overflow: hidden;
}

.auth-art-zone {
  flex: 1;
  background: linear-gradient(135deg, rgba(147, 51, 234, 0.2), rgba(0, 0, 0, 0.3));
  border-right: 1px solid rgba(255, 255, 255, 0.05);
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  padding: 40px; position: relative;
}

.pug-digital-avatar {
  font-size: 5rem;
  filter: drop-shadow(0 0 20px rgba(168, 85, 247, 0.6));
  animation: floatAnim 4s ease-in-out infinite;
}

.pug-bubble {
  margin-top: 24px;
  background: rgba(255, 255, 255, 0.06);
  padding: 12px 18px; border-radius: 16px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  color: rgba(255, 255, 255, 0.85);
  font-size: 0.9rem; text-align: center; line-height: 1.4;
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.2);
}

.auth-form-zone {
  width: 420px; padding: 44px;
  display: flex; flex-direction: column; justify-content: center;
}

.auth-header h1 {
  font-size: 1.8rem; margin: 0; color: #fff; font-weight: 700;
}
.auth-header h1 span { color: #c084fc; }
.auth-header p {
  margin: 6px 0 28px 0; font-size: 0.9rem; color: rgba(255, 255, 255, 0.5);
}

.auth-field {
  display: flex; flex-direction: column; gap: 6px; margin-bottom: 20px;
}
.auth-field label {
  font-size: 0.8rem; font-weight: 600; color: rgba(255, 255, 255, 0.6); text-transform: uppercase; letter-spacing: 0.5px;
}
.auth-field input {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  padding: 12px 16px; border-radius: 12px;
  color: #fff; font-size: 1rem; transition: all 0.2s ease;
}
.auth-field input:focus {
  outline: none; border-color: #c084fc; background: rgba(255, 255, 255, 0.08);
  box-shadow: 0 0 15px rgba(168, 85, 247, 0.2);
}

.auth-submit-btn {
  width: 100%; padding: 14px; background: #9333ea;
  color: #fff; border: none; border-radius: 12px;
  font-size: 1rem; font-weight: 600; cursor: pointer;
  transition: all 0.25s ease;
  box-shadow: 0 4px 20px rgba(147, 51, 234, 0.3);
}
.auth-submit-btn:hover {
  background: #a855f7; transform: translateY(-1px);
  box-shadow: 0 6px 25px rgba(147, 51, 234, 0.5);
}

.auth-error-msg {
  background: rgba(239, 68, 68, 0.15); border: 1px solid rgba(239, 68, 68, 0.3);
  color: #f87171; padding: 10px 14px; border-radius: 10px;
  font-size: 0.85rem; margin-bottom: 20px; font-weight: 500;
}

@keyframes floatAnim {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-10px); }
}
