/* =======================================================
   DOC.PUG — PREMIUM VISIT MODAL V2
======================================================= */

.pugVisitOverlay.open {
  display: flex !important;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background:
    radial-gradient(circle at 20% 15%, rgba(168, 85, 247, 0.2), transparent 28%),
    radial-gradient(circle at 82% 70%, rgba(124, 58, 237, 0.22), transparent 30%),
    rgba(5, 3, 14, 0.72) !important;
  backdrop-filter: blur(28px) saturate(170%);
  -webkit-backdrop-filter: blur(28px) saturate(170%);
}

.pugVisitModal {
  width: min(1180px, 94vw);
  max-height: 92vh;
  overflow: hidden;
  border-radius: 30px;
  padding: 28px;
  background:
    linear-gradient(135deg, rgba(49, 35, 82, 0.92), rgba(17, 12, 35, 0.94)),
    radial-gradient(circle at top left, rgba(168, 85, 247, 0.22), transparent 35%);
  border: 1px solid rgba(196, 181, 253, 0.22);
  box-shadow:
    0 30px 100px rgba(0, 0, 0, 0.58),
    0 0 70px rgba(168, 85, 247, 0.16),
    inset 0 1px 0 rgba(255, 255, 255, 0.12);
  color: #fff;
  animation: pugVisitPop 0.24s ease both;
}

@keyframes pugVisitPop {
  from {
    opacity: 0;
    transform: translateY(14px) scale(0.97);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

/* Header */

.pugVisitHead {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 18px;
  margin-bottom: 22px;
}

.pugVisitHeadLeft {
  display: flex;
  align-items: center;
  gap: 16px;
}

.pugVisitIcon {
  width: 54px;
  height: 54px;
  border-radius: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.55rem;
  background: linear-gradient(135deg, #a855f7, #6d28d9);
  box-shadow: 0 0 28px rgba(168, 85, 247, 0.55);
}

.pugVisitTitle {
  font-size: 2rem;
  font-weight: 850;
  letter-spacing: -0.04em;
  line-height: 1.05;
}

.pugVisitSub {
  margin-top: 6px;
  font-size: 0.98rem;
  color: rgba(233, 213, 255, 0.68);
}

.pugVisitClose {
  width: 52px;
  height: 52px;
  border-radius: 14px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: #fff;
  background: rgba(255, 255, 255, 0.055);
  font-size: 2rem;
  line-height: 1;
  cursor: pointer;
  transition: 0.2s ease;
}

.pugVisitClose:hover {
  background: rgba(255, 255, 255, 0.11);
  border-color: rgba(196, 181, 253, 0.35);
  transform: translateY(-1px);
}

/* Body layout */

.pugVisitBody {
  display: grid;
  grid-template-columns: minmax(360px, 0.95fr) minmax(420px, 1fr);
  gap: 16px;
  max-height: calc(92vh - 170px);
  overflow: auto;
  padding-right: 6px;
}

.pugVisitBody::-webkit-scrollbar,
.pugPatientResults::-webkit-scrollbar {
  width: 8px;
}

.pugVisitBody::-webkit-scrollbar-thumb,
.pugPatientResults::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: rgba(168, 85, 247, 0.35);
}

.pugVisitSection {
  border-radius: 22px;
  padding: 20px;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.055), rgba(255, 255, 255, 0.025));
  border: 1px solid rgba(255, 255, 255, 0.105);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.07),
    0 10px 34px rgba(0, 0, 0, 0.18);
}

.pugVisitPatientBlock {
  border-color: rgba(168, 85, 247, 0.38);
  box-shadow:
    0 0 0 1px rgba(168, 85, 247, 0.08),
    0 16px 45px rgba(0, 0, 0, 0.2);
}

.pugVisitMedicalBlock {
  grid-column: 1 / -1;
}

.pugSectionTitle {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 16px;
  font-size: 1.15rem;
  color: #fff;
}

.pugSectionTitle span {
  color: #c084fc;
  filter: drop-shadow(0 0 10px rgba(168, 85, 247, 0.5));
}

.pugSectionTitle strong {
  font-weight: 850;
  letter-spacing: -0.02em;
}

/* Fields */

.pugVisitFieldsGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
}

.pugVisitField {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.pugVisitField > span {
  color: rgba(237, 233, 254, 0.72);
  font-size: 0.88rem;
  font-weight: 650;
}

.pugVisitInput {
  width: 100%;
  min-height: 48px;
  border-radius: 14px;
  border: 1px solid rgba(196, 181, 253, 0.16);
  background: rgba(10, 7, 25, 0.36);
  color: #fff;
  padding: 12px 14px;
  font-size: 0.96rem;
  outline: none;
  transition: 0.2s ease;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.045);
}

.pugVisitInput::placeholder {
  color: rgba(233, 213, 255, 0.38);
}

.pugVisitInput:focus {
  border-color: rgba(168, 85, 247, 0.78);
  background: rgba(20, 13, 42, 0.55);
  box-shadow:
    0 0 0 4px rgba(168, 85, 247, 0.13),
    0 0 22px rgba(168, 85, 247, 0.13),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

.pugVisitTextarea {
  resize: vertical;
  min-height: 92px;
  line-height: 1.45;
}

/* Search */

.pugSearchWrap {
  position: relative;
}

.pugSearchIcon {
  position: absolute;
  left: 15px;
  top: 50%;
  transform: translateY(-50%);
  color: rgba(233, 213, 255, 0.56);
  z-index: 1;
}

.pugVisitSearch {
  padding-left: 42px;
}

.pugPatientResults {
  margin-top: 14px;
  max-height: 280px;
  overflow: auto;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.pugPatientResults .hint {
  padding: 14px;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.035);
  border: 1px solid rgba(255, 255, 255, 0.06);
}

/* Patient result cards */

.patientSearchItem {
  display: flex !important;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 14px 15px !important;
  border-radius: 18px !important;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.075), rgba(255, 255, 255, 0.035)) !important;
  border: 1px solid rgba(255, 255, 255, 0.09) !important;
  color: #fff !important;
  cursor: pointer;
  transition: 0.2s ease;
  position: relative;
  overflow: hidden;
}

.patientSearchItem::before {
  content: "🐾";
