}

.patientSearchItem:hover {
  transform: translateY(-2px);
  border-color: rgba(168, 85, 247, 0.55) !important;
  background:
    linear-gradient(135deg, rgba(168, 85, 247, 0.18), rgba(255, 255, 255, 0.055)) !important;
  box-shadow: 0 16px 34px rgba(0, 0, 0, 0.22);
}

.patientSearchItem strong {
  display: block;
  font-size: 1rem;
  font-weight: 850;
  color: #fff;
}

.patientSearchItem span {
  display: block;
  margin-top: 4px;
