  color: rgba(233, 213, 255, 0.68);
}

.pugAddPatientBtn {
  width: 100%;
  min-height: 46px;
  margin-top: 12px;
  border-radius: 15px;
  border: 1px dashed rgba(168, 85, 247, 0.55);
  background: rgba(168, 85, 247, 0.065);
  color: #c084fc;
  font-size: 0.98rem;
  font-weight: 800;
  cursor: pointer;
  transition: 0.2s ease;
}

.pugAddPatientBtn:hover {
