  box-shadow: 0 0 22px rgba(168, 85, 247, 0.16);
}
/* =======================================================
   DOC.PUG — PREMIUM VISIT MODAL V2 / PART 2
======================================================= */

.pugVisitMedicalGrid {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr 0.45fr;
  gap: 18px;
  align-items: start;
}

.pugFieldWide {
  grid-row: span 2;
}

.pugFieldWideRight {
  grid-column: 2 / -1;
}

.pugVisitFoot {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 14px;
  margin-top: 18px;
