}

.pugVisitSave:hover {
  transform: translateY(-2px);
  filter: brightness(1.08);
  box-shadow:
    0 0 38px rgba(168, 85, 247, 0.52),
    0 18px 42px rgba(124, 58, 237, 0.36),
    inset 0 1px 0 rgba(255, 255, 255, 0.22);
}

/* Date/time native controls polish */

.pugVisitInput[type="date"],
.pugVisitInput[type="time"],
.pugVisitInput select {
  color-scheme: dark;
}

.pugVisitInput::-webkit-calendar-picker-indicator {
  filter: invert(1);
  opacity: 0.75;
  cursor: pointer;
}

/* Better select look */

select.pugVisitInput {
  appearance: none;
  -webkit-appearance: none;
  background-image:
    linear-gradient(45deg, transparent 50%, rgba(233, 213, 255, 0.8) 50%),
    linear-gradient(135deg, rgba(233, 213, 255, 0.8) 50%, transparent 50%);
  background-position:
    calc(100% - 20px) 22px,
    calc(100% - 14px) 22px;
  background-size: 6px 6px, 6px 6px;
  background-repeat: no-repeat;
  padding-right: 42px;
}

select.pugVisitInput option {
  background: #171027;
  color: #fff;
}

/* Cleaner fallback for old modal globals */

#visitModal.modal-overlay.open,
#visitModal.modal.open {
  display: flex !important;
}

#visitModal:not(.open) {
  display: none !important;
}

/* Patient block hidden/open still controlled by JS */

#visitPatientBlock[style*="display: block"] {
  display: block !important;
}

/* Small selected visual polish */

#visitPatientSearch:not(:placeholder-shown) {
  border-color: rgba(168, 85, 247, 0.55);
}

/* Soft inner separators */

.pugVisitDetailsBlock,
.pugVisitMedicalBlock {
  position: relative;
}

.pugVisitDetailsBlock::after,
.pugVisitMedicalBlock::after {
  content: "";
  position: absolute;
  inset: 1px;
  border-radius: inherit;
  pointer-events: none;
  background: linear-gradient(
    135deg,
    rgba(255, 255, 255, 0.08),
    transparent 32%,
    rgba(168, 85, 247, 0.045)
  );
  opacity: 0.7;
}

/* White / iOS theme support */

body[data-theme="white"] .pugVisitOverlay.open {
  background:
    radial-gradient(circle at 18% 12%, rgba(0, 122, 255, 0.16), transparent 28%),
    radial-gradient(circle at 84% 74%, rgba(88, 86, 214, 0.14), transparent 32%),
    rgba(235, 239, 247, 0.72) !important;
}

body[data-theme="white"] .pugVisitModal {
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.82), rgba(236, 240, 248, 0.78)) !important;
  color: #1c1c1e !important;
  border-color: rgba(255, 255, 255, 0.92) !important;
  box-shadow:
    0 30px 90px rgba(0, 0, 0, 0.16),
    inset 0 1px 0 rgba(255, 255, 255, 1) !important;
}

body[data-theme="white"] .pugVisitTitle,
body[data-theme="white"] .pugSectionTitle,
body[data-theme="white"] .pugSectionTitle strong,
body[data-theme="white"] .patientSearchItem strong {
  color: #1c1c1e !important;
}

body[data-theme="white"] .pugVisitSub,
body[data-theme="white"] .pugVisitField > span,
body[data-theme="white"] .patientSearchItem span {
  color: #6e6e73 !important;
}

body[data-theme="white"] .pugVisitSection,
body[data-theme="white"] .patientSearchItem {
  background: rgba(255, 255, 255, 0.58) !important;
  border-color: rgba(255, 255, 255, 0.9) !important;
}

body[data-theme="white"] .pugVisitInput {
  background: rgba(255, 255, 255, 0.72) !important;
  border-color: rgba(0, 0, 0, 0.08) !important;
  color: #1c1c1e !important;
}

body[data-theme="white"] .pugVisitInput::placeholder {
  color: rgba(60, 60, 67, 0.35) !important;
}

body[data-theme="white"] .pugVisitClose,
body[data-theme="white"] .pugVisitCancel {
  background: rgba(255, 255, 255, 0.65) !important;
  color: #1c1c1e !important;
  border-color: rgba(0, 0, 0, 0.08) !important;
}

/* Responsive */

@media (max-width: 980px) {
  .pugVisitModal {
    width: 96vw;
    padding: 20px;
    border-radius: 24px;
  }

  .pugVisitBody {
    grid-template-columns: 1fr;
    max-height: calc(92vh - 160px);
  }

  .pugVisitMedicalBlock {
    grid-column: auto;
  }

  .pugVisitMedicalGrid {
    grid-template-columns: 1fr;
  }

  .pugFieldWide,
  .pugFieldWideRight {
    grid-column: auto;
    grid-row: auto;
  }

  .pugVisitFoot {
    flex-direction: column-reverse;
  }

  .pugVisitCancel,
  .pugVisitSave {
    width: 100%;
  }
}

@media (max-width: 620px) {
  .pugVisitOverlay.open {
    padding: 10px;
  }

  .pugVisitHead {
    align-items: center;
  }

  .pugVisitIcon {
    width: 46px;
    height: 46px;
    font-size: 1.25rem;
  }

  .pugVisitTitle {
    font-size: 1.45rem;
  }

  .pugVisitFieldsGrid {
    grid-template-columns: 1fr;
  }

  .pugVisitClose {
    width: 44px;
    height: 44px;
  }
}
