/* =======================================================
   DOC.PUG — MONTH CALENDAR
======================================================= */

.monthWeekHead {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 10px;
  margin: 18px 0 10px;
}

.monthWeekHead div {
  color: var(--text-muted, rgba(255,255,255,.55));
  font-weight: 800;
  font-size: .85rem;
  text-align: center;
  text-transform: uppercase;
}

.monthGrid {
  display: grid;
  grid-template-columns: repeat(7, minmax(130px, 1fr));
  gap: 10px;
}

.monthDay {
  min-height: 150px;
  border-radius: 18px;
  padding: 12px;
  background: rgba(255,255,255,.035);
  border: 1px solid rgba(255,255,255,.08);
