  transition: .2s ease;
  overflow: hidden;
}

.monthDay:hover {
  transform: translateY(-2px);
  border-color: var(--accent-color, #a855f7);
  background: color-mix(in srgb, var(--accent-color) 10%, rgba(255,255,255,.04));
  box-shadow: 0 12px 30px rgba(0,0,0,.22);
}

.monthDay.muted {
  opacity: .35;
}

.monthDay.today {
  border-color: var(--accent-color, #a855f7);
  box-shadow: 0 0 0 1px var(--accent-glow, rgba(168,85,247,.3));
}

.monthDayTop {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 10px;
}

.monthDayNum {
  width: 30px;
  height: 30px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 900;
  color: var(--text-main, #fff);
  background: rgba(255,255,255,.055);
}

.monthVisitCount {
  font-size: .72rem;
  color: var(--accent-color, #a855f7);
