/* Patients: honest loading state while the clinic data is requested. */
.patientsTabLoading {
  min-height: 280px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 48px 24px;
  text-align: center;
  color: var(--text-main);
  border: 1px solid var(--glass-border);
  border-radius: 18px;
  background:
    radial-gradient(
      circle at 50% 15%,
      var(--accent-glow),
      transparent 48%
    ),
    var(--glass-bg);
}

.patientsTabLoadingIcon {
  width: 64px;
  height: 64px;
  display: grid;
  place-items: center;
  margin-bottom: 6px;
  border: 1px solid var(--glass-border);
  border-radius: 20px;
  background: var(--accent-glow);
  box-shadow: 0 14px 40px var(--accent-glow);
  font-size: 28px;
  animation: patientsLoadingFloat 1.8s ease-in-out infinite;
}

.patientsTabLoading strong {
  font-size: 18px;
  letter-spacing: -.01em;
}

.patientsTabLoading > span {
  color: var(--text-muted);
  font-size: 13px;
}

.patientsTabLoadingDots {
  display: flex;
  gap: 6px;
  margin-top: 10px;
}

.patientsTabLoadingDots i {
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: var(--accent-color);
  animation: patientsLoadingDot 1.1s ease-in-out infinite;
}

.patientsTabLoadingDots i:nth-child(2) {
  animation-delay: .14s;
}

.patientsTabLoadingDots i:nth-child(3) {
  animation-delay: .28s;
}

@keyframes patientsLoadingFloat {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-6px); }
}

@keyframes patientsLoadingDot {
  0%, 60%, 100% {
    opacity: .32;
    transform: translateY(0);
  }
  30% {
    opacity: 1;
    transform: translateY(-4px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .patientsTabLoadingIcon,
  .patientsTabLoadingDots i {
    animation: none;
  }
}
