.addPetModalOverlay {
  position: fixed;
  inset: 0;
  z-index: 100000;

  display: flex;
  align-items: center;
  justify-content: center;

  padding: 24px;

  background:
    radial-gradient(
      circle at 50% 15%,
      rgba(130, 71, 255, 0.17),
      transparent 40%
    ),
    rgba(3, 2, 11, 0.82);

  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);

  opacity: 0;
  visibility: hidden;

  transition:
    opacity 0.22s ease,
    visibility 0.22s ease;
}

.addPetModalOverlay.is-open {
  opacity: 1;
  visibility: visible;
}

.addPetModal {
  position: relative;

  width: min(680px, 100%);
  max-height: calc(100vh - 48px);
  overflow: auto;

  padding: 32px;

  color: #f8f6ff;

  background:
    linear-gradient(
      145deg,
      rgba(25, 22, 43, 0.985),
      rgba(11, 9, 23, 0.995)
    );

  border: 1px solid rgba(175, 148, 255, 0.22);
  border-radius: 28px;

  box-shadow:
    0 40px 120px rgba(0, 0, 0, 0.72),
    0 0 0 1px rgba(255, 255, 255, 0.025) inset,
    0 0 90px rgba(124, 71, 255, 0.13);

  transform: translateY(22px) scale(0.97);

  transition:
    transform 0.26s cubic-bezier(.2, .8, .2, 1);
}

.addPetModalOverlay.is-open .addPetModal {
  transform: translateY(0) scale(1);
}

.addPetModal::-webkit-scrollbar {
  width: 6px;
}

.addPetModal::-webkit-scrollbar-thumb {
  background: rgba(151, 109, 255, 0.36);
  border-radius: 999px;
}

.addPetModalGlow {
  position: absolute;
  border-radius: 50%;
  filter: blur(65px);
  pointer-events: none;
}

.addPetModalGlowOne {
  top: -140px;
  right: -120px;

  width: 300px;
  height: 300px;

  background: rgba(147, 76, 255, 0.19);
}

.addPetModalGlowTwo {
  bottom: -180px;
  left: -160px;

  width: 310px;
  height: 310px;

  background: rgba(83, 47, 194, 0.11);
}

.addPetModalHeader {
  position: relative;
  z-index: 1;

  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 24px;

  margin-bottom: 26px;
}

.addPetModalKicker {
  margin-bottom: 8px;

  color: #a985ff;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.18em;
}

.addPetModalHeader h2 {
  margin: 0;

  color: #ffffff;
  font-size: 32px;
  font-weight: 850;
  line-height: 1.05;
  letter-spacing: -0.045em;
}

.addPetModalHeader p {
  max-width: 480px;
  margin: 10px 0 0;

  color: rgba(229, 222, 246, 0.53);
  font-size: 14px;
  line-height: 1.5;
}

.addPetModalClose {
  flex: 0 0 auto;

  width: 42px;
  height: 42px;

  display: grid;
  place-items: center;

  color: rgba(255, 255, 255, 0.67);
  font-size: 26px;
  line-height: 1;

  background: rgba(255, 255, 255, 0.045);
  border: 1px solid rgba(255, 255, 255, 0.075);
  border-radius: 14px;

  cursor: pointer;

  transition:
    color 0.18s ease,
    background 0.18s ease,
    border-color 0.18s ease,
    transform 0.18s ease;
}

.addPetModalClose:hover {
  color: #ffffff;

  background: rgba(145, 87, 255, 0.14);
  border-color: rgba(164, 112, 255, 0.36);

  transform: rotate(5deg);
}

.addPetModalForm {
