  border-radius: 18px;

  cursor: pointer;

  transition:
    color 0.18s ease,
    transform 0.18s ease,
    background 0.18s ease,
    border-color 0.18s ease,
    box-shadow 0.18s ease;
}

.addPetSpeciesButton:hover {
  color: #ffffff;
  border-color: rgba(164, 116, 255, 0.37);
  transform: translateY(-2px);
}

.addPetSpeciesButton.is-active {
  color: #ffffff;

  background:
    linear-gradient(
      135deg,
      rgba(126, 76, 255, 0.29),
      rgba(178, 80, 255, 0.105)
    );

  border-color: rgba(173, 114, 255, 0.85);

  box-shadow:
    0 0 0 3px rgba(134, 79, 255, 0.09),
    0 15px 35px rgba(82, 35, 171, 0.17);
}

.addPetSpeciesEmoji {
  width: 46px;
  height: 46px;
  flex: 0 0 auto;

  display: grid;
  place-items: center;

  font-size: 24px;

  background: rgba(255, 255, 255, 0.055);
  border: 1px solid rgba(255, 255, 255, 0.055);
  border-radius: 14px;
}

.addPetSpeciesButton.is-active .addPetSpeciesEmoji {
  background: rgba(140, 84, 255, 0.22);
}

.addPetSpeciesInfo {
