/* =========================================================
   ПРИМЕНЕНИЕ ПЕРЕМЕННЫХ
   ========================================================= */

.addPetModalOverlay {
  overflow: hidden;

  background:
    radial-gradient(
      circle at 50% 12%,
      var(--pet-modal-accent-soft),
      transparent 42%
    ),
    var(--pet-modal-overlay);
}

.addPetModal {
  overflow-x: hidden;

  color: var(--pet-modal-text);

  background:
    linear-gradient(
      145deg,
      var(--pet-modal-bg-1),
      var(--pet-modal-bg-2)
    );

  border-color: var(--pet-modal-strong-border);

  box-shadow:
    0 40px 120px var(--pet-modal-shadow),
    0 0 0 1px rgba(255, 255, 255, 0.025) inset,
    0 0 90px var(--pet-modal-accent-soft);
}

.addPetModalGlowOne {
  background: var(--pet-modal-accent-soft);
}

.addPetModalGlowTwo {
  background: var(--pet-modal-accent-soft);
  opacity: 0.55;
}

.addPetModalKicker {
  color: var(--pet-modal-accent);
}

.addPetModalHeader h2 {
  color: var(--pet-modal-text);
}

.addPetModalHeader p {
  color: var(--pet-modal-text-soft);
}

.addPetModalClose {
  color: var(--pet-modal-text-soft);
  background: var(--pet-modal-surface);
  border-color: var(--pet-modal-border);
}

.addPetModalClose:hover {
  color: var(--pet-modal-text);
  background: var(--pet-modal-accent-soft);
  border-color: var(--pet-modal-accent-border);
}

.addPetLabel {
  color: var(--pet-modal-text);
}

.addPetLabel b {
  color: var(--pet-modal-accent);
}

.addPetLabel small {
  color: var(--pet-modal-text-muted);
}

.addPetInputIcon {
  color: var(--pet-modal-accent);
}

.addPetInput,
.addPetTextarea {
  color: var(--pet-modal-text);

  background:
    linear-gradient(
      180deg,
      var(--pet-modal-surface),
      color-mix(in srgb, var(--pet-modal-surface) 55%, transparent)
    );

  border-color: var(--pet-modal-border);
}

.addPetInput::placeholder,
.addPetTextarea::placeholder {
  color: var(--pet-modal-text-muted);
}

.addPetInput:hover,
.addPetTextarea:hover {
  border-color: var(--pet-modal-accent-border);
}

.addPetInput:focus,
.addPetTextarea:focus {
  background: var(--pet-modal-accent-soft);
  border-color: var(--pet-modal-accent);

  box-shadow:
    0 0 0 4px var(--pet-modal-focus-ring),
    0 12px 35px rgba(0, 0, 0, 0.14);
}

.addPetSpeciesButton {
  color: var(--pet-modal-text-soft);

  background:
    linear-gradient(
      155deg,
      var(--pet-modal-surface),
      color-mix(in srgb, var(--pet-modal-surface) 45%, transparent)
    );

  border-color: var(--pet-modal-border);
}

.addPetSpeciesButton:hover {
  color: var(--pet-modal-text);
  background: var(--pet-modal-surface-hover);
  border-color: var(--pet-modal-accent-border);
}

.addPetSpeciesButton.is-active {
  color: var(--pet-modal-text);

  background:
    linear-gradient(
      135deg,
      var(--pet-modal-accent-soft),
      color-mix(in srgb, var(--pet-modal-accent-soft) 45%, transparent)
    );

  border-color: var(--pet-modal-accent);

  box-shadow:
    0 0 0 3px var(--pet-modal-focus-ring),
    0 15px 35px rgba(0, 0, 0, 0.16);
}

.addPetSpeciesEmoji {
  background: var(--pet-modal-surface);
  border-color: var(--pet-modal-border);
}

.addPetSpeciesButton.is-active .addPetSpeciesEmoji {
  background: var(--pet-modal-accent-soft);
}

.addPetSpeciesInfo strong {
  color: inherit;
}

.addPetSpeciesInfo small {
  color: var(--pet-modal-text-muted);
}

.addPetSpeciesCheck {
  color: #ffffff;
  background: var(--pet-modal-accent);
}

.addPetWeightWrap > span,
.addPetNotesCounter {
  color: var(--pet-modal-text-muted);
}

.addPetModalActions {
  border-top-color: var(--pet-modal-border);
}

.addPetCancelButton {
  color: var(--pet-modal-text-soft);
  background: var(--pet-modal-surface);
  border-color: var(--pet-modal-border);
}

.addPetCancelButton:hover {
  color: var(--pet-modal-text);
  background: var(--pet-modal-surface-hover);
}

.addPetSubmitButton {
  color: #ffffff;

  background:
    linear-gradient(
      135deg,
      var(--pet-modal-accent),
      var(--pet-modal-accent-2)
    );

  box-shadow:
    0 15px 34px
      color-mix(in srgb, var(--pet-modal-accent) 32%, transparent),
    0 1px 0 rgba(255, 255, 255, 0.27) inset;
}

.addPetSubmitButton:hover {
  box-shadow:
    0 19px 42px
      color-mix(in srgb, var(--pet-modal-accent) 44%, transparent),
    0 1px 0 rgba(255, 255, 255, 0.32) inset;
}

.addPetModal::-webkit-scrollbar-thumb {
  background: var(--pet-modal-accent-border);
}

/* Белая тема: более естественная тень и поля */

body[data-theme="white"] .addPetModal {
  box-shadow:
    0 35px 100px rgba(34, 27, 58, 0.28),
    0 0 0 1px rgba(255, 255, 255, 0.8) inset;
}

body[data-theme="white"] .addPetInput,
body[data-theme="white"] .addPetTextarea,
body[data-theme="white"] .addPetSpeciesButton {
  box-shadow: 0 1px 2px rgba(32, 24, 55, 0.03);
}

body[data-theme="white"] .addPetSubmitButton {
  color: #ffffff;
}

body[data-theme="white"] .addPetModalClose {
  box-shadow: 0 3px 12px rgba(42, 34, 70, 0.06);
}
/* =========================================================
   DOC.PUG — SPECIES + BREED COMBOBOX
   ========================================================= */

.addPetSpeciesSelector {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.addPetSpeciesButtonOther {
  grid-column: auto;
}

.addPetBreedCombobox {
  position: relative;
}

.addPetBreedField {
  position: relative;
}

.addPetBreedClear {
  position: absolute;
  top: 50%;
  right: 12px;
  z-index: 3;

  width: 28px;
  height: 28px;

  display: grid;
  place-items: center;

  color: var(--pet-modal-text-muted);
  font-size: 18px;
  line-height: 1;

  background: transparent;
  border: 0;
  border-radius: 9px;

  cursor: pointer;
  transform: translateY(-50%);

  transition:
    color 0.16s ease,
    background 0.16s ease;
}

.addPetBreedClear:hover {
  color: var(--pet-modal-text);
  background: var(--pet-modal-surface-hover);
}

.addPetBreedCombobox .addPetInput {
  padding-right: 48px;
}

.addPetBreedDropdown {
  position: absolute;
  top: calc(100% + 9px);
  left: 0;
  right: 0;
  z-index: 40;

  max-height: 310px;
  overflow-y: auto;

  padding: 8px;

  background:
    linear-gradient(
      145deg,
      var(--pet-modal-bg-1),
      var(--pet-modal-bg-2)
    );

  border: 1px solid var(--pet-modal-strong-border);
  border-radius: 17px;

  box-shadow:
    0 22px 60px var(--pet-modal-shadow),
    0 0 0 1px rgba(255, 255, 255, 0.025) inset;

  opacity: 0;
  visibility: hidden;
  transform: translateY(-7px) scale(0.985);

  transition:
    opacity 0.16s ease,
    visibility 0.16s ease,
    transform 0.16s ease;
}

.addPetBreedDropdown.is-open {
  opacity: 1;
  visibility: visible;
  transform: translateY(0) scale(1);
}

.addPetBreedDropdown::-webkit-scrollbar {
  width: 6px;
}

.addPetBreedDropdown::-webkit-scrollbar-thumb {
  background: var(--pet-modal-accent-border);
  border-radius: 999px;
}

.addPetBreedOption {
  width: 100%;
  min-height: 46px;
  padding: 9px 11px;

  display: flex;
  align-items: center;
  gap: 11px;

  color: var(--pet-modal-text-soft);
  text-align: left;

  background: transparent;
  border: 0;
  border-radius: 12px;

  cursor: pointer;

  transition:
    color 0.15s ease,
    background 0.15s ease,
    transform 0.15s ease;
}

.addPetBreedOption:hover {
  color: var(--pet-modal-text);
  background: var(--pet-modal-accent-soft);
  transform: translateX(2px);
}

.addPetBreedOption.is-selected {
  color: var(--pet-modal-text);
  background: var(--pet-modal-accent-soft);
}

.addPetBreedOptionIcon {
  width: 30px;
  height: 30px;
  flex: 0 0 auto;

  display: grid;
  place-items: center;

  background: var(--pet-modal-surface);
  border: 1px solid var(--pet-modal-border);
  border-radius: 10px;

  font-size: 14px;
}

.addPetBreedOption > span:nth-child(2) {
  flex: 1;
  font-size: 13px;
  font-weight: 700;
}

.addPetBreedOption b {
  color: var(--pet-modal-accent);
  font-size: 13px;
}

.addPetBreedEmpty {
  padding: 24px 18px;

  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;

  color: var(--pet-modal-text-soft);
  text-align: center;
}

.addPetBreedEmpty span {
  font-size: 13px;
  font-weight: 800;
}

.addPetBreedEmpty small {
  color: var(--pet-modal-text-muted);
  font-size: 11px;
}

.addPetBreedHint {
  margin-top: -2px;

  color: var(--pet-modal-text-muted);
  font-size: 11px;
  line-height: 1.4;
}

.addPetInput:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.addPetBreedField.is-other-species .addPetInputIcon {
  color: var(--pet-modal-accent);
}

body[data-theme="white"] .addPetBreedDropdown {
  box-shadow:
    0 22px 55px rgba(31, 24, 54, 0.2),
    0 0 0 1px rgba(255, 255, 255, 0.85) inset;
}

@media (max-width: 680px) {
  .addPetSpeciesSelector {
    grid-template-columns: 1fr 1fr;
  }

  .addPetSpeciesButtonOther {
    grid-column: 1 / -1;
  }

  .addPetSpeciesButtonOther {
    min-height: 66px;
  }

  .addPetBreedDropdown {
    max-height: 245px;
  }
}
.petDeleteBtn{
    width:30px;
    height:30px;

    display:flex;
    align-items:center;
    justify-content:center;

    background:rgba(255,255,255,.05);
    border:1px solid rgba(255,255,255,.08);
    border-radius:10px;

    color:#a8a8b3;
    cursor:pointer;

    transition:.18s;
}

.petDeleteBtn:hover{
    color:#ff6b81;
    background:rgba(255,80,80,.12);
    border-color:rgba(255,80,80,.35);

    transform:scale(1.08);
}

