.premiumVisitTimelineItem {
  position: relative;
  padding-left: 34px;
  margin-bottom: 18px;
}

.premiumVisitNode {
  position: absolute;
  top: 28px;
  left: 5px;
  z-index: 3;

  width: 14px;
  height: 14px;

  background:
    radial-gradient(
      circle,
      var(--accent-color, #a855f7) 0 35%,
      rgba(168, 85, 247, 0.22) 38% 100%
    );

  border: 2px solid
    color-mix(
      in srgb,
      var(--accent-color, #a855f7) 55%,
      white
    );

  border-radius: 50%;

  box-shadow:
    0 0 0 6px
      color-mix(
        in srgb,
        var(--accent-color, #a855f7) 10%,
        transparent
      ),
    0 0 18px
      color-mix(
        in srgb,
        var(--accent-color, #a855f7) 42%,
        transparent
      );
}

.premiumVisitCard {
  position: relative;
  overflow: hidden;

  padding: 26px;

  color: #ffffff;

  background:
    radial-gradient(
      circle at 100% 0%,
      color-mix(
        in srgb,
        var(--accent-color, #a855f7) 9%,
        transparent
      ),
      transparent 34%
    ),
    linear-gradient(
      145deg,
      rgba(28, 19, 51, 0.88),
      rgba(13, 10, 29, 0.94)
    );

  border: 1px solid rgba(255, 255, 255, 0.075);
  border-radius: 22px;

  box-shadow:
    0 16px 46px rgba(0, 0, 0, 0.24),
    inset 0 1px 0 rgba(255, 255, 255, 0.035);

  cursor: pointer;

  transition:
    transform 0.22s ease,
    border-color 0.22s ease,
    box-shadow 0.22s ease,
    background 0.22s ease;
}

.premiumVisitCard:hover {
  transform: translateY(-3px);

  border-color:
    color-mix(
      in srgb,
      var(--accent-color, #a855f7) 34%,
      transparent
    );

  box-shadow:
    0 24px 62px rgba(0, 0, 0, 0.34),
    0 0 32px
      color-mix(
        in srgb,
        var(--accent-color, #a855f7) 12%,
        transparent
      ),
    inset 0 1px 0 rgba(255, 255, 255, 0.05);
}

.premiumVisitCard:focus-visible {
  outline: none;

  box-shadow:
    0 0 0 3px
      color-mix(
        in srgb,
        var(--accent-color, #a855f7) 24%,
        transparent
      ),
    0 24px 62px rgba(0, 0, 0, 0.34);
}

.premiumVisitAccent {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;

  width: 4px;

  background:
    linear-gradient(
      180deg,
      var(--accent-color, #a855f7),
      color-mix(
        in srgb,
        var(--accent-color, #a855f7) 25%,
        transparent
      )
    );

  box-shadow:
    0 0 18px
      color-mix(
        in srgb,
        var(--accent-color, #a855f7) 40%,
        transparent
      );
}

.premiumVisitTop {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 24px;
}

.premiumVisitHeading {
  min-width: 0;
  flex: 1;
}

.premiumVisitEyebrow {
  display: inline-flex;
  align-items: center;
  gap: 7px;

  margin-bottom: 10px;

  color: rgba(231, 225, 244, 0.48);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.02em;
}

.premiumVisitDateIcon {
  display: inline-flex;
