  --med-overlay: rgba(1, 8, 15, 0.86);
  --med-window-start: rgba(8, 34, 47, 0.985);
  --med-window-end: rgba(3, 14, 23, 0.998);

  --med-surface: rgba(83, 205, 227, 0.04);
  --med-surface-hover: rgba(83, 205, 227, 0.07);
  --med-input: rgba(1, 10, 18, 0.3);

  --med-border: rgba(89, 209, 229, 0.1);
  --med-text: #f5fdff;
  --med-text-soft: rgba(224, 246, 250, 0.72);
  --med-text-muted: rgba(199, 232, 239, 0.4);

  --med-shadow: rgba(0, 10, 18, 0.76);
}

body[data-theme="green"] {
  --med-accent: var(--accent-color, #10b981);
  --med-accent-soft: rgba(16, 185, 129, 0.13);
  --med-accent-border: rgba(55, 211, 153, 0.34);

  --med-overlay: rgba(1, 11, 7, 0.87);
  --med-window-start: rgba(7, 39, 30, 0.985);
  --med-window-end: rgba(2, 17, 12, 0.998);

  --med-surface: rgba(71, 211, 153, 0.04);
  --med-surface-hover: rgba(71, 211, 153, 0.07);
  --med-input: rgba(1, 12, 8, 0.3);

  --med-border: rgba(92, 221, 169, 0.1);
  --med-text: #f4fff9;
  --med-text-soft: rgba(221, 246, 233, 0.72);
  --med-text-muted: rgba(190, 226, 207, 0.4);

  --med-shadow: rgba(0, 15, 9, 0.78);
}

body[data-theme="white"] {
  --med-accent: var(--accent-color, #007aff);
  --med-accent-soft: rgba(0, 122, 255, 0.09);
  --med-accent-border: rgba(0, 122, 255, 0.25);

  --med-overlay: rgba(27, 32, 44, 0.43);
  --med-window-start: rgba(255, 255, 255, 0.99);
  --med-window-end: rgba(240, 244, 250, 0.99);

  --med-surface: rgba(36, 42, 56, 0.028);
  --med-surface-hover: rgba(36, 42, 56, 0.05);
  --med-input: rgba(255, 255, 255, 0.72);

  --med-border: rgba(35, 40, 52, 0.09);
  --med-text: #1c1c1e;
  --med-text-soft: rgba(28, 28, 30, 0.68);
  --med-text-muted: rgba(60, 60, 67, 0.43);

  --med-shadow: rgba(26, 34, 53, 0.22);
}

/* ---------- Overlay ---------- */

.medcardModalOverlay {
  position: fixed !important;
  inset: 0 !important;
  z-index: 999999 !important;

  display: none !important;
  align-items: center !important;
  justify-content: center !important;

  padding: 24px !important;

  background:
    radial-gradient(
      circle at 20% 12%,
      var(--med-accent-soft),
      transparent 34%
    ),
    var(--med-overlay) !important;

  backdrop-filter: blur(24px) saturate(150%) !important;
  -webkit-backdrop-filter: blur(24px) saturate(150%) !important;
}

.medcardModalOverlay.open {
  display: flex !important;
}

.medcardModalBackdrop {
  position: absolute;
  inset: 0;
}

/* ---------- Window ---------- */

.medcardModalWindow {
  position: relative;
  z-index: 2;

  width: min(1180px, calc(100vw - 40px));
  max-height: calc(100vh - 40px);

  display: flex;
  flex-direction: column;

  overflow: hidden;

  color: var(--med-text);

  background:
    radial-gradient(
      circle at 100% 0%,
      var(--med-accent-soft),
      transparent 34%
    ),
    linear-gradient(
      145deg,
      var(--med-window-start),
      var(--med-window-end)
    );

  border: 1px solid var(--med-accent-border);
  border-radius: 30px;

  box-shadow:
    0 35px 110px var(--med-shadow),
    0 0 70px var(--med-accent-soft),
    inset 0 1px 0 rgba(255, 255, 255, 0.065);

  animation: medcardModalAppear 0.24s ease both;
}

@keyframes medcardModalAppear {
  from {
    opacity: 0;
    transform: translateY(14px) scale(0.975);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.medcardModalGlow {
  position: absolute;
  pointer-events: none;
  border-radius: 50%;
  filter: blur(70px);
  opacity: 0.38;
}

.medcardModalGlowOne {
  top: -110px;
  left: -80px;
  width: 260px;
  height: 260px;
  background: var(--med-accent-soft);
}

.medcardModalGlowTwo {
  right: -100px;
  bottom: -120px;
  width: 300px;
  height: 300px;
  background: var(--med-accent-soft);
}

/* ---------- Header ---------- */

.medcardModalHeader {
  position: relative;
  z-index: 2;

  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 22px;

  padding: 25px 27px 22px;

  border-bottom: 1px solid var(--med-border);
}

.medcardModalHeaderMain {
  display: flex;
  align-items: center;
  gap: 16px;
}

.medcardModalIcon {
  width: 52px;
  height: 52px;
  flex: 0 0 auto;

  display: grid;
  place-items: center;

  color: #ffffff;

  background:
    linear-gradient(
      135deg,
      var(--med-accent),
      color-mix(in srgb, var(--med-accent) 65%, #000)
    );

  border: 1px solid
    color-mix(in srgb, var(--med-accent) 45%, white);

  border-radius: 17px;

  box-shadow:
    0 12px 30px
      color-mix(in srgb, var(--med-accent) 28%, transparent),
    inset 0 1px 0 rgba(255, 255, 255, 0.22);
}

.medcardModalKicker {
  margin-bottom: 4px;

  color: var(--med-accent);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.13em;
}

.medcardModalHeader h2 {
  margin: 0;

  color: var(--med-text);
  font-size: 26px;
  font-weight: 900;
  line-height: 1.12;
  letter-spacing: -0.035em;
}

.medcardModalHeader p {
  max-width: 690px;
  margin: 7px 0 0;

  color: var(--med-text-soft);
  font-size: 13px;
  line-height: 1.45;
}

.medcardModalClose {
  width: 42px;
  height: 42px;
  flex: 0 0 auto;

  display: grid;
  place-items: center;

  color: var(--med-text-soft);

  background: var(--med-surface);
  border: 1px solid var(--med-border);
  border-radius: 14px;

  cursor: pointer;

  transition:
    color 0.18s ease,
    background 0.18s ease,
    border-color 0.18s ease,
    transform 0.18s ease;
}

.medcardModalClose:hover {
  color: var(--med-text);
  background: var(--med-accent-soft);
  border-color: var(--med-accent-border);
  transform: rotate(3deg);
}

/* ---------- Scroll/body ---------- */

.medcardModalScroll {
  position: relative;
  z-index: 2;

  overflow-y: auto;
  overscroll-behavior: contain;

  padding: 22px 27px 8px;

  scrollbar-width: thin;
  scrollbar-color: var(--med-accent-border) transparent;
}

.medcardModalScroll::-webkit-scrollbar {
  width: 7px;
}

.medcardModalScroll::-webkit-scrollbar-thumb {
  background: var(--med-accent-border);
  border-radius: 999px;
}

/* ---------- Sections ---------- */

.medcardFormSection {
  margin-bottom: 17px;
  padding: 19px;

  background:
    linear-gradient(
      145deg,
      var(--med-surface),
      color-mix(in srgb, var(--med-surface) 42%, transparent)
    );

  border: 1px solid var(--med-border);
  border-radius: 21px;

  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.025);
}

.medcardTreatmentSection {
  border-color:
    color-mix(
      in srgb,
      var(--med-accent) 22%,
      var(--med-border)
    );
}

.medcardSectionHeader {
  display: flex;
  align-items: center;
  gap: 12px;

  margin-bottom: 17px;
}

.medcardSectionIcon {
  width: 37px;
  height: 37px;
  flex: 0 0 auto;

  display: grid;
  place-items: center;

  color: var(--med-accent);

  background: var(--med-accent-soft);
  border: 1px solid var(--med-accent-border);
  border-radius: 13px;
}

.medcardSectionHeader h3 {
  margin: 0;

  color: var(--med-text);
  font-size: 15px;
  font-weight: 880;
}

.medcardSectionHeader p {
  margin: 3px 0 0;

  color: var(--med-text-muted);
  font-size: 11px;
}

/* ---------- Grids ---------- */

.medcardVitalsGrid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr 1fr;
  gap: 13px;
}

.medcardVitalsGrid .medcardFieldWide {
  grid-column: span 2;
}

.medcardStateGrid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 13px;
}

.medcardTextGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}

.medcardPlanGrid {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: 14px;
}

.medcardPlanSide {
  display: grid;
  gap: 13px;
}

.medcardConditionField {
  margin-top: 13px;
}

/* ---------- Fields ---------- */

.medcardField {
  min-width: 0;

  display: flex;
  flex-direction: column;
  gap: 7px;
}

.medcardFieldLabel {
  display: flex;
  align-items: center;
  gap: 5px;

  color: var(--med-text-soft);
  font-size: 12px;
  font-weight: 760;
}

.medcardFieldLabel b {
  color: var(--med-accent);
}

.medcardFieldLabel small {
  color: var(--med-text-muted);
  font-size: 10px;
  font-weight: 700;
}

.medcardInput,
.medcardTextarea {
  width: 100%;

  color: var(--med-text);
  font: inherit;
  font-size: 13px;

  background: var(--med-input);
  border: 1px solid var(--med-border);
  border-radius: 13px;

  outline: none;

  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.025);

  transition:
    color 0.18s ease,
    background 0.18s ease,
    border-color 0.18s ease,
    box-shadow 0.18s ease;
}

.medcardInput {
  min-height: 45px;
  padding: 0 13px;
}

.medcardTextarea {
  min-height: 96px;
  padding: 12px 13px;

  resize: vertical;
  line-height: 1.55;
}

.medcardTextareaLarge {
  min-height: 155px;
}

.medcardInput::placeholder,
.medcardTextarea::placeholder {
  color: var(--med-text-muted);
}

.medcardInput:hover,
.medcardTextarea:hover {
  border-color:
    color-mix(
      in srgb,
      var(--med-accent) 28%,
      var(--med-border)
    );
}

.medcardInput:focus,
.medcardTextarea:focus {
  background:
    color-mix(
      in srgb,
      var(--med-accent) 5%,
      var(--med-input)
    );

  border-color: var(--med-accent);

  box-shadow:
    0 0 0 4px
      color-mix(
        in srgb,
        var(--med-accent) 12%,
        transparent
      ),
    0 10px 28px rgba(0, 0, 0, 0.1);
}

.medcardInputUnit {
  position: relative;
}

.medcardInputUnit .medcardInput {
  padding-right: 48px;
}

.medcardInputUnit > span {
  position: absolute;
  top: 50%;
  right: 13px;

  color: var(--med-text-muted);
  font-size: 11px;
  font-weight: 800;

  pointer-events: none;
  transform: translateY(-50%);
}

.medcardInput[type="date"],
.medcardInput[type="time"] {
  color-scheme: dark;
}

body[data-theme="white"] .medcardInput[type="date"],
body[data-theme="white"] .medcardInput[type="time"] {
  color-scheme: light;
}

/* ---------- Footer ---------- */

.medcardModalFooter {
  position: relative;
  z-index: 3;

  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;

  padding: 17px 27px;

  background:
    color-mix(
      in srgb,
      var(--med-window-end) 92%,
      transparent
    );

  border-top: 1px solid var(--med-border);

  backdrop-filter: blur(22px);
  -webkit-backdrop-filter: blur(22px);
}

.medcardModalFooterHint {
  color: var(--med-text-muted);
  font-size: 11px;
}

.medcardModalActions {
  display: flex;
  gap: 10px;
}

.medcardCancelButton,
.medcardSaveButton {
  min-height: 44px;

  padding: 0 18px;

  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;

  font: inherit;
  font-size: 13px;
  font-weight: 830;

  border-radius: 13px;

  cursor: pointer;

  transition:
    color 0.18s ease,
    background 0.18s ease,
    border-color 0.18s ease,
    box-shadow 0.18s ease,
    transform 0.18s ease;
}

.medcardCancelButton {
  color: var(--med-text-soft);

  background: var(--med-surface);
  border: 1px solid var(--med-border);
}

.medcardCancelButton:hover {
  color: var(--med-text);
  background: var(--med-surface-hover);
}

.medcardSaveButton {
  min-width: 190px;

  color: #ffffff;

  background:
    linear-gradient(
      135deg,
      var(--med-accent),
      color-mix(in srgb, var(--med-accent) 68%, #000)
    );

  border: 1px solid
    color-mix(
      in srgb,
      var(--med-accent) 48%,
      white
    );

  box-shadow:
    0 13px 28px
      color-mix(
        in srgb,
        var(--med-accent) 28%,
        transparent
      ),
    inset 0 1px 0 rgba(255, 255, 255, 0.2);
}

.medcardSaveButton:hover {
  transform: translateY(-2px);

  box-shadow:
    0 17px 36px
      color-mix(
        in srgb,
        var(--med-accent) 39%,
        transparent
      ),
    inset 0 1px 0 rgba(255, 255, 255, 0.25);
}

.medcardSaveButton:disabled {
  opacity: 0.55;
  cursor: wait;
  transform: none;
}

/* ---------- White theme ---------- */

body[data-theme="white"] .medcardModalWindow {
  box-shadow:
    0 30px 90px rgba(28, 38, 58, 0.2),
    inset 0 1px 0 rgba(255, 255, 255, 1);
}

body[data-theme="white"] .medcardFormSection {
  box-shadow:
    0 3px 14px rgba(32, 40, 58, 0.025),
    inset 0 1px 0 rgba(255, 255, 255, 0.82);
}

/* ---------- Responsive ---------- */

@media (max-width: 900px) {
  .medcardVitalsGrid {
    grid-template-columns: 1fr 1fr;
  }

  .medcardStateGrid {
    grid-template-columns: 1fr 1fr;
  }

  .medcardTextGrid,
  .medcardPlanGrid {
    grid-template-columns: 1fr;
  }

  .medcardVitalsGrid .medcardFieldWide {
    grid-column: span 2;
  }
}

@media (max-width: 620px) {
  .medcardModalOverlay {
    align-items: flex-end !important;
    padding: 8px !important;
  }

  .medcardModalWindow {
    width: 100%;
    max-height: calc(100vh - 16px);
    border-radius: 24px;
  }

  .medcardModalHeader {
    padding: 19px 17px 17px;
  }

  .medcardModalIcon {
    width: 44px;
    height: 44px;
    border-radius: 14px;
  }

  .medcardModalHeader h2 {
    font-size: 21px;
  }

  .medcardModalHeader p {
    display: none;
  }

  .medcardModalScroll {
    padding: 16px 14px 4px;
  }

  .medcardFormSection {
    padding: 15px;
    border-radius: 18px;
  }

  .medcardVitalsGrid,
  .medcardStateGrid {
    grid-template-columns: 1fr;
  }

  .medcardVitalsGrid .medcardFieldWide {
    grid-column: auto;
  }

  .medcardModalFooter {
    align-items: stretch;
    flex-direction: column;
    padding: 14px;
  }

  .medcardModalFooterHint {
    display: none;
  }

  .medcardModalActions {
    flex-direction: column-reverse;
  }

  .medcardCancelButton,
  .medcardSaveButton {
    width: 100%;
  }
}
.medcardSelect {
  appearance: none;
  -webkit-appearance: none;

  padding-right: 42px !important;

  background-image:
    linear-gradient(
      45deg,
      transparent 50%,
      var(--med-text-muted) 50%
    ),
    linear-gradient(
      135deg,
      var(--med-text-muted) 50%,
      transparent 50%
    );

  background-position:
    calc(100% - 19px) 19px,
    calc(100% - 13px) 19px;

  background-size: 6px 6px;
  background-repeat: no-repeat;

  cursor: pointer;
}

.medcardSelect option {
  color: #ffffff;
  background: #171124;
}

body[data-theme="black"] .medcardSelect option {
  background: #0a0a0c;
}

body[data-theme="blue"] .medcardSelect option {
  background: #061b26;
}

body[data-theme="green"] .medcardSelect option {
  background: #05241a;
}

body[data-theme="white"] .medcardSelect option {
  color: #1c1c1e;
  background: #ffffff;
}
