  color: rgba(250, 248, 255, 0.88);
  font-size: 13px;
  font-weight: 760;
  line-height: 1.4;
}

.premiumMedBlocks {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;

  margin-top: 14px;
}

.premiumMedBlock {
  padding: 16px;

  background:
    linear-gradient(
      145deg,
      rgba(255, 255, 255, 0.035),
      rgba(255, 255, 255, 0.014)
    );

  border: 1px solid rgba(255, 255, 255, 0.06);
