}

.premiumMedBlock .history-label {
  color: rgba(224, 216, 239, 0.48);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.premiumMedText {
  color: rgba(250, 248, 255, 0.86);
  font-size: 14px;
  line-height: 1.65;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.premiumMedTreatment .premiumMedText {
  color: rgba(236, 225, 249, 0.94);
}

.premiumMedNote .premiumMedText {
  color: rgba(235, 228, 244, 0.62);
  font-style: italic;
}

.premiumMedEntryFooter {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;

  margin-top: 16px;
  padding-top: 16px;

  border-top: 1px solid rgba(255, 255, 255, 0.06);
}

.premiumMedDoctor {
  color: rgba(244, 239, 252, 0.76);
  font-size: 13px;
  font-weight: 760;
}

.premiumMedEntryStatus {
  padding: 7px 10px;

  color: var(--accent-color, #a855f7);
  font-size: 10px;
  font-weight: 850;
  letter-spacing: 0.04em;
  text-transform: uppercase;

  background:
    color-mix(
      in srgb,
      var(--accent-color, #a855f7) 9%,
      transparent
    );

  border: 1px solid
    color-mix(
      in srgb,
      var(--accent-color, #a855f7) 22%,
      transparent
    );

  border-radius: 999px;
}

/* ---------- GREEN ---------- */

body[data-theme="green"] .premiumMedEntry {
  background:
    radial-gradient(
      circle at 100% 0%,
      rgba(16, 185, 129, 0.08),
      transparent 34%
    ),
    linear-gradient(
      145deg,
      rgba(7, 40, 31, 0.95),
      rgba(2, 17, 12, 0.985)
    ) !important;
}

/* ---------- BLUE ---------- */

body[data-theme="blue"] .premiumMedEntry {
  background:
    radial-gradient(
      circle at 100% 0%,
      rgba(6, 182, 212, 0.08),
      transparent 34%
    ),
    linear-gradient(
      145deg,
      rgba(7, 34, 48, 0.95),
      rgba(2, 14, 23, 0.985)
    ) !important;
}

/* ---------- BLACK ---------- */

body[data-theme="black"] .premiumMedEntry {
  background:
    linear-gradient(
      145deg,
      rgba(20, 20, 23, 0.97),
      rgba(5, 5, 7, 0.995)
    ) !important;
}

/* ---------- WHITE ---------- */

body[data-theme="white"] .premiumMedEntry {
  color: #1d1b28;

  background:
    radial-gradient(
      circle at 100% 0%,
      rgba(0, 122, 255, 0.06),
      transparent 34%
    ),
    linear-gradient(
      145deg,
      rgba(255, 255, 255, 0.98),
      rgba(241, 244, 249, 0.98)
    ) !important;

  border-color: rgba(35, 40, 52, 0.08) !important;

  box-shadow:
    0 16px 42px rgba(35, 27, 60, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.92) !important;
}

body[data-theme="white"] .premiumMedEntryHeader,
body[data-theme="white"] .premiumMedEntryFooter {
  border-color: rgba(35, 40, 52, 0.07);
}

body[data-theme="white"] .premiumMedEntryDateRow {
  color: #1d1b28;
}

body[data-theme="white"] .premiumMedEntryVitalsLine {
  color: rgba(29, 27, 40, 0.52);
}

body[data-theme="white"] .premiumMedVitalCell,
body[data-theme="white"] .premiumMedBlock {
  background: rgba(36, 42, 56, 0.025);
  border-color: rgba(35, 40, 52, 0.07);
}

body[data-theme="white"] .premiumMedVitalCell .med-mini-label,
body[data-theme="white"] .premiumMedBlock .history-label {
  color: rgba(29, 27, 40, 0.42);
}

body[data-theme="white"] .premiumMedVitalCell .med-mini-value,
body[data-theme="white"] .premiumMedText,
body[data-theme="white"] .premiumMedDoctor {
  color: rgba(29, 27, 40, 0.82);
}

/* ---------- MOBILE ---------- */

@media (max-width: 760px) {
  .premiumMedEntry {
    padding: 18px !important;
    border-radius: 20px !important;
  }

  .premiumMedEntryHeader {
    gap: 12px;
  }

  .premiumMedVitalsGrid,
  .premiumMedBlocks {
    grid-template-columns: 1fr;
  }

  .premiumMedCondition,
  .premiumMedTreatment {
    grid-column: auto;
  }

  .premiumMedEntryFooter {
    align-items: flex-start;
    flex-direction: column;
  }
}
/* =========================================================
   DOC.PUG CRM — PREMIUM LABS
   ========================================================= */

body.premiumLabModalOpen {
  overflow: hidden;
}

/* =========================
   LABS PAGE
   ========================= */

.premiumLabsPage {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.premiumLabsHero {
  position: relative;
  overflow: hidden;

  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 24px;

  padding: 26px;

  background:
    radial-gradient(
      circle at 90% 10%,
      color-mix(in srgb, var(--accent-color, #a855f7) 18%, transparent),
      transparent 36%
