    linear-gradient(
      145deg,
      rgba(255, 255, 255, 0.055),
      rgba(255, 255, 255, 0.018)
    );

  border: 1px solid rgba(255, 255, 255, 0.085);
  border-radius: 24px;

  box-shadow:
    0 18px 48px rgba(0, 0, 0, 0.22),
    inset 0 1px 0 rgba(255, 255, 255, 0.04);

  backdrop-filter: blur(24px);
  -webkit-backdrop-filter: blur(24px);
}

.premiumLabsHero::before {
  content: "";

  position: absolute;
  top: -90px;
  right: -80px;

  width: 230px;
  height: 230px;

  background:
    color-mix(
      in srgb,
      var(--accent-color, #a855f7) 20%,
      transparent
    );

  border-radius: 50%;
  filter: blur(80px);
  pointer-events: none;
}

.premiumLabsHeroText {
  position: relative;
  z-index: 2;
}

.premiumLabsKicker {
  margin-bottom: 7px;

  color: var(--accent-color, #a855f7);

  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.premiumLabsHero h2 {
  margin: 0;

  color: #fff;

  font-size: 28px;
  font-weight: 850;
  letter-spacing: -0.035em;
}

.premiumLabsHero p {
  max-width: 680px;

  margin: 9px 0 0;

  color: rgba(239, 233, 248, 0.55);

  font-size: 13px;
  line-height: 1.55;
}

.premiumLabsSpecies {
  display: inline-flex;
  align-items: center;
  gap: 7px;

  margin-top: 15px;
  padding: 8px 11px;

  background:
    color-mix(
      in srgb,
      var(--accent-color, #a855f7) 8%,
      transparent
    );

  border: 1px solid
    color-mix(
      in srgb,
      var(--accent-color, #a855f7) 20%,
      transparent
    );

  border-radius: 999px;

  font-size: 10px;
}

.premiumLabsSpecies span {
  color: rgba(240, 234, 249, 0.44);
}

.premiumLabsSpecies strong {
  color: var(--accent-color, #a855f7);
}

.premiumLabsHeroIcon {
  position: relative;
  z-index: 2;

  width: 72px;
  height: 72px;

  display: grid;
  place-items: center;
  flex: 0 0 auto;

  color: var(--accent-color, #a855f7);

  background:
    color-mix(
      in srgb,
      var(--accent-color, #a855f7) 10%,
      transparent
    );

  border: 1px solid
    color-mix(
      in srgb,
      var(--accent-color, #a855f7) 26%,
      transparent
    );

  border-radius: 22px;

  box-shadow:
    0 14px 34px
