}

.clinicSettingsInput::placeholder {
  color: rgba(255, 255, 255, 0.28);
}

.clinicSettingsInput:hover {
  border-color: rgba(184, 106, 255, 0.24);
}

.clinicSettingsInput:focus {
  border-color: rgba(177, 91, 255, 0.8);
  background: rgba(15, 9, 34, 0.7);
  box-shadow:
    0 0 0 4px rgba(147, 70, 232, 0.13),
    0 12px 30px rgba(55, 18, 95, 0.18);
}

select.clinicSettingsInput {
  appearance: none;
  -webkit-appearance: none;
  cursor: pointer;
  background-image:
    linear-gradient(
      45deg,
      transparent 50%,
      rgba(255, 255, 255, 0.55) 50%
    ),
    linear-gradient(
      135deg,
      rgba(255, 255, 255, 0.55) 50%,
      transparent 50%
    );
  background-position:
    calc(100% - 18px) 20px,
    calc(100% - 13px) 20px;
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
}

.clinicColorField {
  display: grid;
  grid-template-columns: 54px minmax(0, 1fr);
  gap: 10px;
}

.clinicColorField input[type="color"] {
  width: 54px;
  height: 48px;
  padding: 4px;
  cursor: pointer;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 14px;
  background: rgba(7, 5, 18, 0.46);
}

.clinicColorField input[type="color"]::-webkit-color-swatch-wrapper {
  padding: 0;
}

.clinicColorField input[type="color"]::-webkit-color-swatch {
  border: none;
  border-radius: 9px;
}

.clinicBrandUploads {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
  margin-top: 24px;
}

.clinicBrandUpload {
  position: relative;
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 14px;
  padding: 16px;
  border: 1px solid rgba(255, 255, 255, 0.085);
  border-radius: 18px;
  background:
    linear-gradient(
      145deg,
      rgba(255, 255, 255, 0.035),
      rgba(255, 255, 255, 0.012)
    );
  transition:
    transform 0.2s ease,
    border-color 0.2s ease,
    background 0.2s ease;
}

.clinicBrandUpload:hover {
  transform: translateY(-2px);
  border-color: rgba(177, 91, 255, 0.25);
  background:
    linear-gradient(
      145deg,
      rgba(147, 70, 232, 0.08),
      rgba(255, 255, 255, 0.018)
    );
}

.clinicBrandUpload.uploading {
  pointer-events: none;
  opacity: 0.58;
}

.clinicBrandUpload.uploading::after {
  content: "Завантаження…";
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  border-radius: inherit;
  background: rgba(9, 5, 20, 0.82);
  font-size: 13px;
  font-weight: 700;
  color: #fff;
}

.clinicBrandPreview {
  display: grid;
  width: 100%;
  height: 108px;
  place-items: center;
  overflow: hidden;
  border: 1px dashed rgba(255, 255, 255, 0.15);
  border-radius: 14px;
  background:
    radial-gradient(
      circle at center,
      rgba(147, 70, 232, 0.11),
      transparent 68%
    ),
    rgba(5, 3, 13, 0.32);
}

.clinicBrandPreview span {
  font-size: 28px;
  font-weight: 300;
  color: rgba(255, 255, 255, 0.34);
}

.clinicBrandPreview img {
  display: block;
  width: 100%;
  height: 100%;
  padding: 10px;
  box-sizing: border-box;
  object-fit: contain;
}

.clinicBrandUploadText strong {
  display: block;
  margin-bottom: 5px;
  font-size: 14px;
  color: #fff;
}

.clinicBrandUploadText p {
  min-height: 36px;
  margin: 0;
  font-size: 11px;
  line-height: 1.45;
  color: rgba(255, 255, 255, 0.44);
}

.clinicBrandUploadActions {
  display: flex;
  gap: 8px;
  margin-top: 12px;
}

.clinicBrandUploadButton,
.clinicBrandRemoveButton {
  display: inline-flex;
  min-height: 34px;
  align-items: center;
  justify-content: center;
  padding: 0 11px;
  cursor: pointer;
  border-radius: 10px;
  font-size: 11px;
  font-weight: 800;
  transition:
    transform 0.2s ease,
    background 0.2s ease,
    border-color 0.2s ease;
}

.clinicBrandUploadButton {
  flex: 1;
  border: 1px solid rgba(180, 96, 255, 0.28);
  background: rgba(147, 70, 232, 0.15);
  color: #e1c2ff;
}

.clinicBrandRemoveButton {
  border: 1px solid rgba(255, 88, 112, 0.18);
  background: rgba(255, 75, 103, 0.08);
  color: #ff93a4;
}

.clinicBrandUploadButton:hover,
.clinicBrandRemoveButton:hover {
  transform: translateY(-1px);
}

.clinicProfileActions {
  display: flex;
  min-height: 50px;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-top: 24px;
  padding-top: 20px;
  border-top: 1px solid rgba(255, 255, 255, 0.075);
}

.clinicProfileSaveStatus {
  font-size: 13px;
  color: rgba(255, 255, 255, 0.5);
}

.clinicProfileSaveStatus.success {
  color: #65e6a3;
}

.clinicProfileSaveButton {
  min-width: 190px;
  min-height: 48px;
  padding: 0 20px;
  cursor: pointer;
  border: 1px solid rgba(215, 167, 255, 0.28);
  border-radius: 14px;
  background:
    linear-gradient(
      135deg,
      #a84dff,
      #7c3fe6
    );
  box-shadow:
    0 14px 32px rgba(120, 47, 210, 0.32),
    inset 0 1px 0 rgba(255, 255, 255, 0.2);
  font: inherit;
  font-size: 13px;
  font-weight: 800;
  color: #fff;
  transition:
    transform 0.2s ease,
    filter 0.2s ease,
    box-shadow 0.2s ease;
}

.clinicProfileSaveButton:hover {
  transform: translateY(-2px);
  filter: brightness(1.08);
  box-shadow:
    0 18px 38px rgba(120, 47, 210, 0.42),
    inset 0 1px 0 rgba(255, 255, 255, 0.22);
}

.clinicProfileSaveButton:disabled {
  cursor: wait;
  opacity: 0.55;
  transform: none;
}

.clinicDocumentPreview {
  position: sticky;
  top: 18px;
  min-width: 0;
}

.clinicPreviewPaper {
  --document-accent: #9346e8;

  min-height: 610px;
  padding: 26px;
  overflow: hidden;
  border-radius: 22px;
  background: #fff;
  box-shadow:
    0 28px 80px rgba(0, 0, 0, 0.42),
    0 0 0 1px rgba(255, 255, 255, 0.08);
  color: #15131a;
}

.clinicPreviewHeader {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
}

.clinicPreviewBrand {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 11px;
}

.clinicPreviewBrand img,
.clinicPreviewLogoFallback {
  width: 46px;
  height: 46px;
  flex: 0 0 auto;
  border-radius: 13px;
}

.clinicPreviewBrand img {
  object-fit: contain;
}

.clinicPreviewLogoFallback {
  display: grid;
  place-items: center;
  background:
    linear-gradient(
      135deg,
      var(--document-accent),
      #4c1d95
    );
  box-shadow: 0 8px 18px color-mix(
    in srgb,
    var(--document-accent) 28%,
    transparent
  );
  font-size: 19px;
  font-weight: 900;
  color: #fff;
}

.clinicPreviewBrand strong,
.clinicPreviewBrand span {
  display: block;
}

.clinicPreviewBrand strong {
  max-width: 170px;
  overflow: hidden;
  font-size: 14px;
  font-weight: 900;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: #16131b;
}

.clinicPreviewBrand span {
  margin-top: 3px;
  font-size: 9px;
  color: #77717f;
}

.clinicPreviewDocTitle {
  max-width: 145px;
  text-align: right;
  font-size: 13px;
  font-weight: 900;
  line-height: 1.25;
  color: var(--document-accent);
}

.clinicPreviewLine {
  height: 3px;
  margin: 18px 0 12px;
  border-radius: 999px;
  background:
    linear-gradient(
      90deg,
      var(--document-accent),
      color-mix(
        in srgb,
        var(--document-accent) 20%,
        transparent
      )
    );
}

.clinicPreviewContacts {
  display: flex;
  flex-wrap: wrap;
  gap: 5px 12px;
  min-height: 22px;
  font-size: 8px;
  line-height: 1.4;
  color: #77717f;
}

.clinicPreviewPatient {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin: 20px 0 16px;
}

.clinicPreviewPatient > div {
  padding: 11px 12px;
  border: 1px solid #ece8f0;
  border-radius: 10px;
  background: #faf8fc;
}

.clinicPreviewPatient span,
.clinicPreviewPatient strong {
  display: block;
}

.clinicPreviewPatient span {
  margin-bottom: 3px;
  font-size: 8px;
  font-weight: 700;
  text-transform: uppercase;
  color: #9a93a1;
}

.clinicPreviewPatient strong {
  font-size: 11px;
  color: #252029;
}

.clinicPreviewTable {
  overflow: hidden;
  border: 1px solid #e9e5ed;
  border-radius: 12px;
}

.clinicPreviewTable > div {
  display: grid;
  grid-template-columns: 1fr 1fr 0.7fr;
  gap: 8px;
  align-items: center;
  min-height: 38px;
  padding: 0 12px;
  border-bottom: 1px solid #eeeaf1;
  font-size: 9px;
}

.clinicPreviewTable > div:last-child {
  border-bottom: none;
}

.clinicPreviewTable .head {
  min-height: 34px;
  background:
    color-mix(
      in srgb,
      var(--document-accent) 10%,
      #fff
    );
  font-size: 8px;
  font-weight: 900;
  text-transform: uppercase;
  color: var(--document-accent);
}

.clinicPreviewTable strong {
  font-weight: 800;
  color: #28232d;
}

.clinicPreviewTable b {
  justify-self: start;
  padding: 4px 7px;
  border-radius: 999px;
  background: #e7f8ef;
  font-size: 7px;
  color: #12894d;
}

.clinicPreviewTable b.high {
  background: #fff0e6;
  color: #dd6d20;
}

.clinicPreviewSignatures {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
  margin-top: 54px;
}

.clinicPreviewSignatures > div {
  display: grid;
  min-height: 72px;
  place-items: end center;
  padding-bottom: 8px;
  border-bottom: 1px solid #cfc9d4;
  font-size: 8px;
  color: #9c95a3;
}

.clinicPreviewSignatures img {
  display: block;
  max-width: 110px;
  max-height: 58px;
  object-fit: contain;
}

.clinicPreviewFooter {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-top: 24px;
  padding-top: 12px;
  border-top: 1px solid #ece8ef;
  font-size: 8px;
  color: #8c8493;
}

.clinicPreviewFooter small {
  flex: 0 0 auto;
  font-size: 7px;
  color: var(--document-accent);
}

.clinicPersonalGrid {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: minmax(240px, 0.7fr) minmax(0, 1.3fr);
  gap: 18px;
}

.clinicPersonalBlock {
  padding: 18px;
  border: 1px solid rgba(255, 255, 255, 0.075);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.025);
}

.clinicPersonalBlock h3 {
  margin: 0 0 6px;
  font-size: 15px;
  color: #fff;
}

.clinicPersonalBlock p {
  margin: 0 0 14px;
  font-size: 12px;
  line-height: 1.45;
  color: rgba(255, 255, 255, 0.45);
}

.clinicThemeGrid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 9px;
}

.clinicThemeChoice {
  display: flex;
  min-width: 0;
  min-height: 72px;
  flex-direction: column;
  align-items: flex-start;
  justify-content: space-between;
  gap: 9px;
  padding: 11px;
  cursor: pointer;
  border: 1px solid rgba(255, 255, 255, 0.075);
  border-radius: 13px;
  background: rgba(255, 255, 255, 0.025);
  font: inherit;
  color: rgba(255, 255, 255, 0.72);
  transition:
    transform 0.2s ease,
    border-color 0.2s ease,
    background 0.2s ease,
    box-shadow 0.2s ease;
}

.clinicThemeChoice > span {
  width: 22px;
  height: 22px;
  border: 2px solid rgba(255, 255, 255, 0.18);
  border-radius: 50%;
  box-shadow: 0 5px 14px rgba(0, 0, 0, 0.22);
}

.clinicThemeChoice strong {
  overflow: hidden;
  font-size: 10px;
  font-weight: 800;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.clinicThemeChoice:hover {
  transform: translateY(-2px);
  border-color: rgba(184, 106, 255, 0.25);
  background: rgba(147, 70, 232, 0.07);
}

.clinicThemeChoice.active {
  border-color: rgba(179, 93, 255, 0.78);
  background:
    linear-gradient(
      145deg,
      rgba(147, 70, 232, 0.2),
      rgba(147, 70, 232, 0.07)
    );
  box-shadow:
    0 0 0 3px rgba(147, 70, 232, 0.09),
    0 12px 30px rgba(65, 20, 112, 0.18);
  color: #fff;
}

.clinicThemeSaveRow {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 14px;
}

.clinicThemeSaveButton {
  min-height: 40px;
  padding: 0 16px;
  cursor: pointer;
  border: 1px solid rgba(179, 93, 255, 0.64);
  border-radius: 12px;
  background: linear-gradient(135deg, #7c5cff, #b45cff);
  font: inherit;
  font-size: 12px;
  font-weight: 800;
  color: #fff;
  box-shadow: 0 10px 26px rgba(124, 92, 255, 0.22);
}

.clinicThemeSaveButton:disabled {
  cursor: wait;
  opacity: 0.65;
}

#clinicThemeSaveStatus {
  font-size: 12px;
  color: #6ee7b7;
}

#clinicThemeSaveStatus.error {
  color: #ff8ca0;
}

.clinicSettingsLogoutRow {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin-top: 18px;
  padding: 18px;
  border: 1px solid rgba(255, 255, 255, 0.075);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.025);
}

.clinicSettingsLogoutRow > div {
  min-width: 0;
}

.clinicSettingsLogoutRow strong,
.clinicSettingsLogoutRow span {
  display: block;
}

.clinicSettingsLogoutRow strong {
  margin-bottom: 4px;
  font-size: 13px;
  color: #fff;
}

.clinicSettingsLogoutRow span {
  overflow: hidden;
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: rgba(255, 255, 255, 0.46);
}

.clinicLogoutButton {
  min-height: 42px;
  padding: 0 16px;
  cursor: pointer;
  border: 1px solid rgba(255, 84, 110, 0.2);
  border-radius: 12px;
  background: rgba(255, 70, 100, 0.09);
  font: inherit;
  font-size: 12px;
  font-weight: 800;
  color: #ff8ca0;
  transition:
    transform 0.2s ease,
    background 0.2s ease,
    border-color 0.2s ease;
}

.clinicLogoutButton:hover {
  transform: translateY(-1px);
  border-color: rgba(255, 84, 110, 0.35);
  background: rgba(255, 70, 100, 0.14);
}

/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1180px) {
  .clinicProfileLayout {
    grid-template-columns: 1fr;
  }

  .clinicDocumentPreview {
    position: static;
  }

  .clinicPreviewPaper {
    max-width: 620px;
  }

  .clinicThemeGrid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 820px) {
  .clinicSettingsPage {
    padding-bottom: 100px;
  }

  .clinicSettingsHero {
    flex-direction: column;
  }

  .clinicSettingsUser {
    width: 100%;
    box-sizing: border-box;
  }

  .clinicSettingsPanel {
    padding: 20px;
    border-radius: 22px;
  }

  .clinicSettingsPanelHead {
    flex-direction: column;
  }

  .clinicOwnerBadge {
    align-self: flex-start;
  }

  .clinicSettingsFormGrid,
  .clinicPersonalGrid {
    grid-template-columns: 1fr;
  }

  .clinicSettingsFieldWide {
    grid-column: auto;
  }

  .clinicBrandUploads {
    grid-template-columns: 1fr;
  }

  .clinicBrandPreview {
    height: 140px;
  }

  .clinicThemeGrid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 560px) {
  .clinicSettingsHero h1 {
    font-size: 34px;
  }

  .clinicSettingsPanel {
    padding: 16px;
  }

  .clinicSettingsPanelIcon {
    width: 40px;
    height: 40px;
    border-radius: 13px;
  }

  .clinicSettingsPanelHead h2 {
    font-size: 19px;
  }

  .clinicProfileActions,
  .clinicSettingsLogoutRow {
    flex-direction: column;
    align-items: stretch;
  }

  .clinicProfileSaveButton,
  .clinicLogoutButton {
    width: 100%;
  }

  .clinicPreviewPaper {
    min-height: 540px;
    padding: 18px;
    border-radius: 17px;
  }

  .clinicPreviewHeader {
    flex-direction: column;
  }

  .clinicPreviewDocTitle {
    max-width: none;
    text-align: left;
  }

  .clinicPreviewPatient,
  .clinicPreviewSignatures {
    grid-template-columns: 1fr;
  }

  .clinicPreviewSignatures {
    margin-top: 30px;
  }

  .clinicThemeGrid {
    grid-template-columns: 1fr;
  }

  .clinicThemeChoice {
    min-height: 56px;
    flex-direction: row;
    align-items: center;
    justify-content: flex-start;
  }
}

/* Deletable clinic specialization chips. */
body .specPill {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 7px 8px 7px 14px;
  border-color: var(--module-border) !important;
  background: var(--module-surface-soft) !important;
  color: var(--module-text) !important;
}

.specPillDelete {
  display: grid;
  width: 28px;
  height: 28px;
  flex: 0 0 28px;
  place-items: center;
  padding: 0;
  border: 1px solid rgba(255, 99, 119, 0.2);
  border-radius: 9px;
  background: rgba(255, 77, 103, 0.07);
  color: #ff8295;
  font-size: 1.1rem;
  line-height: 1;
  cursor: pointer;
  transition:
    transform 0.18s ease,
    border-color 0.18s ease,
    background 0.18s ease;
}

.specPillDelete:hover {
  transform: translateY(-1px);
  border-color: rgba(255, 99, 119, 0.42);
  background: rgba(255, 77, 103, 0.16);
}

.specPillDelete:focus-visible {
  outline: 3px solid rgba(255, 99, 119, 0.2);
  outline-offset: 2px;
}

/* =========================================================
   DOC.PUG CRM — PATIENT FILES ARCHIVE
   ========================================================= */

