}

.patientFilesStats {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 18px;
}

.patientFilesStats > div {
  padding: 15px 16px;
  border: 1px solid rgba(255, 255, 255, 0.075);
  border-radius: 15px;
  background:
    linear-gradient(
      145deg,
      rgba(255, 255, 255, 0.045),
      rgba(255, 255, 255, 0.014)
    );
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.025);
}

.patientFilesStats span,
.patientFilesStats strong {
  display: block;
}

.patientFilesStats span {
  margin-bottom: 5px;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.4);
}

.patientFilesStats strong {
  font-size: 22px;
  font-weight: 850;
  color: #c88cff;
}

.patientFilesFilters {
  display: flex;
  flex-wrap: wrap;
  gap: 9px;
  margin-bottom: 24px;
  padding: 6px;
  border: 1px solid rgba(255, 255, 255, 0.075);
