/* =========================================================
   PATIENT FILE MODAL
   ========================================================= */

.patientFileModalOverlay {
  position: fixed;
  inset: 0;
  z-index: 100000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: rgba(3, 2, 9, 0.78);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}

.patientFileModal {
  position: relative;
  width: min(760px, 100%);
  max-height: calc(100vh - 48px);
  overflow-y: auto;
  padding: 26px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 24px;
  background:
    radial-gradient(
      circle at top left,
      rgba(147, 70, 232, 0.15),
      transparent 32%
    ),
    linear-gradient(
      150deg,
      rgba(22, 14, 42, 0.98),
      rgba(10, 7, 21, 0.98)
    );
  box-shadow:
    0 32px 100px rgba(0, 0, 0, 0.55),
    inset 0 1px 0 rgba(255, 255, 255, 0.05);
  color: #fff;
}

.patientFileModalClose {
  position: absolute;
  top: 14px;
  right: 14px;
  display: grid;
  width: 36px;
  height: 36px;
  place-items: center;
  cursor: pointer;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.04);
  font: inherit;
  font-size: 23px;
  color: rgba(255, 255, 255, 0.62);
}

.patientFileModalHead {
  display: flex;
  align-items: center;
  gap: 14px;
  padding-right: 48px;
  margin-bottom: 24px;
}

.patientFileModalIcon {
  display: grid;
  width: 48px;
  height: 48px;
  flex: 0 0 48px;
  place-items: center;
  border: 1px solid rgba(181, 102, 255, 0.22);
  border-radius: 15px;
  background: rgba(147, 70, 232, 0.13);
  font-size: 22px;
}

.patientFileModalHead h2 {
  margin: 0;
  font-size: 22px;
  font-weight: 800;
}

.patientFileModalHead p {
  margin: 5px 0 0;
  font-size: 12px;
  color: rgba(255, 255, 255, 0.45);
}

.patientFileModalGrid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}

.patientFileModalField {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 7px;
}

.patientFileModalWide {
  grid-column: 1 / -1;
}

.patientFileModalField > span {
  font-size: 11px;
  font-weight: 750;
  color: rgba(255, 255, 255, 0.64);
}

.patientFileModalField input,
.patientFileModalField select,
.patientFileModalField textarea {
  width: 100%;
  box-sizing: border-box;
  border: 1px solid rgba(255, 255, 255, 0.1);
  outline: none;
  border-radius: 13px;
  background: rgba(5, 3, 13, 0.45);
  font: inherit;
  font-size: 13px;
  color: #fff;
  transition:
    border-color 0.2s ease,
    box-shadow 0.2s ease,
    background 0.2s ease;
}

.patientFileModalField input,
.patientFileModalField select {
  min-height: 46px;
  padding: 0 13px;
}

.patientFileModalField textarea {
  min-height: 96px;
  padding: 12px 13px;
  resize: vertical;
}

.patientFileModalField input:focus,
.patientFileModalField select:focus,
.patientFileModalField textarea:focus {
  border-color: rgba(178, 91, 255, 0.75);
  background: rgba(13, 8, 29, 0.72);
  box-shadow: 0 0 0 4px rgba(147, 70, 232, 0.11);
}

.patientFileUploadZone {
  display: grid;
  grid-template-columns: 190px minmax(0, 1fr);
  gap: 18px;
  align-items: center;
  margin-top: 20px;
  padding: 16px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 17px;
  background: rgba(255, 255, 255, 0.025);
}

.patientFileUploadPreview {
  display: grid;
  height: 150px;
  place-items: center;
  overflow: hidden;
  border: 1px dashed rgba(255, 255, 255, 0.14);
  border-radius: 14px;
  background:
    radial-gradient(
      circle at center,
      rgba(147, 70, 232, 0.1),
      transparent 68%
    ),
    rgba(5, 3, 13, 0.42);
}

.patientFileUploadPreview img,
.patientFileUploadPreview video {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.patientFileUploadEmpty,
.patientFileUploadDocument {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 9px;
  padding: 12px;
  text-align: center;
}

.patientFileUploadEmpty > span,
.patientFileUploadDocument {
  font-size: 28px;
}

.patientFileUploadEmpty small,
.patientFileUploadDocument span {
  max-width: 150px;
  overflow: hidden;
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: rgba(255, 255, 255, 0.46);
}

.patientFileUploadInfo h3 {
  margin: 0;
  font-size: 15px;
}

.patientFileUploadInfo p {
  max-width: 430px;
  margin: 7px 0 14px;
  font-size: 11px;
  line-height: 1.5;
  color: rgba(255, 255, 255, 0.44);
}

.patientFileUploadChoose {
  min-height: 38px;
  padding: 0 14px;
  cursor: pointer;
  border: 1px solid rgba(180, 95, 255, 0.28);
  border-radius: 11px;
  background: rgba(147, 70, 232, 0.14);
  font: inherit;
  font-size: 11px;
  font-weight: 800;
  color: #dfbeff;
}

.patientFileModalActions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 24px;
  padding-top: 18px;
  border-top: 1px solid rgba(255, 255, 255, 0.075);
}

.patientFileModalCancel,
.patientFileModalSave {
  min-height: 42px;
  padding: 0 17px;
  cursor: pointer;
  border-radius: 12px;
  font: inherit;
  font-size: 11px;
  font-weight: 800;
}

.patientFileModalCancel {
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.035);
  color: rgba(255, 255, 255, 0.66);
}

.patientFileModalSave {
  min-width: 150px;
  border: 1px solid rgba(212, 163, 255, 0.27);
  background:
    linear-gradient(
      135deg,
      #a84dff,
      #7c3fe6
    );
  box-shadow:
    0 12px 28px rgba(111, 42, 196, 0.3),
    inset 0 1px 0 rgba(255, 255, 255, 0.18);
  color: #fff;
}

.patientFileModalSave:disabled {
  cursor: wait;
  opacity: 0.55;
}

/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1100px) {
  .patientFilesGrid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .patientFilesStats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 720px) {
  .patientFilesArchiveHead {
    flex-direction: column;
  }

  .patientFilesAddButton {
    width: 100%;
  }

  .patientFilesStats,
  .patientFilesGrid,
  .patientFileModalGrid {
    grid-template-columns: 1fr;
  }

  .patientFileModalWide {
    grid-column: auto;
  }

  .patientFileUploadZone {
    grid-template-columns: 1fr;
  }

  .patientFileUploadPreview {
    height: 190px;
  }
}

@media (max-width: 520px) {
  .patientFileModalOverlay {
    padding: 10px;
  }

  .patientFileModal {
    max-height: calc(100vh - 20px);
    padding: 18px;
    border-radius: 18px;
  }

  .patientFilesFilters {
    flex-direction: column;
  }

  .patientFilesFilter {
    width: 100%;
    justify-content: flex-start;
  }

  .patientFilesFilter em {
    margin-left: auto;
  }

  .patientFileModalActions {
    flex-direction: column-reverse;
  }

  .patientFileModalCancel,
  .patientFileModalSave {
    width: 100%;
  }
}
