/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1100px) {
  .patientFinanceKpis {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .patientFinanceMainGrid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 720px) {
  .patientFinanceHead {
    flex-direction: column;
  }

  .patientFinanceValueBadge {
    width: 100%;
    box-sizing: border-box;
  }

  .patientFinanceKpis {
    grid-template-columns: 1fr;
  }

  .patientPaymentRow {
    grid-template-columns: 1fr auto;
  }

  .patientPaymentDescription {
    grid-column: 1 / -1;
    grid-row: 2;
  }
}

@media (max-width: 520px) {
  .patientFinancePanel {
    padding: 16px;
  }

  .patientFinancePanelHead {
    flex-direction: column;
  }

  .patientPaymentsToggle {
    width: 100%;
  }

  .patientPaymentRow {
    grid-template-columns: 1fr;
  }

  .patientPaymentDescription {
    grid-column: auto;
    grid-row: auto;
  }

  .patientPaymentAmount {
    justify-self: start;
  }
}
