}

.visitWorkspaceEyebrow {
  margin-bottom: 6px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.4);
}

.visitWorkspaceHeader h1 {
  margin: 0;
  font-size: clamp(30px, 4vw, 48px);
  line-height: 1;
  font-weight: 850;
  letter-spacing: -0.04em;
  color: #fff;
}

.visitWorkspaceMeta {
  margin-top: 10px;
  font-size: 13px;
  line-height: 1.5;
  color: rgba(255, 255, 255, 0.48);
}

.visitWorkspaceHeaderActions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
}

.visitWorkspaceStatus,
.visitWorkspaceDate {
  display: inline-flex;
  min-height: 38px;
  align-items: center;
  justify-content: center;
