  font-size: 18px;
  font-weight: 820;
  letter-spacing: -0.02em;
  color: #fff;
}

.visitSectionHead p {
  max-width: 620px;
  margin: 5px 0 0;
  font-size: 10px;
  line-height: 1.5;
  color: rgba(255, 255, 255, 0.42);
}

.visitSectionTotal {
  flex: 0 0 auto;
  min-width: 110px;
  padding: 9px 11px;
  border: 1px solid rgba(177, 91, 255, 0.16);
  border-radius: 12px;
  background: rgba(147, 70, 232, 0.07);
