}

.visitSectionTotal span,
.visitSectionTotal strong {
  display: block;
}

.visitSectionTotal span {
  margin-bottom: 3px;
  font-size: 8px;
  font-weight: 750;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.4);
}

.visitSectionTotal strong {
  font-size: 14px;
  font-weight: 850;
  color: #c88cff;
}

.visitMedicalGrid {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: minmax(0, 1.5fr) minmax(180px, 0.5fr);
  gap: 16px;
}

.visitField {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 7px;
}

.visitFieldWide {
  grid-column: 1 / -1;
}

.visitField > span {
  font-size: 10px;
  font-weight: 750;
  color: rgba(255, 255, 255, 0.62);
}

.visitControl {
  width: 100%;
  min-height: 46px;
  box-sizing: border-box;
  padding: 0 13px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  outline: none;
  border-radius: 13px;
  background: rgba(5, 3, 13, 0.46);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.02),
    0 8px 22px rgba(0, 0, 0, 0.08);
  font: inherit;
  font-size: 13px;
  color: #fff;
  transition:
    border-color 0.2s ease,
    background 0.2s ease,
    box-shadow 0.2s ease;
}

textarea.visitControl {
  min-height: 94px;
  padding: 12px 13px;
  line-height: 1.55;
  resize: vertical;
}

.visitTextareaLarge {
  min-height: 120px !important;
}

.visitControl::placeholder {
  color: rgba(255, 255, 255, 0.26);
}

.visitControl:hover {
  border-color: rgba(181, 101, 255, 0.22);
}

.visitControl:focus {
  border-color: rgba(178, 91, 255, 0.72);
  background: rgba(13, 8, 28, 0.72);
  box-shadow:
    0 0 0 4px rgba(147, 70, 232, 0.1),
    0 12px 30px rgba(54, 17, 94, 0.16);
}

select.visitControl {
  appearance: none;
  -webkit-appearance: none;
  cursor: pointer;
  padding-right: 34px;
  background-image:
    linear-gradient(
      45deg,
      transparent 50%,
      rgba(255, 255, 255, 0.55) 50%
