    linear-gradient(
      135deg,
      rgba(255, 255, 255, 0.55) 50%,
      transparent 50%
    );
  background-position:
    calc(100% - 18px) 20px,
    calc(100% - 13px) 20px;
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
}

.visitWeightControl {
  position: relative;
}

.visitWeightControl .visitControl {
  padding-right: 42px;
}

.visitWeightControl > span {
  position: absolute;
  top: 50%;
  right: 13px;
  transform: translateY(-50%);
  font-size: 11px;
  font-weight: 750;
  color: rgba(255, 255, 255, 0.4);
}

.visitPickerModern {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns:
    minmax(160px, 0.7fr)
    minmax(260px, 1.3fr)
    86px
    112px;
  gap: 10px;
  align-items: end;
  margin-bottom: 16px;
}

.visitPickerModern label {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 7px;
}

.visitPickerModern label > span {
  font-size: 9px;
  font-weight: 750;
  color: rgba(255, 255, 255, 0.52);
}

.visitPickerQty .visitControl {
  text-align: center;
}

.visitAddLineButton {
  min-height: 46px;
  padding: 0 14px;
  cursor: pointer;
  border: 1px solid rgba(211, 164, 255, 0.28);
  border-radius: 13px;
  background:
    linear-gradient(
      135deg,
      #a84dff,
      #7c3fe6
    );
  box-shadow:
    0 12px 28px rgba(111, 42, 196, 0.28),
    inset 0 1px 0 rgba(255, 255, 255, 0.18);
  font: inherit;
  font-size: 11px;
  font-weight: 850;
  color: #fff;
  transition:
    transform 0.2s ease,
    filter 0.2s ease,
    box-shadow 0.2s ease;
}

.visitAddLineButton:hover {
  transform: translateY(-2px);
  filter: brightness(1.07);
  box-shadow:
    0 16px 34px rgba(111, 42, 196, 0.38),
    inset 0 1px 0 rgba(255, 255, 255, 0.2);
}

.visitLinesModern {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.visitLine {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 12px 13px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 13px;
  background: rgba(255, 255, 255, 0.022);
  transition:
    transform 0.2s ease,
    border-color 0.2s ease,
    background 0.2s ease;
}

.visitLine:hover {
  transform: translateY(-1px);
  border-color: rgba(177, 91, 255, 0.18);
  background: rgba(147, 70, 232, 0.045);
}

.visitLineMain {
  min-width: 0;
}

.visitLineMain strong,
.visitLineMain span {
  display: block;
}

.visitLineMain strong {
  overflow: hidden;
  font-size: 12px;
  font-weight: 800;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: #fff;
}

.visitLineMain span {
  margin-top: 4px;
  font-size: 9px;
  color: rgba(255, 255, 255, 0.38);
}

.visitLineActions {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 12px;
}

.visitLineTotal {
  font-size: 12px;
  font-weight: 850;
  color: #c98cff;
}

.visitLineDelete {
  display: grid;
  width: 30px;
  height: 30px;
  place-items: center;
  cursor: pointer;
  border: 1px solid rgba(255, 79, 105, 0.16);
  border-radius: 9px;
  background: rgba(255, 67, 96, 0.06);
  font: inherit;
  font-size: 11px;
  color: #ff8296;
  transition:
    transform 0.2s ease,
    background 0.2s ease,
    border-color 0.2s ease;
}

.visitLineDelete:hover {
  transform: translateY(-1px);
  border-color: rgba(255, 79, 105, 0.28);
  background: rgba(255, 67, 96, 0.12);
}

.visitLinesEmpty {
  padding: 24px 16px;
  border: 1px dashed rgba(255, 255, 255, 0.1);
  border-radius: 13px;
  text-align: center;
  font-size: 10px;
  color: rgba(255, 255, 255, 0.36);
}

/* =========================================================
   VISIT SUMMARY SIDEBAR
   ========================================================= */

.visitWorkspaceSidebar {
  position: sticky;
  top: 18px;
}

.visitSummaryCard {
  position: relative;
  padding: 20px;
  overflow: hidden;
  border: 1px solid var(--finance-border-strong);
  border-radius: 22px;
  background:
    radial-gradient(
      circle at top left,
      var(--finance-accent-soft),
      transparent 36%
    ),
    linear-gradient(
      150deg,
      var(--finance-surface-1),
      var(--finance-surface-2)
    );
  box-shadow:
    0 26px 70px var(--finance-shadow),
    inset 0 1px 0 rgba(255, 255, 255, 0.045);
  backdrop-filter: blur(24px);
  -webkit-backdrop-filter: blur(24px);
}

.visitSummaryCard::before {
  content: "";
  position: absolute;
  top: -90px;
  right: -80px;
  width: 210px;
  height: 210px;
  pointer-events: none;
  border-radius: 50%;
  background: var(--finance-accent-glow);
  filter: blur(40px);
}

.visitSummaryHead {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 16px;
}

.visitSummaryHead span {
  font-size: 13px;
  font-weight: 850;
  color: var(--finance-text);
}

.visitSummaryHead b {
  padding: 5px 7px;
  border: 1px solid rgba(97, 229, 154, 0.18);
  border-radius: 999px;
  background: rgba(48, 206, 118, 0.07);
  font-size: 7px;
  font-weight: 900;
  letter-spacing: 0.08em;
  color: #6ae7a1;
}

.visitSummaryPatient {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 12px;
  margin-bottom: 16px;
  border: 1px solid var(--finance-border);
  border-radius: 14px;
  background: var(--finance-surface-soft);
}

.visitSummaryAvatar {
  display: grid;
  width: 40px;
  height: 40px;
  flex: 0 0 40px;
  place-items: center;
  border: 1px solid var(--finance-border-strong);
  border-radius: 12px;
  background: var(--finance-accent-soft);
  font-size: 17px;
}

.visitSummaryPatient strong,
.visitSummaryPatient span {
  display: block;
}

.visitSummaryPatient strong {
  overflow: hidden;
  font-size: 12px;
  font-weight: 800;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--finance-text);
}

.visitSummaryPatient span {
  margin-top: 4px;
  overflow: hidden;
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--finance-text-muted);
}

.visitSummaryRows {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 17px;
}

.visitSummaryRows > div:not(.visitSummaryDivider) {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.visitSummaryRows span {
  font-size: 10px;
  color: var(--finance-text-muted);
}

.visitSummaryRows strong {
  font-size: 12px;
  font-weight: 800;
  color: var(--finance-text);
}

.visitSummaryDivider {
  height: 1px;
  background: var(--finance-border);
}

.visitSummaryGrand {
  align-items: flex-end !important;
}

.visitSummaryGrand span {
  font-size: 11px;
  font-weight: 700;
  color: var(--finance-text-soft);
}

.visitSummaryGrand strong {
  font-size: 28px;
  line-height: 1;
  font-weight: 900;
  letter-spacing: -0.03em;
  color: var(--finance-accent-2);
}

.visitSavePrimary,
.visitCompleteButton,
.visitPrintButton {
  position: relative;
  z-index: 1;
  width: 100%;
  min-height: 44px;
  margin-top: 9px;
  cursor: pointer;
  border-radius: 13px;
  font: inherit;
  font-size: 11px;
  font-weight: 850;
  transition:
    transform 0.2s ease,
    filter 0.2s ease,
    background 0.2s ease,
    border-color 0.2s ease,
    box-shadow 0.2s ease;
}

.visitSavePrimary {
  border: 1px solid var(--finance-border-strong);
  background:
    linear-gradient(
      135deg,
      var(--finance-accent-2),
      var(--finance-accent)
    );
  box-shadow:
    0 14px 32px var(--finance-accent-glow),
    inset 0 1px 0 rgba(255, 255, 255, 0.18);
  color: #fff;
}

.visitCompleteButton {
  border: 1px solid rgba(71, 222, 139, 0.22);
  background: rgba(45, 205, 116, 0.08);
  color: #72e6a7;
}

.visitPrintButton {
  border: 1px solid var(--finance-border);
  background: var(--finance-surface-soft);
  color: var(--finance-text-soft);
}

.visitSavePrimary:hover,
.visitCompleteButton:hover,
.visitPrintButton:hover {
  transform: translateY(-2px);
}

.visitSavePrimary:hover {
  filter: brightness(1.08);
  box-shadow:
    0 18px 38px var(--finance-accent-glow),
    inset 0 1px 0 rgba(255, 255, 255, 0.2);
}

.visitCompleteButton:hover {
  border-color: rgba(71, 222, 139, 0.34);
  background: rgba(45, 205, 116, 0.13);
}

.visitPrintButton:hover {
  background: var(--finance-surface-hover);
}

.visitSummaryHint {
  position: relative;
  z-index: 1;
  margin-top: 14px;
  padding-top: 13px;
  border-top: 1px solid var(--finance-border);
  font-size: 8px;
  line-height: 1.5;
  color: var(--finance-text-faint);
}

/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1120px) {
  .visitWorkspaceGrid {
    grid-template-columns: 1fr;
  }

  .visitWorkspaceSidebar {
    position: static;
  }

  .visitSummaryCard {
    max-width: none;
  }

  .visitPickerModern {
    grid-template-columns:
      minmax(150px, 0.7fr)
      minmax(220px, 1.3fr)
      80px
      110px;
  }
}

@media (max-width: 820px) {
  .visitWorkspaceHeader {
    flex-direction: column;
  }

  .visitWorkspaceHeaderActions {
    justify-content: flex-start;
  }

  .visitSectionCard {
    padding: 18px;
  }

  .visitMedicalGrid {
    grid-template-columns: 1fr;
  }

  .visitFieldWide {
    grid-column: auto;
  }

  .visitPickerModern {
    grid-template-columns: 1fr 1fr;
  }

  .visitPickerQty {
    grid-column: 1;
  }

  .visitAddLineButton {
    grid-column: 2;
  }
}

@media (max-width: 560px) {
  .visitWorkspace {
    padding-bottom: 100px;
  }

  .visitWorkspaceHeader h1 {
    font-size: 34px;
  }

  .visitWorkspaceHeaderActions {
    width: 100%;
  }

  .visitWorkspaceStatus,
  .visitWorkspaceDate {
    flex: 1;
  }

  .visitSectionHead {
    flex-direction: column;
  }

  .visitSectionTotal {
    width: 100%;
    box-sizing: border-box;
    text-align: left;
  }

  .visitPickerModern {
    grid-template-columns: 1fr;
  }

  .visitPickerQty,
  .visitAddLineButton {
    grid-column: auto;
  }

  .visitAddLineButton {
    width: 100%;
  }

  .visitLine {
    align-items: flex-start;
    flex-direction: column;
  }

  .visitLineActions {
    width: 100%;
    justify-content: space-between;
  }

  .visitSummaryGrand {
    align-items: flex-start !important;
    flex-direction: column;
  }
}
