/* =========================================================
   PRINT — A4, CORRECT MULTI-PAGE BREAKS
   ========================================================= */

@media print {
  @page {
    size: A4 portrait;
    margin: 12mm 11mm 14mm;
  }

  html,
  body {
    width: auto !important;
    height: auto !important;
    min-height: 0 !important;
    margin: 0 !important;
    padding: 0 !important;
    background: #ffffff !important;
    overflow: visible !important;
  }

  body.docpug-printing * {
    visibility: hidden !important;
  }

  body.docpug-printing #disA4,
  body.docpug-printing #disA4 * {
    visibility: visible !important;
  }

  body.docpug-printing #disA4 {
    position: static !important;
    inset: auto !important;
    width: auto !important;
    max-width: none !important;
    min-height: 0 !important;
    height: auto !important;
    margin: 0 !important;
    padding: 0 !important;
    background: #ffffff !important;
    overflow: visible !important;
    transform: none !important;
  }

  body.docpug-printing .premiumDischargeDocument {
    width: auto !important;
    max-width: none !important;
    min-height: 0 !important;
    height: auto !important;
    margin: 0 !important;
    padding: 0 !important;
    border: 0 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    background: #ffffff !important;
    overflow: visible !important;
    transform: none !important;
  }

  .dischargeHeader {
    break-inside: avoid;
    page-break-inside: avoid;
  }

  .dischargeAccentLine {
    break-after: avoid;
    page-break-after: avoid;
  }

  .dischargePeopleGrid {
    break-inside: avoid;
    page-break-inside: avoid;
  }

  .dischargeInfoCard {
    break-inside: avoid;
    page-break-inside: avoid;
  }

  .dischargeMedicalSection {
    break-inside: avoid;
    page-break-inside: avoid;
  }

  .dischargeSectionTitle {
    break-after: avoid;
    page-break-after: avoid;
  }

  .dischargeFinanceSection {
    overflow: visible !important;
    break-inside: auto;
    page-break-inside: auto;
  }

  .dischargeFinanceHeader {
    break-inside: avoid;
    page-break-inside: avoid;
    break-after: avoid;
    page-break-after: avoid;
  }

  .dischargeFinanceTable {
    width: 100% !important;
    min-width: 0 !important;
    table-layout: fixed;
    border-collapse: collapse;
  }

  .dischargeFinanceTable thead {
    display: table-header-group;
  }

  .dischargeFinanceTable tfoot {
    display: table-footer-group;
  }

  .dischargeFinanceTable tbody {
    display: table-row-group;
  }

  .dischargeFinanceTable tr {
    break-inside: avoid;
    page-break-inside: avoid;
  }

  .dischargeFinanceTable th,
  .dischargeFinanceTable td {
    break-inside: avoid;
    page-break-inside: avoid;
  }

  .dischargeTotals {
    break-inside: avoid;
    page-break-inside: avoid;
  }

  .dischargeSignatureSection {
    break-inside: avoid;
    page-break-inside: avoid;
  }

  .dischargeFooter {
    break-inside: avoid;
    page-break-inside: avoid;
  }

  .dischargeClinicLogo,
  .dischargeSignatureImage,
  .dischargeStamp img {
    print-color-adjust: exact;
    -webkit-print-color-adjust: exact;
  }

  .dischargeAccentLine,
  .dischargeInfoCard,
  .dischargePrescriptionSection,
  .dischargeFinanceHeader,
  .dischargeTotalBadge,
  .dischargeFinanceTable th {
    print-color-adjust: exact;
    -webkit-print-color-adjust: exact;
  }
}
/* Скрытый контейнер выписки вне режима печати */
.visitDischargePrintHost {
