  padding: 8px 10px !important;
}

.disModernSignGrid {
  display: grid !important;
  grid-template-columns: 1fr 1fr !important;
  margin-top: 12px !important;
  gap: 10px !important;
}

.disModernSignBox {
  min-height: 76px !important;
  padding: 10px 12px !important;
  border-radius: 10px !important;
}

.disModernSignTitle {
  margin-bottom: 5px !important;
  font-size: 9px !important;
}

.disModernSignLine {
  margin-top: 18px !important;
}

.disModernSignName {
  margin-top: 6px !important;
  font-size: 10px !important;
}

.disModernFooter {
  margin-top: 12px !important;
  padding-top: 8px !important;
}
/* ===== PDF-выписка: уменьшаем разрыв и центрируем ===== */

.disModernDoc {
  margin: 0 auto !important;
}

.disModernSection {
  margin-bottom: 0 !important;
}

.disModernSection--follow,
.disModernFollowBlock,
.disModernControlBlock {
  margin-bottom: 10px !important;
}

.disModernSection--finance,
.disModernFinanceBlock,
.disModernServicesBlock {
  margin-top: 10px !important;
}

/* если где-то секция услуг прижимается вниз */
.disModernSection--finance,
.disModernFinanceBlock,
.disModernServicesBlock {
  align-self: auto !important;
}
/* PDF: финансовый блок можно делить между страницами */
.disModernFinanceSection {
  break-inside: auto !important;
  page-break-inside: auto !important;
  overflow: visible !important;
}

.disModernTableWrap {
  break-inside: auto !important;
  page-break-inside: auto !important;
  overflow: visible !important;
}

.disModernTable tr {
  break-inside: avoid !important;
  page-break-inside: avoid !important;
}

/* =========================================================
   INFORMED CONSENT PDF
   ========================================================= */

.disConsentRepresentative {
  display: grid;
  grid-template-columns:
    minmax(0, 1.15fr)
    minmax(0, 1fr)
    minmax(0, .8fr);
  gap: 8px;
  margin-top: 9px;
  padding: 9px 11px;
  border: 1px solid #e8edf3;
  border-radius: 10px;
  background: #f8fafc;
}

.disConsentRepresentative span,
.disConsentRepresentative strong {
  display: block;
}

.disConsentRepresentative span {
  color: var(--disAccent, #9346e8);
  font-size: 7px;
  font-weight: 850;
  letter-spacing: .07em;
}

.disConsentRepresentative strong {
  margin-top: 3px;
  color: #273044;
  font-size: 9px;
  line-height: 1.3;
  overflow-wrap: anywhere;
}

.disConsentSection {
  /*
   * html2canvas 1.x не умеет разбирать вычисленный
   * цвет из color-mix()/color(). Для PDF оставляем
   * такой же лёгкий фон в обычном sRGB.
   */
  background:
    linear-gradient(
      135deg,
      rgba(72, 199, 213, .045),
      #ffffff
    ) !important;
}

.disConsentLead {
  margin: 6px 0 0;
  color: #344054;
  font-size: 10px;
  line-height: 1.45;
}

.disConsentClauses {
  margin: 8px 0 0;
  padding-left: 20px;
  color: #344054;
  font-size: 10px;
  line-height: 1.45;
}

.disConsentClause {
  padding-left: 3px;
}

.disConsentClause + .disConsentClause {
  margin-top: 5px;
}

.disConsentClause::marker {
  color: var(--disAccent, #9346e8);
  font-weight: 850;
}

.disConsentDataSection {
  border-left: 3px solid
    var(--disAccent, #9346e8) !important;
  background: #fbfcfe !important;
}

.disConsentAcknowledgements {
  display: grid;
  grid-template-columns:
    repeat(3, minmax(0, 1fr));
  gap: 7px;
  margin-top: 9px;
}

.disConsentAcknowledgements > div {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  padding: 8px 9px;
  border: 1px solid #e8edf3;
  border-radius: 9px;
  background: #f8fafc;
  color: #536071;
  font-size: 8px;
  line-height: 1.35;
}

.disConsentAcknowledgements span {
  display: grid;
  width: 13px;
  height: 13px;
  flex: 0 0 13px;
  place-items: center;
  border-radius: 4px;
  background: #eaf8fa;
  color: var(--disAccent, #9346e8);
  font-size: 8px;
  font-weight: 900;
}

.disConsentSignGrid {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin-top: 12px;
}

.disConsentSignBox {
  min-height: 82px;
  padding: 10px 12px;
  border: 1px solid #e8edf3;
  border-radius: 10px;
  background: #fff;
}

.disConsentSignDate {
  margin-top: 3px;
  color: #8a94a6;
  font-size: 7px;
}

@media print {
  .disConsentRepresentative,
  .disConsentClause,
  .disConsentDataSection,
  .disConsentAcknowledgements,
  .disConsentSignGrid {
    break-inside: avoid;
    page-break-inside: avoid;
  }
}

