  color: rgba(255,255,255,.66);
}

.stockEditorSubmit,
.stockAdjustmentSubmit.income {
  border: 1px solid rgba(191,121,255,.38);
  background: linear-gradient(135deg,#8942ff,#b349ff);
  color: #fff;
}

.stockAdjustmentModal {
  width: min(470px,94vw);
  padding: 28px;
  text-align: center;
}

.stockAdjustmentIcon {
  display: grid;
  width: 61px;
  height: 61px;
  margin: 0 auto 14px;
  place-items: center;
  border-radius: 19px;
  font-size: 1.5rem;
  font-weight: 900;
}

.stockAdjustmentIcon.income {
  border: 1px solid rgba(71,224,154,.22);
  background: rgba(65,221,148,.1);
  color: #67e1aa;
}

.stockAdjustmentIcon.writeoff {
  border: 1px solid rgba(255,91,115,.22);
  background: rgba(255,76,104,.1);
  color: #ff8090;
}

.stockAdjustmentItem,
.stockDeleteItem {
  display: flex;
  align-items: center;
  gap: 11px;
  margin: 17px 0;
  padding: 12px;
  border: 1px solid rgba(255,255,255,.08);
  border-radius: 14px;
  background: rgba(255,255,255,.025);
  text-align: left;
}

.stockAdjustmentItem > span,
.stockDeleteItem > span {
  display: grid;
  width: 41px;
  height: 41px;
  place-items: center;
  border-radius: 12px;
  background: rgba(168,85,247,.1);
}

.stockAdjustmentItem strong,
.stockAdjustmentItem small,
.stockDeleteItem strong,
.stockDeleteItem small {
  display: block;
}

.stockAdjustmentItem strong,
.stockDeleteItem strong {
  color: #fff;
}

.stockAdjustmentItem small,
.stockDeleteItem small {
  margin-top: 3px;
  color: rgba(255,255,255,.4);
}

.stockAdjustmentField {
  text-align: left;
}

.stockAdjustmentResult {
  display: flex;
  justify-content: space-between;
  padding: 12px;
  border: 1px solid rgba(181,103,255,.15);
  border-radius: 13px;
  background: rgba(168,85,247,.07);
}

.stockAdjustmentResult span {
  color: rgba(255,255,255,.43);
}

.stockAdjustmentResult strong {
  color: #fff;
}

.stockAdjustmentSubmit.writeoff {
  border: 1px solid rgba(255,97,122,.3);
  background: linear-gradient(135deg,#d63d61,#ef5273);
  color: #fff;
}

.stockDeleteModal {
  width: min(430px,94vw);
  padding: 28px;
  text-align: center;
}

.stockDeleteIcon {
  display: grid;
  width: 61px;
  height: 61px;
  margin: 0 auto 14px;
  place-items: center;
  border: 1px solid rgba(255,93,120,.22);
  border-radius: 19px;
  background: rgba(255,75,107,.1);
  font-size: 1.4rem;
}

.stockDeleteModal > p {
  color: rgba(255,255,255,.43);
  font-size: .8rem;
  line-height: 1.45;
}

.stockDeleteSubmit {
  border: 1px solid rgba(255,100,125,.3);
  background: linear-gradient(135deg,#d73e62,#ef5373);
  color: #fff;
}

@media (max-width: 1050px) {
  .stockPremiumStats {
    grid-template-columns: repeat(3,1fr);
  }

  .stockPremiumCards {
    grid-template-columns: repeat(2,minmax(0,1fr));
  }

  .stockPugBriefHeader {
    grid-template-columns: 1fr;
  }

  .stockPugBriefMetrics {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 700px) {
  .stockPremiumPage {
    width: min(100% - 24px,1180px);
  }

  .stockPremiumHero,
  .stockPremiumControls {
    flex-direction: column;
    align-items: stretch;
  }

  .stockPremiumAddButton {
    width: 100%;
  }

  .stockPremiumStats,
  .stockPremiumCards,
  .stockEditorRow {
    grid-template-columns: 1fr;
  }

  .stockPremiumFilters {
    overflow-x: auto;
  }

  .stockEditorModal {
    padding: 23px 17px;
  }

  .stockPugBrief {
    padding: 17px;
  }

  .stockPugBriefIdentity {
    align-items: flex-start;
  }

  .stockPugBriefMetrics,
  .stockPugBriefSignals {
    grid-template-columns: 1fr;
  }

  .stockPugSignal {
    grid-template-columns: 34px minmax(0, 1fr);
  }

  .stockPugSignalAction {
    grid-column: 2;
  }
}
/* =====================================================
   STOCK FILTERS — CLEAN PREMIUM
===================================================== */

.stockAdvancedFilters {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(220px, 320px));
  gap: 12px;
  margin-top: 14px;
  padding: 14px;
  border: 1px solid
    rgba(255, 255, 255, 0.075);
  border-radius: 17px;
  background:
    linear-gradient(
      135deg,
      rgba(255, 255, 255, 0.035),
      rgba(255, 255, 255, 0.012)
    );
}

.stockAdvancedFilter {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 7px;
}

.stockAdvancedFilter > span {
  color:
    rgba(255, 255, 255, 0.44);
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.03em;
}

.stockSelectWrap {
  position: relative;
  min-width: 0;
}

.stockPremiumSelect {
  width: 100%;
  height: 43px;
  padding: 0 42px 0 13px;
  border: 1px solid
    rgba(255, 255, 255, 0.09);
  border-radius: 12px;
  outline: 0;
  appearance: none;
  -webkit-appearance: none;
  background:
    linear-gradient(
      135deg,
      rgba(20, 12, 37, 0.98),
      rgba(12, 7, 25, 0.98)
    );
  color: rgba(255, 255, 255, 0.88);
  font-size: 0.78rem;
  font-weight: 700;
  cursor: pointer;
  transition:
    border-color 0.2s ease,
    box-shadow 0.2s ease,
    transform 0.2s ease;
}

.stockPremiumSelect:hover {
  border-color:
    rgba(180, 103, 255, 0.38);
}

.stockPremiumSelect:focus {
  border-color:
    rgba(181, 103, 255, 0.72);
  box-shadow:
    0 0 0 3px
    rgba(168, 85, 247, 0.13);
}

.stockPremiumSelect option {
  background: #1a1029;
  color: #ffffff;
}

.stockSelectArrow {
  position: absolute;
  top: 50%;
  right: 14px;
  color:
    rgba(211, 167, 255, 0.72);
  font-size: 1rem;
  pointer-events: none;
  transform: translateY(-55%);
}


/* Группы и категории */

.stockPremiumGroupFilters,
.stockPremiumCategories {
  display: flex;
  gap: 8px;
  padding: 3px 0 5px;
  overflow-x: auto;
  scrollbar-width: none;
}

.stockPremiumGroupFilters {
  margin-top: 16px;
}

.stockPremiumCategories {
  margin-top: 9px;
}

.stockPremiumGroupFilters::-webkit-scrollbar,
.stockPremiumCategories::-webkit-scrollbar {
  display: none;
}

.stockPremiumGroupFilters button,
.stockPremiumCategories button {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 40px;
  flex: 0 0 auto;
  padding: 9px 13px;
  border: 1px solid
    rgba(255, 255, 255, 0.075);
  border-radius: 12px;
  background:
    linear-gradient(
      135deg,
      rgba(255, 255, 255, 0.038),
      rgba(255, 255, 255, 0.014)
    );
  color:
    rgba(255, 255, 255, 0.54);
  font-size: 0.72rem;
  font-weight: 760;
  cursor: pointer;
  transition:
    transform 0.18s ease,
    border-color 0.18s ease,
    background 0.18s ease,
    color 0.18s ease;
}

.stockPremiumGroupFilters button:hover,
.stockPremiumCategories button:hover {
  border-color:
    rgba(177, 96, 255, 0.35);
  color: rgba(255, 255, 255, 0.9);
  transform: translateY(-1px);
}

.stockPremiumGroupFilters button.active,
.stockPremiumCategories button.active {
  border-color:
    rgba(202, 145, 255, 0.48);
  background:
    linear-gradient(
      135deg,
      rgba(159, 79, 255, 0.32),
      rgba(191, 79, 255, 0.17)
    );
  color: #f1dcff;
  box-shadow:
    inset 0 1px 0
    rgba(255, 255, 255, 0.07),
    0 9px 24px
    rgba(139, 63, 233, 0.12);
}

.stockPremiumGroupFilters button b,
.stockPremiumCategories button b {
  display: grid;
  min-width: 23px;
  height: 23px;
  padding: 0 6px;
  place-items: center;
  border-radius: 999px;
  background:
    rgba(255, 255, 255, 0.07);
  color:
    rgba(255, 255, 255, 0.74);
  font-size: 0.61rem;
}


/* Верхний статусный переключатель */

.stockPremiumFilters {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 4px;
  border: 1px solid
    rgba(255, 255, 255, 0.075);
  border-radius: 13px;
  background:
    rgba(255, 255, 255, 0.025);
}

.stockPremiumFilters button {
  min-height: 38px;
  padding: 8px 14px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color:
    rgba(255, 255, 255, 0.47);
  font-size: 0.7rem;
  font-weight: 800;
  cursor: pointer;
  transition:
    background 0.18s ease,
    color 0.18s ease,
    transform 0.18s ease;
}

.stockPremiumFilters button:hover {
  color:
    rgba(255, 255, 255, 0.86);
}

.stockPremiumFilters button.active {
  background:
    linear-gradient(
      135deg,
      rgba(145, 71, 241, 0.63),
      rgba(180, 70, 242, 0.43)
    );
  color: #ffffff;
  box-shadow:
    0 7px 18px
    rgba(144, 60, 224, 0.2);
}


/* Карточные характеристики */

.stockPremiumProperties {
  display: grid;
  grid-template-columns:
    repeat(3, minmax(0, 1fr));
  gap: 7px;
  margin-top: 12px;
}

.stockPremiumProperties > span {
  min-width: 0;
  padding: 8px 9px;
  border: 1px solid
    rgba(255, 255, 255, 0.06);
  border-radius: 10px;
  background:
    rgba(255, 255, 255, 0.022);
  color:
    rgba(255, 255, 255, 0.68);
  font-size: 0.64rem;
  overflow: hidden;
  text-overflow: ellipsis;
}

.stockPremiumProperties b {
  display: block;
  margin-bottom: 4px;
  color:
    rgba(255, 255, 255, 0.3);
  font-size: 0.53rem;
  font-weight: 850;
  letter-spacing: 0.035em;
  text-transform: uppercase;
}


/* Один элемент в строке редактора */

.stockEditorRowSingle {
  grid-template-columns: 1fr;
}

@media (max-width: 700px) {
  .stockAdvancedFilters {
    grid-template-columns: 1fr;
  }

  .stockPremiumProperties {
    grid-template-columns: 1fr;
  }
}
/* =========================================================
   VISIT PAYMENT STATUS
   ========================================================= */

.visitPaymentState[hidden],
.visitPaymentButton[hidden] {
  display: none !important;
}

.visitPaymentState {
  position: relative;
  z-index: 1;

  padding: 12px;
  margin: 3px 0 8px;

  border: 1px solid
    var(--finance-border);

  border-radius: 14px;

  background:
    var(--finance-surface-soft);
}

.visitPaymentStateTop,
.visitPaymentStateMoney {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.visitPaymentStateTop {
  padding-bottom: 10px;
  margin-bottom: 10px;

  border-bottom: 1px solid
    var(--finance-border);
}

.visitPaymentStateTop > span,
.visitPaymentStateMoney span {
  display: block;

  font-size: 8px;

  color:
    var(--finance-text-muted);
}

.visitPaymentStateTop b,
.visitPaymentStatus {
  padding: 5px 8px;

  border: 1px solid transparent;
  border-radius: 999px;

  font-size: 8px;
  font-weight: 900;
}

.visitPaymentStateMoney > div:last-child {
  text-align: right;
}

.visitPaymentStateMoney strong {
  display: block;

  margin-top: 4px;

  font-size: 11px;

  color: var(--finance-text);
}

.visitPaymentStateMoney
> div:last-child
strong {
  color: var(--finance-accent-2);
}


/* Статусы оплаты */

.is-unpaid {
  border-color:
    rgba(255, 105, 128, 0.2)
    !important;

  background:
    rgba(255, 75, 105, 0.08)
    !important;

  color: #ff8b9d
    !important;
}

.is-partial {
  border-color:
    rgba(255, 194, 73, 0.22)
    !important;

  background:
    rgba(255, 181, 45, 0.08)
    !important;

  color: #ffd06b
    !important;
}

.is-paid {
  border-color:
    rgba(78, 224, 145, 0.22)
    !important;

  background:
    rgba(48, 206, 118, 0.08)
    !important;

  color: #72e6a7
    !important;
}

.is-refunded,
.is-cancelled {
  border-color:
    rgba(255, 255, 255, 0.1)
    !important;

  background:
    rgba(255, 255, 255, 0.04)
    !important;

  color:
    rgba(255, 255, 255, 0.6)
    !important;
}


/* Кнопка оплаты */

.visitPaymentButton {
  position: relative;
  z-index: 1;

  display: flex;

  width: 100%;
  min-height: 48px;

  align-items: center;
  justify-content: center;
  gap: 8px;

  margin: 9px 0 3px;

  cursor: pointer;

  border: 1px solid
    rgba(99, 229, 165, 0.3);

  border-radius: 13px;

  background:
    radial-gradient(
      circle at top left,
      rgba(105, 255, 184, 0.13),
      transparent 45%
    ),
    linear-gradient(
      135deg,
      rgba(37, 178, 108, 0.18),
      rgba(20, 93, 68, 0.16)
    );

  box-shadow:
    inset 0 1px 0
    rgba(255, 255, 255, 0.08);

  color: #83f0b5;

  font: inherit;
  font-size: 11px;
  font-weight: 900;

  transition:
    transform 0.2s ease,
    filter 0.2s ease,
    box-shadow 0.2s ease;
}

.visitPaymentButton:hover {
  transform:
    translateY(-2px);

  filter:
    brightness(1.08);

  box-shadow:
    0 14px 28px
    rgba(29, 175, 102, 0.15);
}

.visitPaymentButton.is-paid {
  cursor: default;

  border-color:
    rgba(78, 224, 145, 0.18);

  background:
    rgba(48, 206, 118, 0.07);

  box-shadow: none;
}
/* =========================================================
   VISIT PAYMENT MODAL
   ========================================================= */

.visitPaymentModalOpen {
  overflow: hidden;
}

.visitPaymentOverlay {
  position: fixed;
  z-index: 10050;
  inset: 0;

  display: grid;
  place-items: center;

  padding: 24px;
}

.visitPaymentBackdrop {
  position: absolute;
  inset: 0;

  background:
    rgba(4, 2, 10, 0.78);

  backdrop-filter:
    blur(16px);

  -webkit-backdrop-filter:
    blur(16px);
}

.visitPaymentModal {
  position: relative;

  width: min(
    760px,
    100%
  );

  max-height: min(
    860px,
    calc(100vh - 48px)
  );

  overflow: auto;

  border: 1px solid
    rgba(190, 111, 255, 0.22);

  border-radius: 26px;

  background:
    radial-gradient(
      circle at 15% 0%,
      rgba(156, 74, 238, 0.2),
      transparent 35%
    ),
    linear-gradient(
      145deg,
      rgba(24, 15, 43, 0.99),
      rgba(8, 6, 18, 0.99)
    );

  box-shadow:
    0 42px 110px
    rgba(0, 0, 0, 0.65),
    inset 0 1px 0
    rgba(255, 255, 255, 0.06);

  color: #ffffff;
}


/* Заголовок */

.visitPaymentHeader {
  display: grid;

  grid-template-columns:
    48px
    1fr
    38px;

  gap: 14px;

  align-items: center;

  padding: 22px 24px;

  border-bottom: 1px solid
    rgba(255, 255, 255, 0.07);
}

.visitPaymentHeaderIcon {
  display: grid;

  width: 48px;
  height: 48px;

  place-items: center;

  border: 1px solid
    rgba(190, 111, 255, 0.2);

  border-radius: 15px;

  background:
    rgba(147, 70, 232, 0.1);

  font-size: 20px;
}

.visitPaymentEyebrow {
  display: block;

  margin-bottom: 5px;

  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.14em;

  color: #bd78ff;
}

.visitPaymentHeader h2 {
  margin: 0;

  font-size: 20px;
  letter-spacing: -0.02em;
}

.visitPaymentHeader p {
  margin: 5px 0 0;

  font-size: 9px;

  color:
    rgba(255, 255, 255, 0.4);
}

.visitPaymentClose {
  display: grid;

  width: 36px;
  height: 36px;

  cursor: pointer;

  place-items: center;

  border: 1px solid
    rgba(255, 255, 255, 0.08);

  border-radius: 11px;

  background:
    rgba(255, 255, 255, 0.035);

  color:
    rgba(255, 255, 255, 0.58);
}

.visitPaymentClose:hover {
  background:
    rgba(255, 255, 255, 0.07);

  color: #ffffff;
}

.visitPaymentContent {
  padding: 22px 24px 24px;
}


/* Финансовая сводка */

.visitPaymentOverview {
  position: relative;

  display: grid;

  grid-template-columns:
    repeat(
      3,
      minmax(0, 1fr)
    );

  gap: 10px;

  margin-bottom: 18px;
}

.visitPaymentOverview > div {
  padding: 14px;

  border: 1px solid
    rgba(255, 255, 255, 0.065);

  border-radius: 14px;

  background:
    rgba(255, 255, 255, 0.025);
}

.visitPaymentOverview span {
  display: block;

  margin-bottom: 7px;

  font-size: 8px;
  font-weight: 800;

  color:
    rgba(255, 255, 255, 0.4);
}

.visitPaymentOverview strong {
  font-size: 16px;
}

.visitPaymentRemainingCard {
  border-color:
    rgba(190, 111, 255, 0.16)
    !important;

  background:
    rgba(147, 70, 232, 0.07)
    !important;
}

.visitPaymentRemainingCard strong {
  color: #ce8dff;
}

.visitPaymentStatus {
  position: absolute;

  top: -8px;
  right: -8px;
}


/* Форма оплаты */

.visitPaymentForm,
.visitPaymentHistory,
.visitPaymentSuccess {
  padding: 17px;

  border: 1px solid
    rgba(255, 255, 255, 0.07);

  border-radius: 18px;

  background:
    rgba(255, 255, 255, 0.022);
}

.visitPaymentAmountField > span,
.visitPaymentMethodsLabel {
  display: block;

  margin-bottom: 7px;

  font-size: 8px;
  font-weight: 800;

  color:
    rgba(255, 255, 255, 0.4);
}

.visitPaymentAmountField > div {
  display: flex;
  align-items: center;

  border: 1px solid
    rgba(188, 104, 255, 0.2);

  border-radius: 14px;

  background:
    rgba(8, 5, 16, 0.48);
}

.visitPaymentAmountField input {
  width: 100%;

  padding: 14px;

  border: 0;
  outline: 0;

  background: transparent;

  color: #ffffff;

  font: inherit;
  font-size: 20px;
  font-weight: 900;
}

.visitPaymentAmountField b {
  padding-right: 15px;

  color: #c98cff;
}


/* Быстрые суммы */

.visitPaymentQuickAmounts {
  display: flex;

  gap: 8px;

  margin: 9px 0 16px;
}

.visitPaymentQuickAmounts button {
  padding: 7px 10px;

  cursor: pointer;

  border: 1px solid
    rgba(255, 255, 255, 0.08);

  border-radius: 9px;

  background:
    rgba(255, 255, 255, 0.035);

  color:
    rgba(255, 255, 255, 0.62);

  font: inherit;
  font-size: 8px;
  font-weight: 800;
}

.visitPaymentQuickAmounts button:hover {
  border-color:
    rgba(190, 111, 255, 0.22);

  background:
    rgba(147, 70, 232, 0.09);

  color: #deb2ff;
}


/* Способы оплаты */

.visitPaymentMethods {
  display: grid;

  grid-template-columns:
    repeat(
      3,
      minmax(0, 1fr)
    );

  gap: 8px;
}

.visitPaymentMethods button {
  display: flex;

  min-height: 70px;

  cursor: pointer;

  flex-direction: column;
  align-items: center;
  justify-content: center;

  gap: 7px;

  border: 1px solid
    rgba(255, 255, 255, 0.07);

  border-radius: 13px;

  background:
    rgba(255, 255, 255, 0.025);

  color:
    rgba(255, 255, 255, 0.58);

  font: inherit;

  transition:
    border-color 0.2s ease,
    background 0.2s ease,
    transform 0.2s ease;
}

.visitPaymentMethods button:hover {
  transform:
    translateY(-2px);

  border-color:
    rgba(190, 111, 255, 0.2);
}

.visitPaymentMethods button span {
  font-size: 17px;
}

.visitPaymentMethods button b {
  font-size: 8px;
}

.visitPaymentMethods button.active {
  border-color:
    rgba(190, 111, 255, 0.34);

  background:
    rgba(147, 70, 232, 0.12);

  box-shadow:
    inset 0 0 0 1px
    rgba(190, 111, 255, 0.08);

  color: #e1b9ff;
}


/* Провести оплату */

.visitPaymentSubmit {
  display: flex;

  width: 100%;
  min-height: 50px;

  align-items: center;
  justify-content: space-between;

  margin-top: 14px;
  padding: 0 17px;

  cursor: pointer;

  border: 1px solid
    rgba(220, 175, 255, 0.25);

  border-radius: 13px;

  background:
    linear-gradient(
      135deg,
      #a94dff,
      #7139db
    );

  box-shadow:
    0 15px 32px
    rgba(111, 44, 190, 0.28),
    inset 0 1px 0
    rgba(255, 255, 255, 0.16);

  color: #ffffff;

  font: inherit;
  font-size: 10px;
  font-weight: 900;

  transition:
    transform 0.2s ease,
    filter 0.2s ease;
}

.visitPaymentSubmit:hover {
  transform:
    translateY(-2px);

  filter:
    brightness(1.08);
}

.visitPaymentSubmit:disabled {
  cursor: wait;

  opacity: 0.68;

  transform: none;
}


/* История транзакций */

.visitPaymentHistory {
  margin-top: 14px;
}

.visitPaymentHistoryHead {
  display: flex;

  align-items: center;
  justify-content: space-between;

  margin-bottom: 11px;
}

.visitPaymentHistoryHead span,
.visitPaymentHistoryHead strong {
  display: block;
}

.visitPaymentHistoryHead span {
  margin-bottom: 4px;

  font-size: 7px;
  font-weight: 900;
  letter-spacing: 0.12em;

  color: #b66dff;
}

.visitPaymentHistoryHead strong {
  font-size: 11px;
}

.visitPaymentHistoryHead > b {
  display: grid;

  width: 26px;
  height: 26px;

  place-items: center;

  border-radius: 8px;

  background:
    rgba(147, 70, 232, 0.1);

  font-size: 9px;

  color: #c989ff;
}

.visitPaymentHistoryList {
  display: flex;

  flex-direction: column;

  gap: 7px;
}

.visitPaymentHistoryItem {
  display: grid;

  grid-template-columns:
    34px
    1fr
    auto;

  gap: 10px;

  align-items: center;

  padding: 10px;

  border: 1px solid
    rgba(255, 255, 255, 0.055);

  border-radius: 12px;

  background:
    rgba(255, 255, 255, 0.018);
}

.visitPaymentHistoryIcon {
  display: grid;

  width: 34px;
  height: 34px;

  place-items: center;

  border-radius: 10px;

  background:
    rgba(147, 70, 232, 0.09);

  font-size: 14px;
}

.visitPaymentHistoryMain strong,
.visitPaymentHistoryMain span,
.visitPaymentHistoryAmount strong,
.visitPaymentHistoryAmount span {
  display: block;
}

.visitPaymentHistoryMain strong,
.visitPaymentHistoryAmount strong {
  font-size: 9px;
}

.visitPaymentHistoryMain span,
.visitPaymentHistoryAmount span {
  margin-top: 4px;

  font-size: 7px;

  color:
    rgba(255, 255, 255, 0.35);
}

.visitPaymentHistoryAmount {
  text-align: right;
}

.visitPaymentHistoryAmount strong {
  color: #74e9a9;
}

.visitPaymentHistoryEmpty {
  padding: 18px;

  text-align: center;

  font-size: 9px;

  color:
    rgba(255, 255, 255, 0.34);
}


/* Полностью оплачено */

.visitPaymentSuccess {
  display: flex;

  flex-direction: column;
  align-items: center;

  margin-bottom: 14px;
  padding: 24px;

  text-align: center;
}

.visitPaymentSuccess div {
  display: grid;

  width: 48px;
  height: 48px;

  margin-bottom: 11px;

  place-items: center;

  border-radius: 50%;

  background:
    rgba(48, 206, 118, 0.12);

  color: #72e6a7;

  font-size: 20px;
}

.visitPaymentSuccess strong {
  font-size: 13px;
}

.visitPaymentSuccess span {
  margin-top: 6px;

  font-size: 9px;

  color:
    rgba(255, 255, 255, 0.4);
}


/* Загрузка */

.visitPaymentLoading {
  display: flex;

  min-height: 260px;

  flex-direction: column;
  align-items: center;
  justify-content: center;

  gap: 13px;

  color:
    rgba(255, 255, 255, 0.64);

  font-size: 11px;
}

.visitPaymentSpinner {
  width: 30px;
  height: 30px;

  border: 3px solid
    rgba(255, 255, 255, 0.08);

  border-top-color:
    #b760ff;

  border-radius: 50%;

  animation:
    visitPaymentSpin
    0.8s
    linear
    infinite;
}

@keyframes visitPaymentSpin {
  to {
    transform:
      rotate(360deg);
  }
}


/* Адаптация */

@media (
  max-width: 650px
) {
  .visitPaymentOverlay {
    padding: 10px;
  }

  .visitPaymentModal {
    max-height:
      calc(100vh - 20px);

    border-radius: 20px;
  }

  .visitPaymentHeader,
  .visitPaymentContent {
    padding: 17px;
  }

  .visitPaymentOverview {
    grid-template-columns: 1fr;
  }

  .visitPaymentMethods {
    grid-template-columns:
      repeat(
        2,
        minmax(0, 1fr)
      );
  }
}
/* =========================================================
   FINANCE DASHBOARD
