.financeKpiGrid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  margin-top: 16px;
}

.financeKpiCard,
.financePanel {
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.07);
  background:
    radial-gradient(
      circle at 100% 0%,
      rgba(151, 74, 225, 0.08),
      transparent 42%
    ),
    linear-gradient(
      145deg,
      rgba(23, 15, 39, 0.94),
      rgba(10, 7, 20, 0.96)
    );
  box-shadow:
    0 20px 50px rgba(0, 0, 0, 0.2),
    inset 0 1px 0 rgba(255, 255, 255, 0.035);
}

.financeKpiCard {
  min-height: 154px;
  padding: 18px;
  border-radius: 19px;
}

.financeKpiCard::after {
  content: "";
  position: absolute;
  right: -45px;
  bottom: -55px;
  width: 130px;
  height: 130px;
  border-radius: 50%;
  background: var(
    --finance-kpi-glow,
    rgba(167, 82, 255, 0.12)
  );
  filter: blur(22px);
}

.financeKpiCard.is-revenue {
  --finance-kpi-color: #8af0b6;
  --finance-kpi-glow: rgba(58, 219, 135, 0.15);
}

.financeKpiCard.is-profit {
  --finance-kpi-color: #c888ff;
  --finance-kpi-glow: rgba(164, 72, 255, 0.18);
}

.financeKpiCard.is-check {
  --finance-kpi-color: #79bfff;
  --finance-kpi-glow: rgba(67, 157, 255, 0.15);
}

.financeKpiCard.is-debt {
  --finance-kpi-color: #ffca66;
  --finance-kpi-glow: rgba(255, 174, 55, 0.16);
}

.financeKpiIcon {
  display: grid;
  width: 34px;
  height: 34px;
  margin-bottom: 15px;
  place-items: center;
  border: 1px solid
    color-mix(
      in srgb,
      var(--finance-kpi-color) 24%,
      transparent
    );
  border-radius: 10px;
  background:
    color-mix(
      in srgb,
      var(--finance-kpi-color) 9%,
      transparent
    );
  color: var(--finance-kpi-color);
  font-size: 14px;
  font-weight: 900;
}

.financeKpiCard > span,
.financeKpiCard > strong,
.financeKpiCard > small {
  position: relative;
  z-index: 1;
  display: block;
}

.financeKpiCard > span {
  margin-bottom: 7px;
  color: rgba(255, 255, 255, 0.4);
  font-size: 9px;
  font-weight: 750;
}

.financeKpiCard > strong {
  color: var(--finance-kpi-color);
  font-size: clamp(22px, 2.3vw, 31px);
  line-height: 1;
  font-weight: 900;
  letter-spacing: -0.035em;
}

.financeKpiCard > small {
  margin-top: 10px;
  color: rgba(255, 255, 255, 0.28);
  font-size: 8px;
}

.financeMainGrid,
.financeSecondaryGrid {
  display: grid;
  gap: 12px;
  margin-top: 12px;
}

.financeMainGrid {
  grid-template-columns:
    minmax(0, 1.65fr)
    minmax(300px, 0.75fr);
}

.financeSecondaryGrid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.financePanel {
  padding: 20px;
  border-radius: 21px;
}

.financePanelHead {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 16px;
}

.financePanelHead h2 {
  margin: 0;
  font-size: 15px;
  font-weight: 880;
}

.financePanelHead > strong {
  color: #c989ff;
  font-size: 20px;
  font-weight: 900;
}

.financePanelHead > b {
  display: grid;
  width: 30px;
  height: 30px;
  place-items: center;
  border-radius: 9px;
  background: rgba(147, 70, 232, 0.12);
  color: #c989ff;
  font-size: 10px;
}

.financeChartCanvas svg {
  display: block;
  width: 100%;
  height: 235px;
  overflow: visible;
}

.financeChartCanvas svg > line {
  stroke: rgba(255, 255, 255, 0.055);
  stroke-width: 1;
  stroke-dasharray: 5 7;
}

.financeChartArea {
  fill: url(#financeAreaGradient);
}

.financeChartLine {
  fill: none;
  stroke: #bd70ff;
  stroke-width: 4;
  stroke-linecap: round;
  stroke-linejoin: round;
  filter: drop-shadow(
    0 8px 10px rgba(174, 84, 255, 0.3)
  );
}

.financeChartPoints circle {
  fill: #0e091c;
  stroke: #d19aff;
  stroke-width: 3;
}

.financeChartLabels {
  display: flex;
  justify-content: space-between;
  padding: 0 8px;
  color: rgba(255, 255, 255, 0.28);
  font-size: 8px;
}

.financeChartEmpty {
  display: flex;
  min-height: 235px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
}

.financeChartEmpty > span {
  color: #af65f5;
  font-size: 35px;
}

.financeChartEmpty strong {
  margin-top: 8px;
  font-size: 12px;
}

.financeChartEmpty p {
  margin: 6px 0 0;
  color: rgba(255, 255, 255, 0.32);
  font-size: 9px;
}

.financeMethodsVisual {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 21px;
  padding-top: 4px;
}

.financeDonut {
  display: grid;
  width: 178px;
  height: 178px;
  place-items: center;
  border-radius: 50%;
  background: conic-gradient(
    #63e1a0 0 var(--cash),
    #a961ff var(--cash) var(--card),
    #55b9ff var(--card) 100%
  );
  box-shadow: 0 20px 45px rgba(0, 0, 0, 0.3);
}

.financeDonut::before {
  content: "";
  grid-area: 1 / 1;
  width: 128px;
  height: 128px;
  border-radius: 50%;
  background: #100a1d;
  box-shadow: inset 0 0 28px rgba(0, 0, 0, 0.45);
}

.financeDonut > div {
  z-index: 1;
  grid-area: 1 / 1;
  text-align: center;
}

.financeDonut strong,
.financeDonut span {
  display: block;
}

.financeDonut strong {
  font-size: 17px;
  font-weight: 900;
}

.financeDonut span {
  margin-top: 5px;
  color: rgba(255, 255, 255, 0.32);
  font-size: 8px;
}

.financeMethodsLegend {
  width: 100%;
}

.financeMethodsLegend > div {
  display: grid;
  grid-template-columns: 8px 1fr auto;
  gap: 9px;
  align-items: center;
  padding: 10px 0;
  border-top: 1px solid rgba(255, 255, 255, 0.055);
}

.financeMethodsLegend i {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

.financeMethodsLegend i.cash {
  background: #63e1a0;
}

.financeMethodsLegend i.card {
  background: #a961ff;
}

.financeMethodsLegend i.transfer {
  background: #55b9ff;
}

.financeMethodsLegend span {
  color: rgba(255, 255, 255, 0.46);
  font-size: 9px;
}

.financeMethodsLegend strong {
  font-size: 10px;
}

.financeDebtNumbers {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.financeDebtNumbers > div {
  padding: 12px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 13px;
  background: rgba(255, 255, 255, 0.022);
}

.financeDebtNumbers span,
.financeDebtNumbers strong {
  display: block;
}

.financeDebtNumbers span {
  margin-bottom: 7px;
  color: rgba(255, 255, 255, 0.34);
  font-size: 8px;
}

.financeDebtNumbers strong {
  font-size: 13px;
}

.financeDebtNumbers > div:last-child strong {
  color: #ffcc6d;
}

.financeProgress {
  height: 7px;
  margin-top: 14px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.055);
}

.financeProgress i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(
    90deg,
    #6fe5a6,
    #b25cff
  );
  box-shadow: 0 0 16px rgba(113, 225, 167, 0.3);
}

.financeInsightPanel {
  display: flex;
  align-items: center;
  gap: 15px;
  background:
    radial-gradient(
      circle at 0 0,
      rgba(164, 78, 255, 0.18),
      transparent 45%
    ),
    linear-gradient(
      145deg,
      rgba(30, 17, 51, 0.96),
      rgba(13, 8, 26, 0.98)
    );
}

.financeInsightIcon {
  display: grid;
  width: 48px;
  height: 48px;
  flex: 0 0 48px;
  place-items: center;
  border: 1px solid rgba(200, 135, 255, 0.22);
  border-radius: 15px;
  background: rgba(151, 74, 232, 0.11);
  box-shadow: 0 12px 28px rgba(106, 45, 184, 0.18);
  color: #d8a7ff;
  font-size: 20px;
}

.financeInsightPanel h2 {
  margin: 0;
  font-size: 14px;
}

.financeInsightPanel p {
  margin: 7px 0 0;
  color: rgba(255, 255, 255, 0.42);
  font-size: 9px;
  line-height: 1.55;
}

.financeTransactionsPanel {
  margin-top: 12px;
}

.financeTransactionsList {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.financeTransactionRow {
  display: grid;
  grid-template-columns: 38px 1fr auto;
  gap: 11px;
  align-items: center;
  padding: 11px 12px;
  border: 1px solid rgba(255, 255, 255, 0.055);
  border-radius: 13px;
  background: rgba(255, 255, 255, 0.018);
  transition:
    transform 0.18s ease,
    background 0.18s ease;
}

.financeTransactionRow:hover {
  transform: translateX(3px);
  background: rgba(255, 255, 255, 0.032);
}

.financeTransactionIcon {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border-radius: 11px;
  font-size: 15px;
  font-weight: 900;
}

.financeTransactionIcon.is-income {
  background: rgba(48, 206, 118, 0.1);
  color: #72e6a7;
}

.financeTransactionIcon.is-outcome {
  background: rgba(255, 71, 103, 0.1);
  color: #ff8297;
}

.financeTransactionMain strong,
.financeTransactionMain span,
.financeTransactionAmount strong,
.financeTransactionAmount span {
  display: block;
}

.financeTransactionMain strong,
.financeTransactionAmount strong {
  font-size: 10px;
}

.financeTransactionMain span,
.financeTransactionAmount span {
  margin-top: 4px;
  color: rgba(255, 255, 255, 0.32);
  font-size: 8px;
}

.financeTransactionAmount {
  text-align: right;
}

.financeTransactionAmount.is-income strong {
  color: #72e6a7;
}

.financeTransactionAmount.is-outcome strong {
  color: #ff8297;
}

.financeTransactionsEmpty {
  padding: 28px;
  text-align: center;
  color: rgba(255, 255, 255, 0.33);
  font-size: 10px;
}

@media (max-width: 1100px) {
  .financeKpiGrid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .financeMainGrid,
  .financeSecondaryGrid {
    grid-template-columns: 1fr;
  }

  .financeMethodsVisual {
    flex-direction: row;
  }
}

@media (max-width: 760px) {
  .financeDashboard {
    width: min(100% - 20px, 1480px);
    padding-top: 18px;
  }

  .financeHero {
    flex-direction: column;
    align-items: flex-start;
    padding: 22px;
  }

  .financeHeroActions {
    width: 100%;
    flex-direction: column;
    align-items: stretch;
  }

  .financePresetSwitch {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
  }

  .financeDateRange,
  .financeKpiGrid,
  .financeDebtNumbers {
    grid-template-columns: 1fr;
  }

  .financeMethodsVisual {
    flex-direction: column;
  }

  .financeTransactionRow {
    grid-template-columns: 36px 1fr;
  }

  .financeTransactionAmount {
    grid-column: 2;
    text-align: left;
  }
}
/* FINANCE CASHFLOW CHART */

