  align-items: center;
  gap: 7px;
  color: rgba(255, 255, 255, 0.42);
  font-size: 9px;
  font-weight: 750;
}

.financeCashflowLegend i {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

.financeCashflowLegend i.is-income {
  background: #63e1a0;
  box-shadow: 0 0 10px rgba(99, 225, 160, 0.35);
}

.financeCashflowLegend i.is-outcome {
  background: #ff738c;
  box-shadow: 0 0 10px rgba(255, 115, 140, 0.3);
}

.financeCashflowLegend i.is-net {
  background: #bd70ff;
  box-shadow: 0 0 10px rgba(189, 112, 255, 0.35);
}

.financeCashflowGrid {
  stroke: rgba(255, 255, 255, 0.055);
  stroke-width: 1;
  stroke-dasharray: 5 7;
}

.financeCashflowZeroLine {
  stroke: rgba(255, 255, 255, 0.14);
  stroke-width: 1.5;
}

.financeCashflowAxisLabel,
.financeCashflowDateLabel {
  fill: rgba(255, 255, 255, 0.28);
  font-size: 9px;
  font-weight: 700;
}

.financeIncomeBar {
  fill: url("#financeIncomeGradient");
  fill: #63e1a0;
  opacity: 0.86;
  filter: drop-shadow(
    0 6px 9px rgba(61, 213, 132, 0.2)
  );
}

.financeOutcomeBar {
  fill: #ff738c;
  opacity: 0.82;
  filter: drop-shadow(
    0 6px 9px rgba(255, 91, 119, 0.18)
  );
}

.financeNetLine {
  fill: none;
  stroke: #bd70ff;
  stroke-width: 3.5;
  stroke-linecap: round;
  stroke-linejoin: round;
  filter: drop-shadow(
    0 5px 8px rgba(189, 112, 255, 0.32)
  );
}

.financeNetPoint {
  fill: #100a1d;
  stroke: #d49bff;
  stroke-width: 3;
  filter: drop-shadow(
    0 4px 7px rgba(189, 112, 255, 0.35)
  );
}
/* =========================================================
   FINANCE EXPENSE MODAL
   ========================================================= */

.financeHeroActions {
  flex-wrap: wrap;
  justify-content: flex-end;
}

.financeAddExpenseButton {
  display: inline-flex;
  min-height: 46px;
  align-items: center;
  justify-content: center;
  gap: 9px;
  padding: 0 17px;
  cursor: pointer;
  border: 1px solid rgba(255, 112, 139, 0.26);
  border-radius: 13px;
  background:
    linear-gradient(
      135deg,
      rgba(255, 84, 116, 0.18),
      rgba(155, 55, 115, 0.13)
    );
  box-shadow:
    0 14px 30px rgba(94, 18, 58, 0.18),
    inset 0 1px 0 rgba(255, 255, 255, 0.055);
  color: #ff9bad;
  font: inherit;
  font-size: 10px;
  font-weight: 900;
  transition:
    transform 0.18s ease,
    border-color 0.18s ease,
    background 0.18s ease;
}

.financeAddExpenseButton:hover {
  transform: translateY(-2px);
  border-color: rgba(255, 130, 153, 0.42);
  background:
    linear-gradient(
      135deg,
      rgba(255, 84, 116, 0.26),
      rgba(155, 55, 115, 0.2)
    );
}

.financeAddExpenseButton span {
  display: grid;
  width: 22px;
  height: 22px;
  place-items: center;
  border-radius: 7px;
  background: rgba(255, 112, 139, 0.12);
  font-size: 15px;
  line-height: 1;
}

body.financeExpenseModalOpen {
  overflow: hidden;
}

.financeExpenseOverlay {
  position: fixed;
  z-index: 12000;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}

.financeExpenseBackdrop {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(
      circle at 50% 25%,
      rgba(139, 62, 220, 0.15),
      transparent 38%
    ),
    rgba(3, 2, 10, 0.84);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}

.financeExpenseModal {
  position: relative;
  width: min(760px, 100%);
  max-height: calc(100vh - 48px);
  overflow: auto;
  border: 1px solid rgba(197, 119, 255, 0.2);
  border-radius: 25px;
  background:
    radial-gradient(
      circle at 0 0,
      rgba(170, 75, 255, 0.18),
      transparent 35%
    ),
    radial-gradient(
      circle at 100% 100%,
      rgba(255, 82, 119, 0.08),
      transparent 34%
    ),
    linear-gradient(
      145deg,
      rgba(29, 17, 49, 0.99),
      rgba(10, 7, 20, 0.99)
    );
  box-shadow:
    0 45px 110px rgba(0, 0, 0, 0.58),
    inset 0 1px 0 rgba(255, 255, 255, 0.055);
  color: #fff;
  animation:
    financeExpenseAppear
    0.22s ease-out;
}

.financeRefundModal {
  width: min(620px, 100%);
}

.financeRefundSummary {
  display: grid;
  gap: 12px;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
}

.financeRefundSummary > div {
  display: grid;
  gap: 5px;
  padding: 14px 16px;
  border: 1px solid
    rgba(255, 255, 255, 0.08);
  border-radius: 16px;
  background:
    rgba(255, 255, 255, 0.035);
}

.financeRefundSummary span {
  color:
    rgba(255, 255, 255, 0.48);
  font-size: 10px;
  font-weight: 700;
}

.financeRefundSummary strong {
  color: #fff;
  font-size: 20px;
  letter-spacing: -0.02em;
}

@keyframes financeExpenseAppear {
  from {
    transform: translateY(18px) scale(0.975);
    opacity: 0;
  }

  to {
    transform: translateY(0) scale(1);
    opacity: 1;
  }
}

.financeExpenseModal::-webkit-scrollbar {
  width: 7px;
}

.financeExpenseModal::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: rgba(187, 105, 255, 0.25);
}

.financeExpenseHeader {
  display: grid;
  grid-template-columns: 48px 1fr 40px;
  gap: 14px;
  align-items: center;
  padding: 22px 24px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.07);
}

.financeExpenseHeaderIcon {
  display: grid;
  width: 48px;
  height: 48px;
  place-items: center;
  border: 1px solid rgba(255, 112, 139, 0.24);
  border-radius: 15px;
  background: rgba(255, 75, 110, 0.1);
  box-shadow: 0 12px 28px rgba(123, 25, 68, 0.15);
  color: #ff8fa4;
  font-size: 24px;
  font-weight: 900;
}

.financeExpenseHeader > div:nth-child(2) > span {
  display: block;
  margin-bottom: 5px;
  color: #c47cff;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.14em;
}

.financeExpenseHeader h2 {
  margin: 0;
  font-size: 22px;
  font-weight: 900;
  letter-spacing: -0.025em;
}

.financeExpenseHeader p {
  margin: 5px 0 0;
  color: rgba(255, 255, 255, 0.38);
  font-size: 9px;
  line-height: 1.45;
}

.financeExpenseClose {
  display: grid;
  width: 40px;
  height: 40px;
  place-items: center;
  cursor: pointer;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.035);
  color: rgba(255, 255, 255, 0.45);
  font: inherit;
  font-size: 13px;
  transition:
    color 0.18s ease,
    background 0.18s ease;
}

.financeExpenseClose:hover {
  background: rgba(255, 82, 119, 0.1);
  color: #ff8fa4;
}

.financeExpenseForm {
  padding: 22px 24px 24px;
}

.financeExpenseError {
  margin-bottom: 14px;
  padding: 11px 13px;
  border: 1px solid rgba(255, 89, 120, 0.22);
  border-radius: 11px;
  background: rgba(255, 63, 99, 0.08);
  color: #ff9bad;
  font-size: 9px;
  font-weight: 750;
}

.financeExpenseAmountBlock {
  margin-bottom: 17px;
  padding: 16px;
  border: 1px solid rgba(255, 112, 139, 0.13);
  border-radius: 17px;
  background:
    radial-gradient(
      circle at 100% 0,
      rgba(255, 86, 120, 0.09),
      transparent 44%
    ),
    rgba(255, 255, 255, 0.018);
}

.financeExpenseAmountBlock label > span,
.financeExpenseField > span {
  display: block;
  margin: 0 0 8px 2px;
  color: rgba(255, 255, 255, 0.4);
  font-size: 8px;
  font-weight: 800;
}

.financeExpenseAmountInput {
  position: relative;
}

.financeExpenseAmountInput input {
  width: 100%;
  height: 64px;
  padding: 0 58px 0 17px;
  border: 1px solid rgba(255, 112, 139, 0.18);
  border-radius: 14px;
  outline: 0;
  background: rgba(4, 3, 11, 0.42);
  color: #ffb1bf;
  font: inherit;
  font-size: 29px;
  font-weight: 900;
  letter-spacing: -0.025em;
}

.financeExpenseAmountInput input:focus {
  border-color: rgba(255, 125, 150, 0.5);
  box-shadow:
    0 0 0 3px rgba(255, 91, 124, 0.07);
}

.financeExpenseAmountInput b {
  position: absolute;
  top: 50%;
  right: 18px;
  transform: translateY(-50%);
  color: #ff8fa4;
  font-size: 19px;
}

.financeExpenseGrid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 13px;
}

.financeExpenseField {
  display: block;
}

.financeExpenseWide {
  margin-top: 13px;
}

.financeExpenseField input,
.financeExpenseField select,
.financeExpenseField textarea {
  width: 100%;
  border: 1px solid rgba(255, 255, 255, 0.075);
  border-radius: 12px;
  outline: 0;
  background: rgba(5, 3, 13, 0.42);
  color: rgba(255, 255, 255, 0.78);
  font: inherit;
  font-size: 10px;
  font-weight: 700;
  transition:
    border-color 0.18s ease,
    box-shadow 0.18s ease;
}

.financeExpenseField input,
.financeExpenseField select {
  height: 45px;
  padding: 0 13px;
}

.financeExpenseField textarea {
  min-height: 82px;
  padding: 12px 13px;
  resize: vertical;
  line-height: 1.55;
}

.financeExpenseField input:focus,
.financeExpenseField select:focus,
.financeExpenseField textarea:focus {
  border-color: rgba(193, 112, 255, 0.42);
  box-shadow:
    0 0 0 3px rgba(164, 72, 255, 0.065);
}

.financeExpenseField input::placeholder,
.financeExpenseField textarea::placeholder {
  color: rgba(255, 255, 255, 0.21);
}

.financeExpenseField select {
  cursor: pointer;
  color-scheme: dark;
}

.financeExpenseField select option {
  background: #171022;
  color: #fff;
}

.financeExpenseField input[type="datetime-local"] {
  color-scheme: dark;
}

.financeExpenseHint {
  display: grid;
  grid-template-columns: 27px 1fr;
  gap: 10px;
  align-items: start;
  margin-top: 15px;
  padding: 12px;
  border: 1px solid rgba(124, 190, 255, 0.1);
  border-radius: 12px;
  background: rgba(71, 144, 255, 0.045);
}

.financeExpenseHint > span {
  display: grid;
  width: 27px;
  height: 27px;
  place-items: center;
  border-radius: 8px;
  background: rgba(84, 160, 255, 0.1);
  color: #82bfff;
  font-size: 10px;
  font-weight: 900;
}

.financeExpenseHint p {
  margin: 2px 0 0;
  color: rgba(255, 255, 255, 0.35);
  font-size: 8px;
  line-height: 1.55;
}

.financeExpenseFooter {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 19px;
  padding-top: 17px;
  border-top: 1px solid rgba(255, 255, 255, 0.065);
}

.financeExpenseCancel,
.financeExpenseSubmit {
  display: inline-flex;
  min-height: 44px;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 0 18px;
  cursor: pointer;
  border-radius: 12px;
  font: inherit;
  font-size: 10px;
  font-weight: 900;
}

.financeExpenseCancel {
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.03);
  color: rgba(255, 255, 255, 0.48);
}

.financeExpenseSubmit {
  min-width: 190px;
  border: 1px solid rgba(255, 112, 139, 0.25);
  background:
    linear-gradient(
      135deg,
      #ed4f72,
      #a846d5
    );
  box-shadow: 0 14px 28px rgba(168, 50, 117, 0.24);
  color: #fff;
}

.financeExpenseSubmit:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow: 0 18px 34px rgba(168, 50, 117, 0.32);
}

.financeExpenseSubmit:disabled,
.financeExpenseCancel:disabled {
  cursor: wait;
  opacity: 0.58;
}

.financeExpenseSubmit .visitPaymentSpinner {
  width: 17px;
  height: 17px;
}

@media (max-width: 900px) {
  .financeHeroActions {
    width: 100%;
  }

  .financeAddExpenseButton {
    flex: 1;
  }
}

@media (max-width: 640px) {
  .financeExpenseOverlay {
    align-items: flex-end;
    padding: 0;
  }

  .financeExpenseModal {
    width: 100%;
    max-height: 92vh;
    border-right: 0;
    border-bottom: 0;
    border-left: 0;
    border-radius: 23px 23px 0 0;
  }

  .financeExpenseHeader {
    grid-template-columns: 42px 1fr 38px;
    padding: 18px 16px;
  }

  .financeExpenseHeaderIcon {
    width: 42px;
    height: 42px;
  }

  .financeExpenseForm {
    padding: 17px 16px 22px;
  }

  .financeExpenseGrid {
    grid-template-columns: 1fr;
  }

  .financeRefundSummary {
    grid-template-columns: 1fr;
  }

  .financeExpenseFooter {
    flex-direction: column-reverse;
  }

  .financeExpenseCancel,
  .financeExpenseSubmit {
    width: 100%;
  }
}
.financeExpenseAmountInput
input[type="number"] {
  appearance: textfield;
  -moz-appearance: textfield;
}

.financeExpenseAmountInput
input[type="number"]::-webkit-inner-spin-button,
.financeExpenseAmountInput
input[type="number"]::-webkit-outer-spin-button {
  margin: 0;
  appearance: none;
  -webkit-appearance: none;
}
.deleteModalOverlay.is-success
.deleteModal {
  border-color: rgba(91, 232, 158, 0.28);
  background:
    radial-gradient(
      circle at top,
      rgba(66, 222, 142, 0.16),
      transparent 36%
    ),
    linear-gradient(
      145deg,
      rgba(20, 48, 39, 0.98),
      rgba(9, 18, 19, 0.99)
    );
  box-shadow:
    0 34px 100px rgba(0, 0, 0, 0.65),
    0 0 46px rgba(70, 224, 146, 0.16);
}

.deleteModalOverlay.is-success
.deleteIcon {
  border-color: rgba(103, 239, 170, 0.3);
  background: rgba(71, 222, 145, 0.12);
  box-shadow: 0 0 34px rgba(70, 224, 146, 0.2);
  color: #72e6a7;
}

.deleteModalOverlay.is-success
.deleteButtons .primary {
  color: #071510;
  background:
    linear-gradient(
      135deg,
      #7ce9ad,
      #45c987
    );
  border-color: rgba(151, 245, 192, 0.35);
  box-shadow:
    0 14px 32px rgba(69, 201, 135, 0.24);
}

.deleteModalOverlay.is-success
.deleteButtons .primary:hover {
  transform: translateY(-1px);
  box-shadow:
    0 18px 42px rgba(69, 201, 135, 0.34);
}
.financeCashflowValueLabel {
  font-size: 9px;
  font-weight: 900;
}

.financeCashflowValueLabel.is-income {
  fill: #72e6a7;
}

.financeCashflowValueLabel.is-outcome {
  fill: #ff8ba0;
}
/* =========================================
   FINANCE — INTERNAL NAVIGATION
   ========================================= */

.financeSectionNavigation {
  position: relative;
  z-index: 4;

  display: flex;
  align-items: center;
  gap: 8px;

  width: 100%;
  padding: 8px;

  overflow-x: auto;
  scrollbar-width: none;

  border: 1px solid
    rgba(255, 255, 255, 0.09);
  border-radius: 22px;

  background:
    linear-gradient(
      135deg,
      rgba(35, 20, 58, 0.88),
      rgba(12, 9, 27, 0.92)
    );

  box-shadow:
    0 18px 55px
      rgba(0, 0, 0, 0.22),
    inset 0 1px 0
      rgba(255, 255, 255, 0.04);

  backdrop-filter: blur(24px);
}

.financeSectionNavigation::-webkit-scrollbar {
  display: none;
}

.financeSectionButton {
  position: relative;

  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;

  min-width: max-content;
  min-height: 48px;

  padding: 0 18px;

  border: 1px solid transparent;
  border-radius: 16px;

  color: rgba(255, 255, 255, 0.58);
  background: transparent;

  font: inherit;
  cursor: pointer;

  transition:
    color 0.2s ease,
    background 0.2s ease,
    border-color 0.2s ease,
    transform 0.2s ease,
    box-shadow 0.2s ease;
}

.financeSectionButton span {
  display: grid;
  place-items: center;

  width: 25px;
  height: 25px;

  border-radius: 9px;

  color: rgba(255, 255, 255, 0.7);
  background:
    rgba(255, 255, 255, 0.055);

  font-size: 14px;
}

.financeSectionButton strong {
  font-size: 13px;
  font-weight: 750;
  letter-spacing: 0.01em;
}

.financeSectionButton small {
  padding: 3px 6px;

  border-radius: 999px;

  color: rgba(255, 255, 255, 0.38);
  background:
    rgba(255, 255, 255, 0.055);

  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.financeSectionButton:not(:disabled):hover {
  color: #fff;

  border-color:
    color-mix(
      in srgb,
      var(--accent-color, #a855f7)
      35%,
      rgba(255, 255, 255, 0.09)
    );

  background:
    color-mix(
      in srgb,
      var(--accent-color, #a855f7)
      10%,
      rgba(255, 255, 255, 0.035)
    );

  transform: translateY(-1px);
}

.financeSectionButton.active {
  color: #fff;

  border-color:
    color-mix(
      in srgb,
      var(--accent-color, #a855f7)
      62%,
      rgba(255, 255, 255, 0.12)
    );

  background:
    linear-gradient(
      135deg,
      color-mix(
        in srgb,
        var(--accent-color, #a855f7)
        32%,
        rgba(255, 255, 255, 0.06)
      ),
      color-mix(
        in srgb,
        var(--accent-color, #a855f7)
        14%,
        rgba(15, 10, 29, 0.75)
      )
    );

  box-shadow:
    0 0 0 1px
      color-mix(
        in srgb,
        var(--accent-color, #a855f7)
        18%,
        transparent
      ),
    0 12px 30px
      color-mix(
        in srgb,
        var(--accent-color, #a855f7)
        20%,
        transparent
      );
}

.financeSectionButton.active span {
  color: #fff;

  background:
    color-mix(
      in srgb,
      var(--accent-color, #a855f7)
      40%,
      rgba(255, 255, 255, 0.1)
    );

  box-shadow:
    0 0 18px
      var(
        --accent-glow,
        rgba(168, 85, 247, 0.35)
      );
}

.financeSectionButton.is-disabled {
  opacity: 0.42;
  cursor: default;
}


/* =========================================
   FINANCE — OPERATIONS HERO
   ========================================= */

.financeOperationsHero {
  overflow: hidden;
}

.financeOperationsHero::after {
  content: "↕";

  position: absolute;
  right: 55px;
  bottom: -70px;

  color:
    color-mix(
      in srgb,
      var(--accent-color, #a855f7)
      10%,
      transparent
    );

  font-size: 210px;
  font-weight: 900;
  line-height: 1;

  pointer-events: none;
}


/* =========================================
   FINANCE — OPERATIONS FILTERS
   ========================================= */

.financeOperationsFilters {
  display: grid;
  grid-template-columns:
    minmax(220px, 1.5fr)
    minmax(160px, 0.8fr)
    minmax(160px, 0.8fr)
    minmax(145px, 0.65fr)
    minmax(145px, 0.65fr);

  gap: 14px;

  padding: 20px;

  border: 1px solid
    rgba(255, 255, 255, 0.09);
  border-radius: 24px;

  background:
    linear-gradient(
      135deg,
      rgba(26, 16, 46, 0.9),
      rgba(10, 8, 23, 0.94)
    );

  box-shadow:
    0 20px 60px
      rgba(0, 0, 0, 0.2),
    inset 0 1px 0
      rgba(255, 255, 255, 0.035);

  backdrop-filter: blur(22px);
}

.financeOperationsFilters label {
  display: flex;
  flex-direction: column;
  gap: 8px;

  min-width: 0;
}

.financeOperationsFilters label > span {
  padding-left: 3px;

  color: rgba(255, 255, 255, 0.48);

  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.financeOperationsFilters input,
.financeOperationsFilters select {
  width: 100%;
  min-width: 0;
  height: 48px;

  padding: 0 14px;

  border: 1px solid
    rgba(255, 255, 255, 0.1);
  border-radius: 14px;
  outline: none;

  color: rgba(255, 255, 255, 0.9);
  background:
    rgba(6, 5, 17, 0.62);

  font: inherit;
  font-size: 13px;

  color-scheme: dark;

  transition:
    border-color 0.2s ease,
    box-shadow 0.2s ease,
    background 0.2s ease;
}

.financeOperationsFilters input::placeholder {
  color: rgba(255, 255, 255, 0.28);
}

.financeOperationsFilters input:focus,
.financeOperationsFilters select:focus {
  border-color:
    var(--accent-color, #a855f7);

  background:
    color-mix(
      in srgb,
      var(--accent-color, #a855f7)
      7%,
      rgba(6, 5, 17, 0.72)
    );

  box-shadow:
    0 0 0 3px
      color-mix(
        in srgb,
        var(--accent-color, #a855f7)
        14%,
        transparent
      );
}

.financeOperationsFilterActions {
  grid-column: 1 / -1;

  display: flex;
  justify-content: flex-end;
  gap: 10px;

  padding-top: 4px;
}

.financeOperationsFilterActions button {
  min-height: 42px;
  padding: 0 20px;

  border-radius: 13px;

  color: #fff;
  font: inherit;
  font-size: 12px;
  font-weight: 800;

  cursor: pointer;

  transition:
    transform 0.2s ease,
    filter 0.2s ease,
    border-color 0.2s ease;
}

.financeOperationsApply {
  border: 1px solid
    color-mix(
      in srgb,
      var(--accent-color, #a855f7)
      70%,
      white
    );

  background:
    linear-gradient(
      135deg,
      var(--accent-color, #a855f7),
      color-mix(
        in srgb,
        var(--accent-color, #a855f7)
        70%,
        #5011a5
      )
    );

  box-shadow:
    0 10px 25px
      var(
        --accent-glow,
        rgba(168, 85, 247, 0.25)
      );
}

.financeOperationsReset {
  border: 1px solid
    rgba(255, 255, 255, 0.1);

  background:
    rgba(255, 255, 255, 0.045);
}

.financeOperationsFilterActions button:hover {
  transform: translateY(-1px);
  filter: brightness(1.08);
}


/* =========================================
   FINANCE — OPERATIONS JOURNAL
   ========================================= */

.financeOperationsPanel {
  overflow: hidden;
}

.financeOperationsList {
  display: flex;
  flex-direction: column;
  gap: 10px;

  margin-top: 18px;
}

.financeOperationCard {
  position: relative;

  display: grid;
  grid-template-columns:
    48px
    minmax(0, 1fr)
    auto;

  align-items: center;
  gap: 15px;

  min-height: 82px;
  padding: 15px 18px;

  overflow: hidden;

  border: 1px solid
    rgba(255, 255, 255, 0.075);
  border-radius: 18px;

  background:
    linear-gradient(
      135deg,
      rgba(255, 255, 255, 0.04),
      rgba(255, 255, 255, 0.018)
    );

  transition:
    transform 0.2s ease,
    border-color 0.2s ease,
    background 0.2s ease;
}

.financeOperationCard::before {
  content: "";

  position: absolute;
  left: 0;
  top: 16px;
  bottom: 16px;

  width: 2px;
  border-radius: 999px;

  background:
    var(--accent-color, #a855f7);

  opacity: 0.45;
}

.financeOperationCard:hover {
  border-color:
    color-mix(
      in srgb,
      var(--accent-color, #a855f7)
      28%,
      rgba(255, 255, 255, 0.1)
    );

  background:
    color-mix(
      in srgb,
      var(--accent-color, #a855f7)
      5%,
      rgba(255, 255, 255, 0.035)
    );

  transform: translateY(-1px);
}

.financeOperationContent {
  min-width: 0;
}

.financeOperationTitle {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.financeOperationTitle strong {
  overflow: hidden;

  color: rgba(255, 255, 255, 0.94);

  font-size: 14px;
  font-weight: 800;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.financeOperationTitle span {
  overflow: hidden;

  color: rgba(255, 255, 255, 0.43);

  font-size: 11px;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.financeOperationContent p {
  margin: 7px 0 0;

  overflow: hidden;

  color: rgba(255, 255, 255, 0.57);

  font-size: 11px;
  line-height: 1.45;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.financeOperationContent p b {
  color: rgba(255, 255, 255, 0.72);
}

.financeOperationContent small {
  display: block;

  margin-top: 7px;

  overflow: hidden;

  color: rgba(255, 255, 255, 0.29);

  font-size: 9px;
  letter-spacing: 0.03em;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.financeOperationAmount {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 7px;

  min-width: 115px;
}

.financeOperationAmount strong {
  color: rgba(255, 255, 255, 0.9);

  font-size: 15px;
  font-weight: 900;
  white-space: nowrap;
}

.financeOperationAmount.is-income strong {
  color: #63e6a3;

  text-shadow:
    0 0 18px
      rgba(99, 230, 163, 0.18);
}

.financeOperationAmount.is-outcome strong {
  color: #ff708d;

  text-shadow:
    0 0 18px
      rgba(255, 112, 141, 0.16);
}

.financeOperationStatus {
  display: inline-flex;
  align-items: center;

  min-height: 23px;
  padding: 0 9px;

  border: 1px solid
    rgba(255, 255, 255, 0.09);
  border-radius: 999px;

  color: rgba(255, 255, 255, 0.48);
  background:
    rgba(255, 255, 255, 0.035);

  font-size: 9px;
  font-weight: 800;
}

.financeOperationStatus.is-completed {
  color: #63e6a3;
  border-color:
    rgba(99, 230, 163, 0.2);
  background:
    rgba(99, 230, 163, 0.07);
}

.financeOperationStatus.is-pending {
  color: #ffc85c;
  border-color:
    rgba(255, 200, 92, 0.22);
  background:
    rgba(255, 200, 92, 0.07);
}

.financeOperationStatus.is-cancelled,
.financeOperationStatus.is-failed {
  color: #ff708d;
  border-color:
    rgba(255, 112, 141, 0.22);
  background:
    rgba(255, 112, 141, 0.07);
}

.financeOperationsPagination {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;

  margin-top: 18px;
  padding-top: 18px;

  border-top: 1px solid
    rgba(255, 255, 255, 0.07);
}

.financeOperationsPagination > span {
  color: rgba(255, 255, 255, 0.4);

  font-size: 11px;
  font-weight: 650;
}

.financeOperationsPagination > div {
  display: flex;
  gap: 9px;
}

.financeOperationsPagination button {
  min-height: 39px;
  padding: 0 15px;

  border: 1px solid
    rgba(255, 255, 255, 0.1);
  border-radius: 12px;

  color: rgba(255, 255, 255, 0.76);
  background:
    rgba(255, 255, 255, 0.045);

  font: inherit;
  font-size: 11px;
  font-weight: 750;

  cursor: pointer;

  transition:
    border-color 0.2s ease,
    background 0.2s ease,
    transform 0.2s ease;
}

.financeOperationsPagination button:not(:disabled):hover {
  border-color:
    var(--accent-color, #a855f7);

  background:
    color-mix(
      in srgb,
      var(--accent-color, #a855f7)
      12%,
      rgba(255, 255, 255, 0.04)
    );

  transform: translateY(-1px);
}

.financeOperationsPagination button:disabled {
  opacity: 0.28;
  cursor: default;
}

.financeTransactionsEmpty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 7px;

  min-height: 180px;

  border: 1px dashed
    rgba(255, 255, 255, 0.09);
  border-radius: 18px;

  color: rgba(255, 255, 255, 0.4);
  background:
    rgba(255, 255, 255, 0.018);

  text-align: center;
}

.financeTransactionsEmpty strong {
  color: rgba(255, 255, 255, 0.76);
  font-size: 14px;
}

.financeTransactionsEmpty span {
  font-size: 11px;
}


/* =========================================
   FINANCE OPERATIONS — TABLET
   ========================================= */

@media (max-width: 1180px) {
  .financeOperationsFilters {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .financeOperationsSearch {
    grid-column: 1 / -1;
  }
}


/* =========================================
   FINANCE OPERATIONS — MOBILE
   ========================================= */

@media (max-width: 720px) {
  .financeSectionNavigation {
    gap: 6px;

    padding: 6px;

    border-radius: 18px;
  }

  .financeSectionButton {
    min-height: 43px;
    padding: 0 13px;

    border-radius: 13px;
  }

  .financeSectionButton strong {
    font-size: 11px;
  }

  .financeSectionButton small {
    display: none;
  }

  .financeOperationsHero::after {
    display: none;
  }

  .financeOperationsFilters {
    grid-template-columns: 1fr;

    gap: 12px;
    padding: 15px;

    border-radius: 19px;
  }

  .financeOperationsSearch {
    grid-column: auto;
  }

  .financeOperationsFilterActions {
    grid-column: auto;

    display: grid;
    grid-template-columns: 1fr 1fr;
  }

  .financeOperationsFilterActions button {
    width: 100%;
    padding: 0 12px;
  }

  .financeOperationCard {
    grid-template-columns:
      42px
      minmax(0, 1fr);

    gap: 11px;
    padding: 14px;

    border-radius: 16px;
  }

  .financeOperationAmount {
    grid-column: 2;

    flex-direction: row;
    align-items: center;
    justify-content: space-between;

    width: 100%;
    min-width: 0;

    padding-top: 8px;

    border-top: 1px solid
      rgba(255, 255, 255, 0.06);
  }

  .financeOperationAmount strong {
    font-size: 14px;
  }

  .financeOperationContent p {
    white-space: normal;
  }

  .financeOperationsPagination {
    align-items: stretch;
    flex-direction: column;
  }

  .financeOperationsPagination > div {
    display: grid;
    grid-template-columns: 1fr 1fr;
  }

  .financeOperationsPagination button {
    width: 100%;
  }
}
.financeOperationActions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;

  margin-top: 11px;
}

.financeOperationActions button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;

  min-height: 31px;
  padding: 0 11px;

  border: 1px solid
    rgba(255, 255, 255, 0.1);
  border-radius: 10px;

  color: rgba(255, 255, 255, 0.72);
  background:
    rgba(255, 255, 255, 0.045);

  font: inherit;
  font-size: 9px;
  font-weight: 800;

  cursor: pointer;

  transition:
    color 0.2s ease,
    border-color 0.2s ease,
    background 0.2s ease,
    transform 0.2s ease;
}

.financeOperationVisitButton:hover {
  color: #fff;

  border-color:
    var(--accent-color, #a855f7);

  background:
    color-mix(
      in srgb,
      var(--accent-color, #a855f7)
      14%,
      rgba(255, 255, 255, 0.04)
    );

  transform: translateY(-1px);
}

.financeOperationDocumentButton:hover {
  color: #63e6a3;

  border-color:
    rgba(99, 230, 163, 0.35);

  background:
    rgba(99, 230, 163, 0.08);

  transform: translateY(-1px);
}

.financeOperationCancelButton:hover {
  color: #ff8aa1;

  border-color:
    rgba(255, 112, 141, 0.38);

  background:
    rgba(255, 112, 141, 0.09);

  transform: translateY(-1px);
}

.financeOperationEditButton:hover {
  color: #ffd48b;

  border-color:
    rgba(255, 212, 139, 0.36);

  background:
    rgba(255, 212, 139, 0.08);

  transform: translateY(-1px);
}

.financeOperationActions button:disabled {
  opacity: 0.45;
  cursor: wait;
}

.financeOperationRefundState {
  display: inline-flex;
  align-items: center;
  min-height: 31px;
  padding: 0 11px;
  border: 1px solid
    rgba(244, 175, 84, 0.22);
  border-radius: 10px;
  color: #e4a34d;
  background:
    rgba(244, 175, 84, 0.09);
  font-size: 9px;
  font-weight: 800;
}

.financeOperationRefundButton {
  color: #e4a34d !important;
  border-color:
    rgba(244, 175, 84, 0.25) !important;
  background:
    rgba(244, 175, 84, 0.08) !important;
}

.financeOperationRefundButton:hover {
  color: #ffd18f !important;
  border-color:
    rgba(244, 175, 84, 0.44) !important;
  background:
    rgba(244, 175, 84, 0.16) !important;
  transform: translateY(-1px);
}

body[data-theme="white"]
  .financeOperationRefundState {
  color: #93570c;
  border-color:
    rgba(157, 94, 16, 0.2);
  background:
    rgba(157, 94, 16, 0.07);
}

body[data-theme="white"]
  .financeOperationRefundButton {
  color: #86500d !important;
  border-color:
    rgba(157, 94, 16, 0.22) !important;
  background:
    rgba(157, 94, 16, 0.07) !important;
}

.deleteModalOverlay.is-payment-cancel
  .deleteIcon {
  color: #ff8aa1;
  border-color:
    rgba(255, 112, 141, 0.28);
  background:
    rgba(255, 112, 141, 0.1);
}

@media (max-width: 720px) {
  .financeOperationActions {
    display: grid;
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .financeOperationActions button {
    width: 100%;
  }
}
/* =========================================
   FINANCE — EXPENSES
   ========================================= */

.financeExpensesDashboard {
  padding-bottom: 130px;
}


/* =========================================
   EXPENSES HERO
   ========================================= */

.financeExpensesHero {
  position: relative;
  overflow: hidden;
}

.financeExpensesHero::after {
  content: "−";

  position: absolute;
  right: 55px;
  bottom: -105px;

  color:
    color-mix(
      in srgb,
      #ff6485 10%,
      transparent
    );

  font-size: 260px;
  font-weight: 900;
  line-height: 1;

  pointer-events: none;
}

.financeExpensesHero > * {
  position: relative;
  z-index: 2;
}

.financeExpensesJournalButton {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;

  min-height: 48px;
  padding: 0 18px;

  border: 1px solid
    rgba(255, 255, 255, 0.11);
  border-radius: 15px;

  color: rgba(255, 255, 255, 0.75);
  background:
    rgba(255, 255, 255, 0.045);

  font: inherit;
  font-size: 12px;
  font-weight: 800;

  cursor: pointer;

  transition:
    color 0.2s ease,
    border-color 0.2s ease,
    background 0.2s ease,
    transform 0.2s ease;
}

.financeExpensesJournalButton:hover {
  color: #fff;

  border-color:
    var(--accent-color, #a855f7);

  background:
    color-mix(
      in srgb,
      var(--accent-color, #a855f7)
      12%,
      rgba(255, 255, 255, 0.04)
    );

  transform: translateY(-1px);
}


/* =========================================
   EXPENSE KPI CARDS
   ========================================= */

.financeExpenseKpiGrid {
  display: grid;
  grid-template-columns:
    repeat(5, minmax(0, 1fr));

  gap: 14px;
}

.financeExpenseKpi {
  position: relative;

  min-width: 0;
  min-height: 168px;
  padding: 20px;

  overflow: hidden;

  border: 1px solid
    rgba(255, 255, 255, 0.085);
  border-radius: 23px;

  background:
    linear-gradient(
      145deg,
      rgba(31, 20, 50, 0.94),
      rgba(11, 9, 25, 0.96)
    );

  box-shadow:
    0 18px 50px
      rgba(0, 0, 0, 0.2),
    inset 0 1px 0
      rgba(255, 255, 255, 0.035);

  transition:
    transform 0.2s ease,
    border-color 0.2s ease;
}

.financeExpenseKpi::after {
  content: "";

  position: absolute;
  right: -45px;
  bottom: -55px;

  width: 130px;
  height: 130px;

  border-radius: 50%;

  background:
    var(
      --expense-kpi-glow,
      rgba(168, 85, 247, 0.16)
    );

  filter: blur(28px);
  pointer-events: none;
}

.financeExpenseKpi:hover {
  border-color:
    rgba(255, 255, 255, 0.14);

  transform: translateY(-2px);
}

.financeExpenseKpi.is-total {
  --expense-kpi-color:
    #ff708d;

  --expense-kpi-glow:
    rgba(255, 112, 141, 0.2);
}

.financeExpenseKpi.is-purchases {
  --expense-kpi-color:
    #a970ff;

  --expense-kpi-glow:
    rgba(169, 112, 255, 0.2);
}

.financeExpenseKpi.is-salary {
  --expense-kpi-color:
    #ff75b5;

  --expense-kpi-glow:
    rgba(255, 117, 181, 0.18);
}

.financeExpenseKpi.is-fixed {
  --expense-kpi-color:
    #ffb85c;

  --expense-kpi-glow:
    rgba(255, 184, 92, 0.18);
}

.financeExpenseKpi.is-average {
  --expense-kpi-color:
    #56b8ff;

  --expense-kpi-glow:
    rgba(86, 184, 255, 0.18);
}

.financeExpenseKpiIcon {
  display: grid;
  place-items: center;

  width: 40px;
  height: 40px;
  margin-bottom: 18px;

  border: 1px solid
    color-mix(
      in srgb,
      var(--expense-kpi-color)
      38%,
      rgba(255, 255, 255, 0.08)
    );
  border-radius: 13px;

  color:
    var(--expense-kpi-color);

  background:
    color-mix(
      in srgb,
      var(--expense-kpi-color)
      11%,
      rgba(255, 255, 255, 0.025)
    );

  font-size: 17px;
  font-weight: 900;
}

.financeExpenseKpi > span {
  display: block;

  margin-bottom: 7px;

  color: rgba(255, 255, 255, 0.48);

  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.04em;
}

.financeExpenseKpi > strong {
  position: relative;
  z-index: 2;

  display: block;

  overflow: hidden;

  color:
    var(--expense-kpi-color);

  font-size: clamp(
    21px,
    2vw,
    31px
  );
  font-weight: 900;
  line-height: 1.05;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.financeExpenseKpi > small {
  display: block;

  margin-top: 10px;

  color: rgba(255, 255, 255, 0.32);

  font-size: 9px;
  line-height: 1.35;
}


/* =========================================
   EXPENSE MAIN GRID
   ========================================= */

.financeExpensesMainGrid {
  display: grid;
  grid-template-columns:
    minmax(0, 1.55fr)
    minmax(330px, 0.85fr);

  gap: 16px;
}

.financeExpenseTotalValue {
  color: #ff708d !important;
}


/* =========================================
   EXPENSE TREND CHART
   ========================================= */

.financeExpenseTrendChart {
  width: 100%;
  min-height: 280px;
  margin-top: 10px;

  overflow-x: auto;
  scrollbar-width: thin;
  scrollbar-color:
    rgba(255, 255, 255, 0.12)
    transparent;
}

.financeExpenseTrendChart svg {
  display: block;

  width: 100%;
  min-width: 650px;
  height: auto;
}

.financeExpenseGridLine {
  stroke:
    rgba(255, 255, 255, 0.07);
  stroke-width: 1;
  stroke-dasharray: 4 7;
}

.financeExpenseGridLabel,
.financeExpenseDateLabel {
  fill:
    rgba(255, 255, 255, 0.32);

  font-family: inherit;
  font-size: 9px;
  font-weight: 650;
}

.financeExpenseBar {
  fill: url("#financeExpenseGradient");
  fill: #ff6485;

  opacity: 0.82;

  filter:
    drop-shadow(
      0 5px 9px
      rgba(255, 100, 133, 0.16)
    );

  transition:
    opacity 0.2s ease;
}

.financeExpenseBarGroup:hover
.financeExpenseBar {
  opacity: 1;
}

.financeExpenseBarPoint {
  fill: #ffd1dc;
  stroke: #ff6485;
  stroke-width: 2;
}


/* =========================================
   EXPENSE CATEGORIES
   ========================================= */

.financeExpenseCategories {
  display: flex;
  flex-direction: column;
  gap: 9px;

  margin-top: 18px;
}

.financeExpenseCategory {
  display: grid;
  grid-template-columns:
    40px
    minmax(0, 1fr)
    auto;

  align-items: center;
  gap: 12px;

  padding: 11px;

  border: 1px solid
    rgba(255, 255, 255, 0.065);
  border-radius: 15px;

  background:
    rgba(255, 255, 255, 0.025);

  transition:
    border-color 0.2s ease,
    background 0.2s ease,
    transform 0.2s ease;
}

.financeExpenseCategory:hover {
  border-color:
    rgba(255, 255, 255, 0.12);

  background:
    rgba(255, 255, 255, 0.04);

  transform: translateX(2px);
}

.financeExpenseCategoryIcon {
  display: grid;
  place-items: center;

  width: 40px;
  height: 40px;

  border: 1px solid
    color-mix(
      in srgb,
      var(--category-color)
      32%,
      rgba(255, 255, 255, 0.07)
    );
  border-radius: 13px;

  background:
    color-mix(
      in srgb,
      var(--category-color)
      10%,
      rgba(255, 255, 255, 0.02)
    );

  font-size: 15px;
}

.financeExpenseCategoryMain {
  min-width: 0;
}

.financeExpenseCategoryMain > div:first-child {
  display: flex;
  justify-content: space-between;
  gap: 8px;

  margin-bottom: 8px;
}

.financeExpenseCategoryMain strong {
  overflow: hidden;

  color: rgba(255, 255, 255, 0.81);

  font-size: 11px;
  font-weight: 800;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.financeExpenseCategoryMain span {
  flex: 0 0 auto;

  color: rgba(255, 255, 255, 0.3);

  font-size: 8px;
}

.financeExpenseCategoryProgress {
  height: 4px;

  overflow: hidden;

  border-radius: 999px;

  background:
    rgba(255, 255, 255, 0.055);
}

.financeExpenseCategoryProgress i {
  display: block;

  height: 100%;
  border-radius: inherit;

  background:
    var(--category-color);

  box-shadow:
    0 0 12px
      color-mix(
        in srgb,
        var(--category-color)
        45%,
        transparent
      );
}

.financeExpenseCategoryAmount {
  display: flex;
  align-items: flex-end;
  flex-direction: column;
  gap: 4px;

  min-width: 82px;
}

.financeExpenseCategoryAmount strong {
  color: rgba(255, 255, 255, 0.88);

  font-size: 11px;
  font-weight: 850;
  white-space: nowrap;
}

.financeExpenseCategoryAmount span {
  color: rgba(255, 255, 255, 0.35);

  font-size: 9px;
}


/* =========================================
   PURCHASES / SALARIES / COUNTERPARTIES
   ========================================= */

.financeExpensesSecondaryGrid {
  display: grid;
  grid-template-columns:
    minmax(0, 1.25fr)
    minmax(330px, 0.75fr);

  gap: 16px;
}

.financeExpenseControlCards {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  gap: 13px;

  margin-top: 18px;
}

.financeExpenseControlCards > article {
  position: relative;

  min-width: 0;
  min-height: 205px;
  padding: 18px;

  overflow: hidden;

  border: 1px solid
    rgba(255, 255, 255, 0.08);
  border-radius: 19px;

  background:
    linear-gradient(
      145deg,
      rgba(255, 255, 255, 0.045),
      rgba(255, 255, 255, 0.018)
    );
}

.financeExpenseControlCards > article::after {
  content: "";

  position: absolute;
  right: -45px;
  bottom: -55px;

  width: 130px;
  height: 130px;

  border-radius: 50%;

  filter: blur(30px);
  pointer-events: none;
}

.financeExpenseControlCards
.is-purchase::after {
  background:
    rgba(169, 112, 255, 0.18);
}

.financeExpenseControlCards
.is-salary::after {
  background:
    rgba(255, 117, 181, 0.16);
}

.financeExpenseControlCards
> article
> div:first-child {
  display: flex;
  align-items: center;
  gap: 11px;
}

.financeExpenseControlCards
> article
> div:first-child
> span {
  display: grid;
  place-items: center;

  width: 42px;
  height: 42px;

  border: 1px solid
    rgba(255, 255, 255, 0.1);
  border-radius: 14px;

  background:
    rgba(255, 255, 255, 0.045);

  font-size: 17px;
}

.financeExpenseControlCards small {
  color:
    var(--accent-color, #a855f7);

  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.financeExpenseControlCards h3 {
  margin: 4px 0 0;

  color: rgba(255, 255, 255, 0.84);

  font-size: 12px;
}

.financeExpenseControlCards
> article
> strong {
  position: relative;
  z-index: 2;

  display: block;

  margin-top: 23px;

  color: rgba(255, 255, 255, 0.94);

  font-size: 25px;
  font-weight: 900;
}

.financeExpenseControlCards p {
  position: relative;
  z-index: 2;

  margin: 12px 0 0;

  color: rgba(255, 255, 255, 0.36);

  font-size: 9px;
  line-height: 1.55;
}

.financeExpenseCounterparties {
  display: flex;
  flex-direction: column;
  gap: 9px;

  margin-top: 18px;
}

.financeExpenseCounterparty {
  display: grid;
  grid-template-columns:
    29px
    minmax(0, 1fr)
    auto;

  align-items: center;
  gap: 11px;

  padding: 11px;

  border: 1px solid
    rgba(255, 255, 255, 0.065);
  border-radius: 14px;

  background:
    rgba(255, 255, 255, 0.025);
}

.financeExpenseCounterparty
> span {
  display: grid;
  place-items: center;

  width: 29px;
  height: 29px;

  border-radius: 9px;

  color:
    var(--accent-color, #a855f7);

  background:
    color-mix(
      in srgb,
      var(--accent-color, #a855f7)
      11%,
      rgba(255, 255, 255, 0.025)
    );

  font-size: 9px;
  font-weight: 900;
}

.financeExpenseCounterparty div {
  min-width: 0;
}

.financeExpenseCounterparty
div strong {
  display: block;

  overflow: hidden;

  color: rgba(255, 255, 255, 0.8);

  font-size: 11px;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.financeExpenseCounterparty
div small {
  display: block;

  margin-top: 4px;

  overflow: hidden;

  color: rgba(255, 255, 255, 0.3);

  font-size: 8px;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.financeExpenseCounterparty
> b {
  color: #ff8099;

  font-size: 11px;
  white-space: nowrap;
}


/* =========================================
   EXPENSES — RESPONSIVE
   ========================================= */

@media (max-width: 1280px) {
  .financeExpenseKpiGrid {
    grid-template-columns:
      repeat(3, minmax(0, 1fr));
  }

  .financeExpensesMainGrid,
  .financeExpensesSecondaryGrid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 820px) {
  .financeExpenseKpiGrid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .financeExpenseControlCards {
    grid-template-columns: 1fr;
  }

  .financeExpensesHero::after {
    display: none;
  }
}

@media (max-width: 560px) {
  .financeExpenseKpiGrid {
    grid-template-columns: 1fr;
  }

  .financeExpenseKpi {
    min-height: 150px;
  }

  .financeExpenseCategory {
    grid-template-columns:
      38px
      minmax(0, 1fr);
  }

  .financeExpenseCategoryAmount {
    grid-column: 2;

    align-items: center;
    flex-direction: row;
    justify-content: space-between;

    width: 100%;
    min-width: 0;

    padding-top: 7px;
  }

  .financeExpenseCounterparty {
    grid-template-columns:
      29px
      minmax(0, 1fr);
  }

  .financeExpenseCounterparty
  > b {
    grid-column: 2;
  }

  .financeExpensesJournalButton,
  #financeExpensesAddButton {
    width: 100%;
  }
}
/* =========================================================
   FINANCE — PURCHASES
   ========================================================= */

.financePurchasesPanel {
  margin-top: 22px;
  padding: 24px;
  border: 1px solid rgba(168, 85, 247, 0.2);
  border-radius: 26px;
  background:
    radial-gradient(
      circle at 90% 0%,
      rgba(168, 85, 247, 0.12),
      transparent 36%
    ),
    linear-gradient(
      145deg,
      rgba(31, 20, 54, 0.94),
      rgba(12, 11, 30, 0.97)
    );
  box-shadow:
    0 22px 60px rgba(0, 0, 0, 0.24),
    inset 0 1px 0 rgba(255, 255, 255, 0.04);
}

.financePurchasesPanelHead {
