  color: var(--text-secondary, #aaa4b9);
  font-size: 13px;
  font-weight: 700;
}

#financePurchaseCreateButton {
  min-height: 44px;
  padding: 0 18px;
  border: 1px solid rgba(192, 132, 252, 0.5);
