.financePurchaseCard:hover {
  transform: translateY(-2px);
  border-color: rgba(192, 132, 252, 0.35);
  background: rgba(168, 85, 247, 0.075);
  box-shadow: 0 14px 32px rgba(0, 0, 0, 0.2);
}

.financePurchaseCardIcon {
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  border: 1px solid rgba(192, 132, 252, 0.28);
  border-radius: 15px;
  background: rgba(168, 85, 247, 0.11);
  font-size: 21px;
}

.financePurchaseCardMain {
  min-width: 0;
}

.financePurchaseCardTitle {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 6px;
}

.financePurchaseCardTitle strong {
  overflow: hidden;
  color: var(--text-primary, #fff);
  font-size: 15px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.financePurchaseCardMeta {
  display: flex;
  flex-wrap: wrap;
  gap: 7px 13px;
  color: var(--text-secondary, #918ba0);
  font-size: 12px;
}

.financePurchaseCardAmount {
  min-width: 125px;
  text-align: right;
}

.financePurchaseCardAmount strong {
  display: block;
  color: #ffffff;
  font-size: 18px;
}

.financePurchaseCardAmount span {
  display: block;
  margin-top: 4px;
  color: var(--text-secondary, #8c8599);
  font-size: 11px;
}

.financePurchaseCardArrow {
  color: var(--accent-color, #b267ff);
  font-size: 20px;
  opacity: 0.65;
  transition: transform 0.18s ease;
}

.financePurchaseCard:hover .financePurchaseCardArrow {
  transform: translateX(3px);
  opacity: 1;
}

.financePurchaseStatus,
.financePurchasePaymentStatus {
  display: inline-flex;
  align-items: center;
  min-height: 26px;
  padding: 0 10px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.04);
  font-size: 11px;
  font-weight: 800;
}

.financePurchaseStatus.is-draft {
  border-color: rgba(148, 163, 184, 0.25);
  color: #cbd5e1;
}

.financePurchaseStatus.is-ordered,
.financePurchasePaymentStatus.is-partial {
  border-color: rgba(250, 204, 21, 0.3);
  background: rgba(250, 204, 21, 0.08);
  color: #facc15;
}

.financePurchaseStatus.is-received,
.financePurchasePaymentStatus.is-paid {
  border-color: rgba(52, 211, 153, 0.3);
  background: rgba(52, 211, 153, 0.08);
  color: #5ee9ad;
}

.financePurchaseStatus.is-cancelled,
.financePurchasePaymentStatus.is-unpaid {
  border-color: rgba(251, 113, 133, 0.28);
  background: rgba(251, 113, 133, 0.07);
  color: #fb8ba0;
}

.financePurchaseProgress {
  width: 100%;
  height: 5px;
  margin-top: 10px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.055);
}

.financePurchaseProgress > span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background:
    linear-gradient(
      90deg,
      var(--accent-color, #a855f7),
      #d946ef
    );
}

.financePurchasesEmpty {
  padding: 38px 20px;
  border: 1px dashed rgba(255, 255, 255, 0.1);
  border-radius: 18px;
  color: var(--text-secondary, #9790a5);
  text-align: center;
}

.financePurchasesPagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin-top: 18px;
}

.financePurchasesPagination button {
  min-height: 38px;
  padding: 0 15px;
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.04);
  color: var(--text-primary, #fff);
  font: inherit;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
}

.financePurchasesPagination button:hover:not(:disabled) {
  border-color: rgba(192, 132, 252, 0.38);
  background: rgba(168, 85, 247, 0.1);
}

.financePurchasesPagination button:disabled {
  cursor: not-allowed;
  opacity: 0.35;
}

/* =========================================================
   PURCHASE MODALS — SHARED
   ========================================================= */

body.financePurchaseModalOpen {
  overflow: hidden;
}

.financePurchaseCreateOverlay,
.financePurchaseDetailsOverlay {
  position: fixed;
  z-index: 10020;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 22px;
  overflow-y: auto;
  background:
    radial-gradient(
      circle at 50% 45%,
      rgba(168, 85, 247, 0.16),
      transparent 42%
    ),
    rgba(3, 2, 12, 0.82);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  animation: financePurchaseOverlayIn 0.18s ease both;
}

.financePurchaseCreateModal,
.financePurchaseDetailsModal {
  position: relative;
  width: min(940px, 100%);
  max-height: calc(100vh - 44px);
  overflow: hidden;
  border: 1px solid rgba(192, 132, 252, 0.26);
  border-radius: 28px;
  background:
    radial-gradient(
      circle at 10% 0%,
      rgba(168, 85, 247, 0.19),
      transparent 34%
    ),
    linear-gradient(
      145deg,
      rgba(28, 17, 48, 0.985),
      rgba(9, 8, 24, 0.99)
    );
  box-shadow:
    0 38px 100px rgba(0, 0, 0, 0.58),
    0 0 45px rgba(168, 85, 247, 0.12),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
  animation: financePurchaseModalIn 0.22s ease both;
}

.financePurchaseDetailsModal {
  width: min(860px, 100%);
}

.financePurchaseCreateHeader,
.financePurchaseDetailsHeader {
  display: flex;
  align-items: center;
  gap: 15px;
  padding: 22px 24px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.07);
  background: rgba(255, 255, 255, 0.018);
}

.financePurchaseCreateHeaderIcon,
.financePurchaseDetailsHeaderIcon {
  display: grid;
  place-items: center;
  width: 51px;
  height: 51px;
  flex: 0 0 auto;
  border: 1px solid rgba(192, 132, 252, 0.32);
  border-radius: 16px;
  background: rgba(168, 85, 247, 0.12);
  font-size: 23px;
  box-shadow: inset 0 0 22px rgba(168, 85, 247, 0.08);
}

.financePurchaseCreateHeader h2,
.financePurchaseDetailsHeader h2 {
  margin: 3px 0 4px;
  color: var(--text-primary, #fff);
  font-size: clamp(21px, 3vw, 28px);
}

.financePurchaseCreateHeader p,
.financePurchaseDetailsHeader p {
  margin: 0;
  color: var(--text-secondary, #938c9f);
  font-size: 13px;
}

.financePurchaseCreateClose,
.financePurchaseDetailsClose {
  display: grid;
  place-items: center;
  width: 43px;
  height: 43px;
  margin-left: auto;
  flex: 0 0 auto;
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.035);
  color: #aaa4b6;
  font: inherit;
  font-size: 20px;
  cursor: pointer;
  transition:
    color 0.18s ease,
    background 0.18s ease,
    transform 0.18s ease;
}

.financePurchaseCreateClose:hover,
.financePurchaseDetailsClose:hover {
  transform: rotate(3deg);
  background: rgba(251, 113, 133, 0.1);
  color: #fb7185;
}

.financePurchaseCreateBody,
.financePurchaseDetailsBody {
  max-height: calc(100vh - 220px);
  padding: 24px;
  overflow-y: auto;
  overscroll-behavior: contain;
}

.financePurchaseCreateBody::-webkit-scrollbar,
.financePurchaseDetailsBody::-webkit-scrollbar {
  width: 7px;
}

.financePurchaseCreateBody::-webkit-scrollbar-thumb,
.financePurchaseDetailsBody::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: rgba(168, 85, 247, 0.34);
}

