/* =========================================================
   ANIMATION + RESPONSIVE
   ========================================================= */

@keyframes financePurchaseOverlayIn {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

@keyframes financePurchaseModalIn {
  from {
    opacity: 0;
    transform: translateY(18px) scale(0.975);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@media (max-width: 900px) {
  .financePurchaseItemLine {
    grid-template-columns:
      32px
      minmax(0, 1fr)
      minmax(90px, 0.45fr)
      38px;
  }

  .financePurchaseItemLineTotal {
    grid-column: 2 / -1;
  }

  .financePurchaseCard {
    grid-template-columns: auto minmax(0, 1fr) auto;
  }

  .financePurchaseCardAmount {
    grid-column: 2;
    text-align: left;
  }

  .financePurchaseCardArrow {
    grid-column: 3;
    grid-row: 1 / span 2;
  }
}

@media (max-width: 680px) {
  .financePurchasesPanel {
    padding: 17px;
    border-radius: 21px;
  }

  .financePurchasesPanelHead {
    flex-direction: column;
  }

  .financePurchasesPanelActions {
    width: 100%;
  }

  #financePurchaseCreateButton {
    flex: 1;
  }

  .financePurchaseCreateOverlay,
  .financePurchaseDetailsOverlay {
    align-items: flex-end;
    padding: 0;
  }

  .financePurchaseCreateModal,
  .financePurchaseDetailsModal {
    width: 100%;
    max-height: 94vh;
    border-right: 0;
    border-bottom: 0;
    border-left: 0;
    border-radius: 24px 24px 0 0;
  }

  .financePurchaseCreateHeader,
  .financePurchaseDetailsHeader {
    padding: 18px;
  }

  .financePurchaseCreateBody,
  .financePurchaseDetailsBody {
    max-height: calc(94vh - 190px);
    padding: 17px;
  }

  .financePurchaseGeneralGrid,
  .financePurchaseSupplierGrid,
  .financePurchaseCreateTotals,
  .financePurchaseDetailsTotals {
    grid-template-columns: 1fr;
  }

  .financePurchaseItemLine {
    grid-template-columns: 32px minmax(0, 1fr) 38px;
    align-items: center;
  }

  .financePurchaseItemLine > label {
    grid-column: 1 / -1;
  }

  .financePurchaseCreateItemNumber {
    grid-column: 1;
  }

  .financePurchaseItemRemove {
    grid-column: 3;
    grid-row: 1;
  }

  .financePurchaseItemLineTotal {
    grid-column: 1 / -1;
  }

  .financePurchaseCreateFooter {
    padding: 14px 17px;
  }

  .financePurchaseCreateActions {
    width: 100%;
  }

  .financePurchaseCreateCancel,
  .financePurchaseCreateSubmit {
    flex: 1;
    min-width: 0;
  }

  .financePurchaseCard {
    grid-template-columns: 42px minmax(0, 1fr);
    gap: 12px;
    padding: 15px;
  }

  .financePurchaseCardIcon {
    width: 42px;
    height: 42px;
  }

  .financePurchaseCardAmount {
    grid-column: 2;
  }

  .financePurchaseCardArrow {
    display: none;
  }
}
