  --expense-border: rgba(255, 255, 255, 0.09);
  --expense-border-strong: rgba(192, 132, 252, 0.28);
  --expense-text: rgba(255, 255, 255, 0.94);
  --expense-muted: rgba(255, 255, 255, 0.5);
  --expense-subtle: rgba(255, 255, 255, 0.3);
