}

.financeRecurringTemplateCard header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.financeRecurringTemplateCard header > span {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  border-radius: 11px;
  background: rgba(245, 199, 104, 0.08);
  color: #dfc275;
