  border-color: var(--module-border) !important;
  background: var(--module-surface-soft) !important;
}

body .clinicBrandPreview {
  border-color: var(--module-border) !important;
  background:
    radial-gradient(circle at center, var(--module-accent-soft), transparent 68%),
    var(--module-input) !important;
}

body .clinicBrandPreview span {
  color: var(--module-text-faint) !important;
}

body .clinicBrandUpload:hover,
body .clinicThemeChoice:hover {
  border-color: var(--module-border-strong) !important;
  background: var(--module-surface-hover) !important;
}

body .clinicBrandUploadButton {
  border-color: var(--module-border-strong) !important;
  background: var(--module-accent-soft) !important;
  color: var(--module-accent-2) !important;
}

body .clinicThemeChoice {
  color: var(--module-text-soft) !important;
}

body .clinicThemeChoice.active {
  border-color: var(--module-accent) !important;
  background: var(--module-accent-soft) !important;
  box-shadow:
    0 0 0 3px var(--module-accent-soft),
    0 12px 30px var(--module-accent-glow) !important;
  color: var(--module-text) !important;
}

body :is(
  .clinicProfileSaveButton,
  .clinicThemeSaveButton
) {
  border-color: color-mix(in srgb, var(--module-accent) 58%, white) !important;
  background: linear-gradient(
    135deg,
    var(--module-accent),
    color-mix(in srgb, var(--module-accent) 72%, var(--module-surface-2))
  ) !important;
  color: #fff !important;
  box-shadow: 0 12px 30px var(--module-accent-glow) !important;
}

body .clinicProfileActions {
  border-color: var(--module-border) !important;
}

/* The white theme needs dark header text and a soft active dock item. */
body[data-theme="white"] .mac-dock .menu-item.active,
body[data-theme="white"] .dock-menu .menu-item.active {
  border-color: var(--module-border-strong) !important;
  background: var(--module-accent-soft) !important;
  box-shadow: 0 6px 18px var(--module-accent-glow) !important;
}

body[data-theme="white"] .mac-dock .menu-item.active a,
body[data-theme="white"] .dock-menu .menu-item.active a {
  background: transparent !important;
  color: var(--module-accent) !important;
  box-shadow: none !important;
}

body[data-theme="white"] :is(
  .clinicSettingsUser,
  .clinicSettingsPanel
) {
  box-shadow: 0 20px 55px var(--module-shadow) !important;
}

/* Platform owner: atomic clinic provisioning. */
.platformClinicLayout {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(360px, 0.95fr);
  gap: 22px;
  align-items: start;
}

.platformClinicForm,
.platformClinicsColumn {
  min-width: 0;
  padding: 20px;
  border: 1px solid var(--module-border);
  border-radius: 20px;
  background: var(--module-surface-soft);
}

.platformClinicFormTitle {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 18px;
}

.platformClinicFormTitle strong {
  color: var(--module-text);
  font-size: 15px;
  font-weight: 800;
}

.platformClinicFormTitle span {
  color: var(--module-text-muted);
  font-size: 11px;
  text-align: right;
}

.platformClinicFormActions {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 14px;
  margin-top: 20px;
}

.platformClinicFormActions > span {
  margin-right: auto;
  color: var(--module-accent-2);
  font-size: 12px;
  font-weight: 700;
}

.platformClinicFormActions > span.error,
.platformClinicEmpty.error {
  color: #ff8fa3;
}

.platformClinicFormActions button,
.platformCopyCredentialsButton {
  min-height: 44px;
  padding: 0 18px;
  cursor: pointer;
  border: 1px solid color-mix(in srgb, var(--module-accent) 58%, white);
  border-radius: 13px;
  background: linear-gradient(
    135deg,
    var(--module-accent),
    color-mix(in srgb, var(--module-accent) 70%, var(--module-surface-2))
  );
  box-shadow: 0 12px 30px var(--module-accent-glow);
  color: #fff;
  font: inherit;
  font-size: 13px;
  font-weight: 800;
}

.platformClinicFormActions button:disabled {
  cursor: wait;
  opacity: 0.58;
}

.platformClinicsList {
  display: flex;
  max-height: 555px;
  overflow: auto;
  flex-direction: column;
  gap: 9px;
  padding-right: 3px;
}

.platformClinicItem {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
  padding: 12px;
  border: 1px solid var(--module-border);
  border-radius: 15px;
  background: var(--module-input);
}

.platformClinicMark {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border: 1px solid var(--module-border-strong);
  border-radius: 13px;
  background: var(--module-accent-soft);
}

.platformClinicMark[data-clinic-theme="black"] { filter: grayscale(0.65); }
.platformClinicMark[data-clinic-theme="blue"] { filter: hue-rotate(45deg); }
.platformClinicMark[data-clinic-theme="green"] { filter: hue-rotate(100deg); }

.platformClinicMeta,
.platformClinicState {
  min-width: 0;
}

.platformClinicMeta strong,
.platformClinicMeta span,
.platformClinicState strong,
.platformClinicState span {
  display: block;
}

.platformClinicMeta strong {
  overflow: hidden;
  color: var(--module-text);
  font-size: 13px;
  font-weight: 800;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.platformClinicMeta span,
.platformClinicState strong {
  margin-top: 4px;
  color: var(--module-text-muted);
  font-size: 10px;
}

.platformClinicState {
  text-align: right;
}

.platformClinicState strong {
  margin: 0 0 4px;
}

.platformClinicState span {
  color: #75d7a2;
  font-size: 10px;
  font-weight: 800;
}

.platformClinicState span.inactive {
  color: #ff8fa3;
}

.platformSubscriptionRow {
  grid-column: 1 / -1;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding-top: 11px;
  border-top: 1px solid var(--module-border);
}

.platformSubscriptionRow > div:first-child {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 8px;
}

.platformSubscriptionRow strong,
.platformSubscriptionRow small {
  color: var(--module-text-muted);
  font-size: 10px;
  font-weight: 700;
}

.platformSubscriptionBadge {
  padding: 5px 8px;
  border: 1px solid var(--module-border-strong);
  border-radius: 999px;
  background: var(--module-accent-soft);
  color: var(--module-accent-2);
  font-size: 9px;
  font-weight: 900;
  white-space: nowrap;
}

.platformSubscriptionBadge.active { color: #75d7a2; }
.platformSubscriptionBadge.expiring { color: #ffc66f; }
.platformSubscriptionBadge.expired,
.platformSubscriptionBadge.paused { color: #ff8fa3; }

.platformSubscriptionActions {
  display: flex;
  flex: 0 0 auto;
  gap: 6px;
}

.platformSubscriptionActions button,
.platformSubscriptionEditorActions button {
  min-height: 30px;
  padding: 0 10px;
  cursor: pointer;
  border: 1px solid var(--module-border-strong);
  border-radius: 9px;
  background: var(--module-accent-soft);
  color: var(--module-accent-2);
  font: inherit;
  font-size: 10px;
  font-weight: 800;
}

.platformSubscriptionActions button:first-child {
  border-color: color-mix(in srgb, #55d99b 44%, var(--module-border));
  color: #75d7a2;
}

.platformSubscriptionActions button:disabled,
.platformSubscriptionEditorActions button:disabled {
  cursor: wait;
  opacity: 0.55;
}

.platformSubscriptionEditor {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  padding: 13px;
  border: 1px solid var(--module-border);
  border-radius: 13px;
  background: var(--module-surface-soft);
}

.platformSubscriptionEditor[hidden] {
  display: none;
}

.platformSubscriptionEditor label {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 5px;
}

.platformSubscriptionEditor label.wide,
.platformSubscriptionEditor > p,
.platformSubscriptionEditorActions,
.platformSubscriptionHistory {
  grid-column: 1 / -1;
}

.platformSubscriptionEditor label > span {
  color: var(--module-text-muted);
  font-size: 9px;
  font-weight: 800;
}

.platformSubscriptionEditor input {
  width: 100%;
  min-height: 36px;
  padding: 0 10px;
  box-sizing: border-box;
  border: 1px solid var(--module-border);
  outline: none;
  border-radius: 9px;
  background: var(--module-input);
  color: var(--module-text);
  color-scheme: var(--module-color-scheme);
  font: inherit;
  font-size: 11px;
}

.platformSubscriptionEditor input:focus {
  border-color: var(--module-accent);
  box-shadow: 0 0 0 3px var(--module-accent-soft);
}

.platformSubscriptionEditor > p {
  margin: 0;
  color: var(--module-text-faint);
  font-size: 9px;
  line-height: 1.4;
}

.platformSubscriptionEditorActions {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.platformSubscriptionEditorActions button:first-child {
  background: var(--module-accent);
  color: #fff;
}

.platformSubscriptionHistory {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding-top: 9px;
  border-top: 1px solid var(--module-border);
  color: var(--module-text-muted);
  font-size: 10px;
}

.platformSubscriptionHistory[hidden] {
  display: none;
}

.platformSubscriptionHistory > div {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  gap: 8px;
  padding: 8px;
  border-radius: 9px;
  background: var(--module-input);
}

.platformSubscriptionHistory strong {
  color: var(--module-text);
}

.platformSubscriptionHistory span,
.platformSubscriptionHistory small {
  color: var(--module-text-muted);
}

.platformClinicEmpty {
  padding: 34px 16px;
  border: 1px dashed var(--module-border);
  border-radius: 15px;
  color: var(--module-text-muted);
  font-size: 12px;
  text-align: center;
}

.platformClinicCredentials {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(300px, 0.8fr) auto;
  gap: 20px;
  align-items: center;
  margin-top: 22px;
  padding: 20px;
  border: 1px solid color-mix(in srgb, #55d99b 44%, var(--module-border));
  border-radius: 20px;
  background: color-mix(in srgb, #38c985 9%, var(--module-surface-1));
}

.platformClinicCredentials[hidden] {
  display: none;
}

.platformClinicCredentials > div > span,
.platformClinicCredentials > div > strong,
.platformClinicCredentials > div > p {
  display: block;
}

.platformClinicCredentials > div > span {
  margin-bottom: 5px;
  color: #75d7a2;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.platformClinicCredentials > div > strong {
  color: var(--module-text);
  font-size: 17px;
}

.platformClinicCredentials > div > p {
  margin: 6px 0 0;
  color: var(--module-text-muted);
  font-size: 11px;
  line-height: 1.45;
}

.platformClinicCredentials dl {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin: 0;
}

.platformClinicCredentials dl > div {
  min-width: 0;
  padding: 10px 12px;
  border: 1px solid var(--module-border);
  border-radius: 12px;
  background: var(--module-input);
}

.platformClinicCredentials dt {
  margin-bottom: 4px;
  color: var(--module-text-muted);
  font-size: 9px;
  text-transform: uppercase;
}

.platformClinicCredentials dd {
  overflow: hidden;
  margin: 0;
  color: var(--module-text);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12px;
  font-weight: 800;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ownerSubscriptionStatus {
  display: grid;
  grid-template-columns: 48px minmax(0, 1fr) auto;
  gap: 15px;
  align-items: center;
  margin-bottom: 22px;
  padding: 18px 20px;
  border: 1px solid var(--module-border-strong);
  border-radius: 20px;
  background:
    linear-gradient(135deg, var(--module-accent-soft), transparent 62%),
    var(--module-surface-1);
  box-shadow: 0 16px 40px var(--module-shadow);
  color: var(--module-text);
}

.ownerSubscriptionStatus.expired,
.ownerSubscriptionStatus.paused {
  border-color: color-mix(in srgb, #ff6f87 42%, var(--module-border));
}

.ownerSubscriptionStatus.expiring {
  border-color: color-mix(in srgb, #ffc66f 42%, var(--module-border));
}

.ownerSubscriptionIcon {
  display: grid;
  width: 48px;
  height: 48px;
  place-items: center;
  border: 1px solid var(--module-border-strong);
  border-radius: 15px;
  background: var(--module-accent-soft);
  font-size: 21px;
}

.ownerSubscriptionStatus > div:nth-child(2) > span,
.ownerSubscriptionStatus > div:nth-child(2) > strong,
.ownerSubscriptionStatus > div:nth-child(2) > p {
  display: block;
}

.ownerSubscriptionStatus > div:nth-child(2) > span {
  margin-bottom: 4px;
  color: var(--module-accent-2);
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.09em;
}

.ownerSubscriptionStatus > div:nth-child(2) > strong {
  font-size: 15px;
}

.ownerSubscriptionStatus > div:nth-child(2) > p {
  margin: 4px 0 0;
  color: var(--module-text-muted);
  font-size: 11px;
}

.ownerSubscriptionDays {
  min-width: 90px;
  text-align: right;
}

.ownerSubscriptionDays strong,
.ownerSubscriptionDays span {
  display: block;
}

.ownerSubscriptionDays strong {
  font-size: 24px;
}

.ownerSubscriptionDays span {
  color: var(--module-text-muted);
  font-size: 9px;
}

@media (max-width: 980px) {
  .platformClinicLayout,
  .platformClinicCredentials {
    grid-template-columns: 1fr;
  }

  .platformCopyCredentialsButton {
    width: 100%;
  }
}

@media (max-width: 620px) {
  .platformClinicForm,
  .platformClinicsColumn {
    padding: 15px;
  }

  .platformClinicItem {
    grid-template-columns: 38px minmax(0, 1fr);
  }

  .platformClinicState {
    grid-column: 2;
    text-align: left;
  }

  .platformClinicCredentials dl {
    grid-template-columns: 1fr;
  }

  .platformSubscriptionRow,
  .platformSubscriptionRow > div:first-child {
    align-items: flex-start;
    flex-direction: column;
  }

  .platformSubscriptionActions {
    width: 100%;
  }

  .platformSubscriptionActions button {
    flex: 1;
  }

  .platformSubscriptionEditor {
    grid-template-columns: 1fr;
  }

  .platformSubscriptionEditor label,
  .platformSubscriptionEditor label.wide {
    grid-column: 1;
  }

  .ownerSubscriptionStatus {
    grid-template-columns: 42px minmax(0, 1fr);
  }

  .ownerSubscriptionDays {
    grid-column: 2;
    text-align: left;
  }
}

/* Team specialization editor. */
.specializationEditorOverlay {
  position: fixed;
  inset: 0;
  z-index: 1000000;
  display: grid;
  place-items: center;
  padding: 22px;
}

.specializationEditorBackdrop {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  padding: 0;
  border: 0;
  background:
    radial-gradient(circle at 50% 22%, var(--module-accent-soft), transparent 42%),
    var(--module-overlay);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  cursor: default;
}

.specializationEditorModal {
  position: relative;
  z-index: 1;
  width: min(520px, 94vw);
  padding: 28px;
  border: 1px solid var(--module-border-strong);
  border-radius: 25px;
  background:
    radial-gradient(circle at 100% 0, var(--module-accent-soft), transparent 38%),
    linear-gradient(145deg, var(--module-surface-1), var(--module-surface-2));
  box-shadow:
    0 38px 105px var(--module-shadow),
    0 0 38px var(--module-accent-glow);
  color: var(--module-text);
  animation: specializationEditorOpen 0.18s ease-out;
}

@keyframes specializationEditorOpen {
  from {
    opacity: 0;
    transform: translateY(10px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.specializationEditorClose {
  position: absolute;
  top: 15px;
  right: 15px;
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  padding: 0;
  border: 1px solid var(--module-border);
  border-radius: 11px;
  background: var(--module-surface-soft);
  color: var(--module-text-soft);
  font-size: 1.5rem;
  line-height: 1;
  cursor: pointer;
}

.specializationEditorHeader {
  display: flex;
  gap: 14px;
  padding-right: 34px;
}

.specializationEditorIcon {
  display: grid;
  width: 52px;
  height: 52px;
  flex: 0 0 52px;
  place-items: center;
  border: 1px solid var(--module-border-strong);
  border-radius: 16px;
  background: var(--module-accent-soft);
  box-shadow: 0 0 24px var(--module-accent-glow);
  color: var(--module-accent-2);
  font-size: 1.2rem;
}

.specializationEditorEyebrow {
  color: var(--module-accent-2);
  font-size: 0.68rem;
  font-weight: 900;
  letter-spacing: 0.12em;
}

.specializationEditorHeader h2 {
  margin: 4px 0 0;
  color: var(--module-text);
  font-size: 1.55rem;
}

.specializationEditorHeader p {
  margin: 7px 0 0;
  color: var(--module-text-muted);
  font-size: 0.82rem;
  line-height: 1.5;
}

.specializationEditorForm {
  margin-top: 23px;
}

.specializationEditorField {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.specializationEditorField > span,
.specializationEditorColorField strong {
  color: var(--module-text-soft);
  font-size: 0.78rem;
  font-weight: 800;
}

.specializationEditorField input {
  width: 100%;
  min-height: 48px;
  padding: 0 14px;
  box-sizing: border-box;
  border: 1px solid var(--module-border);
  border-radius: 13px;
  outline: none;
  background: var(--module-input);
  color: var(--module-text);
  font: inherit;
  color-scheme: var(--module-color-scheme);
}

.specializationEditorField input::placeholder {
  color: var(--module-text-faint);
}

.specializationEditorField input:focus {
  border-color: var(--module-accent);
  box-shadow:
    0 0 0 3px var(--module-accent-soft),
    0 0 20px var(--module-accent-glow);
}

.specializationEditorColorField {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin-top: 14px;
  padding: 13px 14px;
  border: 1px solid var(--module-border);
  border-radius: 14px;
  background: var(--module-surface-soft);
}

.specializationEditorColorField > span,
.specializationEditorColorField small {
  display: block;
}

.specializationEditorColorField small {
  margin-top: 4px;
  color: var(--module-text-muted);
  font-size: 0.68rem;
}

.specializationEditorColorField input {
  width: 48px;
  height: 40px;
  flex: 0 0 48px;
  padding: 4px;
  border: 1px solid var(--module-border);
  border-radius: 11px;
  background: var(--module-input);
  cursor: pointer;
}

.specializationEditorColorField input::-webkit-color-swatch-wrapper {
  padding: 0;
}

.specializationEditorColorField input::-webkit-color-swatch {
  border: 0;
  border-radius: 7px;
}

.specializationEditorError {
  min-height: 18px;
  margin-top: 9px;
  color: #ff8295;
  font-size: 0.72rem;
  font-weight: 700;
}

.specializationEditorActions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-top: 4px;
}

.specializationEditorCancel,
.specializationEditorSubmit {
  min-height: 46px;
  padding: 0 16px;
  border-radius: 13px;
  font: inherit;
  font-size: 0.82rem;
  font-weight: 850;
  cursor: pointer;
}

.specializationEditorCancel {
  border: 1px solid var(--module-border);
  background: var(--module-surface-soft);
  color: var(--module-text-soft);
}

.specializationEditorSubmit {
  border: 1px solid color-mix(in srgb, var(--module-accent) 58%, white);
  background: linear-gradient(
    135deg,
    var(--module-accent),
    color-mix(in srgb, var(--module-accent) 72%, var(--module-surface-2))
  );
  box-shadow: 0 12px 30px var(--module-accent-glow);
  color: #fff;
}

@media (max-width: 560px) {
  .specializationEditorModal {
    padding: 23px 17px;
  }

  .specializationEditorHeader {
    padding-right: 30px;
  }

  .specializationEditorActions {
    grid-template-columns: 1fr;
  }
}
/* =========================================================
   PUGCRM — CALENDAR FULL WIDTH DESKTOP
   Большой рабочий календарь + компактная панель справа
========================================================= */

/* Только на странице календаря расширяем общий рабочий холст */
.main-content:has(
  .page[data-page="calendar"].active
) {
  width: calc(100vw - 32px) !important;
  max-width: none !important;

  margin-left: 16px !important;
  margin-right: 16px !important;

  padding-left: 0 !important;
  padding-right: 0 !important;
}

/* Сама страница календаря занимает всю доступную ширину */
.page[data-page="calendar"] {
  width: 100% !important;
  max-width: none !important;
  min-width: 0 !important;
}

/* Контейнер, в который JS вставляет календарь */
.page[data-page="calendar"]
#calendar-grid-target {
  width: 100% !important;
  max-width: none !important;
  min-width: 0 !important;
}

/* Главная карточка календаря */
.page[data-page="calendar"]
.calendarCard {
  width: 100% !important;
  max-width: none !important;

