  padding: 0;
  list-style: none;
}

.ownerReportAttention li {
  position: relative;
  border-radius: 11px;
  padding: 10px 10px 10px 28px;
  color: rgba(255, 255, 255, .72);
  background: rgba(255, 255, 255, .035);
  font-size: 11px;
}

.ownerReportAttention li::before {
  content: "•";
  position: absolute;
  left: 12px;
  color: #ffbd68;
}

.ownerReportTelegram {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(240px, 1fr) minmax(280px, .8fr);
  align-items: center;
  gap: 20px;
  margin-top: 14px;
  padding: 22px;
  overflow: hidden;
  background:
    radial-gradient(circle at 100% 0%, rgba(88, 215, 255, .13), transparent 37%),
    rgba(12, 12, 19, .9);
}

.ownerReportTelegramIcon {
  display: grid;
  place-items: center;
  width: 54px;
  height: 54px;
  border-radius: 17px;
  color: #fff;
  background: linear-gradient(145deg, #37b8ee, #1976c9);
  font-size: 24px;
  transform: rotate(-8deg);
}

.ownerReportTelegramCopy p {
  max-width: 610px;
  margin: 8px 0 0;
  color: rgba(255, 255, 255, .52);
  font-size: 11px;
  line-height: 1.55;
}

.ownerReportTelegramControls {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
}

.ownerReportTelegramControls .is-primary {
  grid-column: 1 / -1;
  color: #fff;
  border-color: rgba(155, 92, 255, .55);
  background: linear-gradient(135deg, #8b48ee, #6431c7);
}

.ownerReportAutoToggle {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 46px;
  border: 1px solid rgba(255, 255, 255, .09);
  border-radius: 12px;
  padding: 8px 11px;
  color: #fff;
  background: rgba(255, 255, 255, .035);
  cursor: pointer;
}

.ownerReportAutoToggle input {
  width: 18px;
  height: 18px;
  min-height: 0;
  margin: 0;
  padding: 0;
  accent-color: #8b48ee;
}

.ownerReportAutoToggle span {
  display: grid;
  gap: 2px;
}

.ownerReportAutoToggle b {
  font-size: 11px;
}

.ownerReportAutoToggle small {
  color: rgba(255, 255, 255, .45);
  font-size: 9px;
}

.ownerReportTelegramControls button:disabled {
  opacity: .45;
  cursor: not-allowed;
}

.ownerReportTelegramStatus {
  position: absolute;
  right: 22px;
  bottom: 8px;
  color: rgba(255, 255, 255, .38);
  font-size: 9px;
}

@media (max-width: 1050px) {
  .ownerReportMetricGrid,
  .ownerReportSecondaryGrid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .ownerReportMainGrid,
  .ownerReportTelegram {
    grid-template-columns: 1fr;
  }

  .ownerReportTelegramIcon {
    display: none;
  }

  .ownerReportTelegramStatus {
    position: static;
  }
}

@media (max-width: 640px) {
  .ownerReportMetricGrid,
  .ownerReportSecondaryGrid {
    grid-template-columns: 1fr;
  }

  .ownerReportHeroActions,
  .ownerReportHeroActions label,
  .ownerReportHeroActions input,
  .ownerReportHeroActions button {
    width: 100%;
  }

  .ownerReportTelegramControls {
    grid-template-columns: 1fr;
  }

  .ownerReportTelegramControls .is-primary {
    grid-column: auto;
  }
}

