/* =====================================================
   STAFF MODAL — WIDE PREMIUM WINDOW
===================================================== */

#staffDrawer {
  padding: 24px;
  align-items: center;
  justify-content: center;
}

#staffDrawer .modal-window {
  width: min(
    760px,
    calc(100vw - 48px)
  ) !important;

  max-width: 760px !important;
  max-height: min(
    860px,
    calc(100vh - 48px)
  ) !important;

  padding: 28px !important;
  box-sizing: border-box;

  overflow-x: hidden;
  overflow-y: auto;

  border-radius: 24px !important;
  border: 1px solid
    var(
      --module-border-strong,
      rgba(168, 85, 247, 0.45)
    ) !important;

  background:
    radial-gradient(
      circle at 100% 0,
      rgba(168, 85, 247, 0.18),
      transparent 42%
    ),
    linear-gradient(
      145deg,
      rgba(31, 17, 51, 0.98),
      rgba(15, 8, 28, 0.98)
    ) !important;

  box-shadow:
    0 40px 120px
      rgba(0, 0, 0, 0.65),
    0 0 55px
      rgba(168, 85, 247, 0.22) !important;
