/* Заголовок */

#staffDrawer .modal-window > h3 {
  margin: 0 0 24px;
  font-size: 22px;
  line-height: 1.2;
  font-weight: 800;
  letter-spacing: -0.02em;
}

/* Все подписи */

#staffDrawer .modal-window label {
  min-width: 0;
}

#staffDrawer .modal-window label > span,
#staffDrawer .modal-window label > div:first-child {
  font-size: 12px;
  line-height: 1.35;
  font-weight: 650;
}

/* Поля */

#staffDrawer .modal-window input:not(
  [type="color"]
):not(
  [type="checkbox"]
),
#staffDrawer .modal-window select,
#staffDrawer .modal-window textarea {
  width: 100%;
  min-width: 0;
  box-sizing: border-box;
  border-radius: 12px;
}

#staffDrawer .modal-window input:not(
  [type="color"]
):not(
  [type="checkbox"]
),
#staffDrawer .modal-window select {
  min-height: 46px;
  padding: 0 13px;
}

#staffDrawer .modal-window textarea {
  min-height: 92px;
  padding: 12px 13px;
  resize: vertical;
}

/* Экстренный контакт */

#staffDrawer
  .staffEmergencyContactBlock {
  margin-top: 22px;
  padding: 20px;
  border-radius: 18px;

  border: 1px solid
    rgba(168, 85, 247, 0.38);

  background:
    radial-gradient(
      circle at 100% 0,
      rgba(168, 85, 247, 0.16),
      transparent 45%
    ),
    rgba(8, 4, 18, 0.44);

  box-shadow:
    inset 0 1px 0
      rgba(255, 255, 255, 0.04);
}

#staffDrawer
  .staffEmergencyContactHead {
  margin-bottom: 16px;
}

#staffDrawer
  .staffEmergencyContactHead strong {
  font-size: 15px;
}

#staffDrawer
  .staffEmergencyContactHead span {
  margin-top: 4px;
  font-size: 12px;
}

/* На широкой модалке три поля в линию */

#staffDrawer
  .staffEmergencyContactBlock {
  display: grid;
  grid-template-columns:
    repeat(3, minmax(0, 1fr));
  gap: 14px;
}

#staffDrawer
  .staffEmergencyContactHead {
