===================================================== */

.appointmentTemplatePicker {
  margin-top: 10px;
  margin-bottom: 16px;
}

.appointmentTemplatePickerHead {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px;
}

.appointmentTemplatePickerHead > div {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.appointmentTemplatePickerHead strong {
  font-size: 12px;
  font-weight: 700;
  color: rgba(255,255,255,.92);
}

