  font-size: 11px;
  font-weight: 700;

  text-transform: uppercase;

  letter-spacing: .05em;
}

.monthScheduleEditorRows {
  flex: 1;

  min-height: 0;

  overflow-y: auto;

  padding:
    0 18px 18px;
}

.monthScheduleEditorRow {
  min-height: 70px;

  margin-bottom: 8px;

  padding:
    10px 12px;

  border:
    1px solid
    rgba(255,255,255,.07);

  border-radius: 14px;

  background:
    rgba(255,255,255,.025);

  transition:
    opacity .18s ease,
    background .18s ease,
    border-color .18s ease;
}

.monthScheduleEditorRow.is-active {
  border-color:
    rgba(124,92,255,.22);

  background:
    rgba(124,92,255,.045);
}

.monthScheduleEditorRow.is-off {
  opacity: .58;
}


/* PERSON */

.monthScheduleEditorPerson {
  display: flex;
  align-items: center;

  min-width: 0;

  gap: 11px;
}

.monthScheduleEditorColor {
  width: 4px;
  height: 38px;

  flex: 0 0 4px;

  border-radius: 999px;
}

.monthScheduleEditorAvatar {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 38px;
  height: 38px;

  flex: 0 0 38px;

  border-radius: 11px;

  background:
    rgba(255,255,255,.055);
}

.monthScheduleEditorIdentity {
  display: flex;
  flex-direction: column;

  min-width: 0;
}

.monthScheduleEditorIdentity strong {
  overflow: hidden;

  color: #fff;

  font-size: 14px;

  white-space: nowrap;
  text-overflow: ellipsis;
}

.monthScheduleEditorIdentity span {
  margin-top: 3px;

  color:
    rgba(255,255,255,.4);

  font-size: 11px;
}


/* STATUS */

.monthScheduleEditorStatus {
  display: inline-flex;
  align-items: center;
  justify-content: center;

  gap: 8px;

  min-height: 38px;

  padding:
    0 12px;

  border:
    1px solid
    rgba(255,255,255,.1);

  border-radius: 999px;

  background:
    rgba(255,255,255,.035);

  color:
    rgba(255,255,255,.55);

  cursor: pointer;
}

.monthScheduleEditorStatus > span {
  width: 8px;
  height: 8px;

  border-radius: 50%;

  background:
    rgba(255,255,255,.3);
}

.monthScheduleEditorStatus.active {
  border-color:
    rgba(64,211,140,.4);

  background:
    rgba(64,211,140,.1);

  color:
    #a1f0ca;
}

.monthScheduleEditorStatus.active > span {
  background:
    #49d795;
}


/* TIME */

.monthScheduleEditorTime {
  display: flex;
  flex-direction: column;

  gap: 5px;
}

.monthScheduleEditorTime > span {
  display: none;
}

.monthScheduleEditorTime input {
  width: 100%;
  height: 40px;

  box-sizing: border-box;

  padding:
    0 11px;

  border:
    1px solid
    rgba(255,255,255,.1);

  border-radius: 11px;

  background:
    rgba(0,0,0,.22);

  color: #fff;

  font-size: 13px;

  outline: none;
}

.monthScheduleEditorTime input:focus {
  border-color:
    rgba(124,92,255,.55);

  box-shadow:
    0 0 0 3px
    rgba(124,92,255,.1);
}


/* FOOTER */

.monthScheduleEditorFooter {
  display: flex;
  align-items: center;
  justify-content: flex-end;

  gap: 10px;

  padding:
    16px 26px;

  border-top:
    1px solid
    rgba(255,255,255,.08);

  background:
    rgba(7,16,25,.97);
}

.monthScheduleEditorFooter button {
  min-width: 150px;
  min-height: 44px;

  border-radius: 12px;
}
