/* =========================================
   REPEATING STAFF SCHEDULE
   ========================================= */

.monthScheduleRepeatContent {
  padding: 22px 24px 24px;
}

.monthScheduleRepeatContent[hidden] {
  display: none !important;
}

.monthScheduleRepeatIntro {
  display: flex;
  align-items: center;
  justify-content: space-between;

  margin-bottom: 22px;
  padding: 16px 18px;

  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 14px;

  background: rgba(255, 255, 255, 0.025);
}

.monthScheduleRepeatIntro > div {
  display: flex;
  align-items: center;
  gap: 13px;
}

.monthScheduleRepeatIntro > div > span {
  display: grid;
  place-items: center;

  width: 38px;
  height: 38px;

  border-radius: 11px;

  background: rgba(124, 92, 255, 0.14);

  color: #a995ff;
  font-size: 20px;
}

.monthScheduleRepeatIntro strong {
  display: block;

  margin-bottom: 3px;

  font-size: 15px;
  font-weight: 750;
}

.monthScheduleRepeatIntro small {
  display: block;

  color: rgba(255, 255, 255, 0.48);
  font-size: 12px;
}

.monthScheduleRepeatGrid {
  display: grid;
  grid-template-columns:
    minmax(180px, 1.4fr)
    minmax(130px, 1fr)
    minmax(130px, 1fr);

  gap: 18px;
}

.monthScheduleRepeatField {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.monthScheduleRepeatField > span {
  color: rgba(255, 255, 255, 0.52);

  font-size: 10px;
  font-weight: 750;

  text-transform: uppercase;
  letter-spacing: 0.07em;
}

.monthScheduleRepeatField input,
.monthScheduleRepeatField select {
  width: 100%;
  height: 42px;

  box-sizing: border-box;

  padding: 0 12px;

  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 10px;

  background: rgba(255, 255, 255, 0.035);

  color: inherit;

  font: inherit;

  outline: none;
}

.monthScheduleRepeatField input:focus,
.monthScheduleRepeatField select:focus {
  border-color: rgba(124, 92, 255, 0.75);

  box-shadow:
    0 0 0 3px
    rgba(124, 92, 255, 0.1);
}

.monthScheduleRepeatDaysField {
  grid-column: 1 / -1;
}

.monthScheduleRepeatDays {
  display: grid;

  grid-template-columns:
    repeat(7, 1fr);

  gap: 8px;
}

.monthScheduleRepeatDays button {
  height: 42px;

  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 10px;

  background: rgba(255, 255, 255, 0.025);

  color: rgba(255, 255, 255, 0.65);

  font-weight: 700;

  cursor: pointer;

  transition:
    0.15s ease;
}

.monthScheduleRepeatDays button:hover {
  border-color:
    rgba(124, 92, 255, 0.55);

  background:
    rgba(124, 92, 255, 0.08);
}

.monthScheduleRepeatDays button.active {
  border-color:
    rgba(124, 92, 255, 0.9);

  background:
    rgba(124, 92, 255, 0.18);

  color: #ffffff;

  box-shadow:
    inset 0 0 0 1px
    rgba(124, 92, 255, 0.12);
}

.monthScheduleRepeatHint {
  margin-top: 18px;
  padding-top: 14px;

  border-top:
    1px solid
    rgba(255, 255, 255, 0.06);

  color:
    rgba(255, 255, 255, 0.38);

  font-size: 11px;
}
/* =========================================================
   MEDICAL CORE — ACTIVE DIAGNOSES
   ========================================================= */

.patientDiagnosesPanel {
  position: relative;
  overflow: hidden;
  margin-bottom: 20px;
  padding: 20px;
  border: 1px solid rgba(167, 139, 250, 0.22);
  border-radius: 18px;
  background:
    radial-gradient(circle at 100% 0%, rgba(139, 92, 246, 0.16), transparent 42%),
    linear-gradient(145deg, rgba(24, 20, 42, 0.92), rgba(12, 17, 29, 0.94));
  box-shadow: 0 18px 45px rgba(4, 7, 20, 0.24);
}

.patientDiagnosesHeader {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 16px;
}

.patientDiagnosesKicker,
.patientDiagnosisModalHeader span {
  display: block;
  margin-bottom: 4px;
  color: #a78bfa;
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.16em;
}

.patientDiagnosesHeader h3,
.patientDiagnosisModalHeader h3 {
  margin: 0;
  color: #f8fafc;
  font-size: 1.16rem;
  line-height: 1.25;
}

.patientDiagnosesHeader p,
.patientDiagnosisModalHeader p {
  max-width: 600px;
  margin: 6px 0 0;
  color: rgba(226, 232, 240, 0.62);
  font-size: 0.84rem;
  line-height: 1.45;
}

.patientDiagnosesHeaderActions,
.patientDiagnosisActions,
.patientDiagnosisFormActions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

.patientDiagnosesHeaderActions button,
.patientDiagnosisActions button,
.patientDiagnosisFormActions button {
  min-height: 36px;
  padding: 8px 12px;
  border: 1px solid rgba(148, 163, 184, 0.2);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.055);
  color: #e2e8f0;
  font: inherit;
  font-size: 0.78rem;
  font-weight: 700;
  cursor: pointer;
  transition: 160ms ease;
}

.patientDiagnosesHeaderActions button:hover,
.patientDiagnosisActions button:hover,
.patientDiagnosisFormActions button:hover {
  border-color: rgba(167, 139, 250, 0.5);
  background: rgba(139, 92, 246, 0.16);
  transform: translateY(-1px);
}

.patientDiagnosesHeaderActions .is-primary,
.patientDiagnosisFormActions .is-primary {
  border-color: rgba(139, 92, 246, 0.7);
  background: linear-gradient(135deg, #7c3aed, #9333ea);
  color: #fff;
  box-shadow: 0 8px 24px rgba(124, 58, 237, 0.24);
}

.patientDiagnosisActions .is-danger {
  color: #fecaca;
}

.patientDiagnosesList,
.patientDiagnosisHistoryList {
  display: grid;
  gap: 10px;
}

.patientDiagnosisCard {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 14px 14px 14px 16px;
  border: 1px solid rgba(148, 163, 184, 0.14);
  border-left: 3px solid rgba(148, 163, 184, 0.45);
  border-radius: 13px;
  background: rgba(2, 6, 23, 0.34);
}

.patientDiagnosisCard.severity-mild {
  border-left-color: #22c55e;
}

.patientDiagnosisCard.severity-moderate {
  border-left-color: #eab308;
}

.patientDiagnosisCard.severity-severe {
  border-left-color: #f97316;
}

.patientDiagnosisCard.severity-critical {
  border-left-color: #ef4444;
  background: linear-gradient(90deg, rgba(127, 29, 29, 0.15), rgba(2, 6, 23, 0.34));
}

.patientDiagnosisCard.status-entered_in_error {
  opacity: 0.64;
}

.patientDiagnosisCardMain {
  min-width: 0;
}

.patientDiagnosisCardTitleRow {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

.patientDiagnosisCard h4 {
  margin: 0;
  color: #f8fafc;
  font-size: 0.98rem;
  line-height: 1.3;
}

.patientDiagnosisCode {
  padding: 2px 7px;
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 999px;
  color: rgba(226, 232, 240, 0.62);
  font-size: 0.66rem;
  font-weight: 700;
}

.patientDiagnosisMeta {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px 12px;
  margin-top: 7px;
  color: rgba(226, 232, 240, 0.58);
  font-size: 0.73rem;
}

.patientDiagnosisStatus,
.patientDiagnosisSeverity {
  display: inline-flex;
  align-items: center;
  padding: 3px 7px;
  border-radius: 999px;
  font-weight: 800;
}

.patientDiagnosisStatus.status-active {
  background: rgba(34, 197, 94, 0.13);
  color: #86efac;
}

.patientDiagnosisStatus.status-remission {
  background: rgba(59, 130, 246, 0.14);
  color: #93c5fd;
}

.patientDiagnosisStatus.status-resolved {
  background: rgba(148, 163, 184, 0.14);
  color: #cbd5e1;
}

.patientDiagnosisStatus.status-entered_in_error {
  background: rgba(239, 68, 68, 0.12);
  color: #fca5a5;
}

.patientDiagnosisSeverity.severity-critical,
.patientDiagnosisSeverity.severity-severe {
  background: rgba(239, 68, 68, 0.1);
  color: #fca5a5;
}

.patientDiagnosisSeverity.severity-moderate {
  background: rgba(234, 179, 8, 0.11);
  color: #fde047;
}

.patientDiagnosisSeverity.severity-mild {
  background: rgba(34, 197, 94, 0.1);
  color: #86efac;
}

.patientDiagnosisNote {
  display: -webkit-box;
  overflow: hidden;
  margin: 9px 0 0;
  color: rgba(226, 232, 240, 0.75);
  font-size: 0.8rem;
  line-height: 1.45;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
}

.patientDiagnosisActions {
  justify-content: flex-end;
  flex: 0 0 auto;
  max-width: 410px;
}

.patientDiagnosisActions button {
  min-height: 32px;
  padding: 6px 9px;
  font-size: 0.7rem;
}

.patientDiagnosesEmpty {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px;
  border: 1px dashed rgba(148, 163, 184, 0.2);
  border-radius: 13px;
  background: rgba(15, 23, 42, 0.32);
  color: rgba(226, 232, 240, 0.68);
}

.patientDiagnosesEmpty > span {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  border-radius: 50%;
  background: rgba(34, 197, 94, 0.12);
  color: #86efac;
  font-weight: 900;
}

.patientDiagnosesEmpty strong {
  display: block;
  color: #e2e8f0;
  font-size: 0.85rem;
}

.patientDiagnosesEmpty p {
  margin: 3px 0 0;
  font-size: 0.73rem;
  line-height: 1.4;
}

.patientDiagnosesEmpty.is-error > span {
  background: rgba(239, 68, 68, 0.12);
  color: #fca5a5;
}

.patientDiagnosesEmpty > button {
  margin-left: auto;
  padding: 7px 10px;
  border: 1px solid rgba(148, 163, 184, 0.2);
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.05);
  color: inherit;
  font: inherit;
  font-size: 0.72rem;
  font-weight: 700;
  cursor: pointer;
}

.patientDiagnosisModalOverlay {
  position: fixed;
  z-index: 12000;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 18px;
  background: rgba(2, 6, 23, 0.76);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.patientDiagnosisModal {
  overflow: auto;
  width: min(720px, 100%);
  max-height: min(860px, calc(100vh - 36px));
  border: 1px solid rgba(167, 139, 250, 0.24);
  border-radius: 20px;
  background:
    radial-gradient(circle at 100% 0%, rgba(139, 92, 246, 0.13), transparent 36%),
    #101522;
  box-shadow: 0 28px 90px rgba(0, 0, 0, 0.48);
}

.patientDiagnosisModalHeader {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 20px 22px 16px;
  border-bottom: 1px solid rgba(148, 163, 184, 0.13);
}

.patientDiagnosisModalHeader > button {
  display: grid;
  width: 36px;
  height: 36px;
  flex: 0 0 auto;
  padding: 0;
  place-items: center;
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.04);
  color: #cbd5e1;
  font-size: 1.35rem;
  cursor: pointer;
}

.patientDiagnosisForm {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
  padding: 20px 22px 22px;
}

.patientDiagnosisForm label {
  display: grid;
  gap: 7px;
}

.patientDiagnosisForm label.is-wide,
.patientDiagnosisFormError,
.patientDiagnosisFormActions {
  grid-column: 1 / -1;
}

.patientDiagnosisForm label > span {
  color: rgba(226, 232, 240, 0.7);
  font-size: 0.73rem;
  font-weight: 700;
}

.patientDiagnosisForm input,
.patientDiagnosisForm select,
.patientDiagnosisForm textarea {
  width: 100%;
  min-height: 42px;
  padding: 10px 12px;
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 11px;
  outline: none;
  background: rgba(2, 6, 23, 0.42);
  color: #f8fafc;
  font: inherit;
  font-size: 0.84rem;
}

.patientDiagnosisForm textarea {
  min-height: 98px;
  resize: vertical;
}

.patientDiagnosisForm input:focus,
.patientDiagnosisForm select:focus,
.patientDiagnosisForm textarea:focus {
  border-color: rgba(139, 92, 246, 0.75);
  box-shadow: 0 0 0 3px rgba(139, 92, 246, 0.12);
}

.patientDiagnosisFormError {
  min-height: 18px;
  color: #fca5a5;
  font-size: 0.78rem;
}

.patientDiagnosisFormActions {
  justify-content: flex-end;
  padding-top: 4px;
}

.patientDiagnosisFormActions button:disabled {
  cursor: wait;
  opacity: 0.62;
  transform: none;
}

.patientDiagnosisTimeline,
.patientDiagnosisHistoryList {
  padding: 18px 22px 22px;
}

.patientDiagnosisTimelineItem {
  position: relative;
  display: grid;
  grid-template-columns: 14px 1fr;
  gap: 10px;
  padding-bottom: 18px;
}

.patientDiagnosisTimelineItem::before {
  position: absolute;
  top: 13px;
  bottom: 0;
  left: 5px;
  width: 1px;
  background: rgba(148, 163, 184, 0.2);
  content: "";
}

.patientDiagnosisTimelineItem:last-child::before {
  display: none;
}

.patientDiagnosisTimelineItem > span {
  position: relative;
  z-index: 1;
  width: 11px;
  height: 11px;
  margin-top: 3px;
  border: 2px solid #a78bfa;
  border-radius: 50%;
  background: #101522;
}

.patientDiagnosisTimelineItem strong,
.patientDiagnosisTimelineItem time {
  display: block;
}

.patientDiagnosisTimelineItem strong {
  color: #f1f5f9;
  font-size: 0.84rem;
}

.patientDiagnosisTimelineItem time {
  margin-top: 3px;
  color: rgba(226, 232, 240, 0.5);
  font-size: 0.7rem;
}

.patientDiagnosisTimelineItem p {
  margin: 7px 0 0;
  color: rgba(226, 232, 240, 0.72);
  font-size: 0.78rem;
}

.patientDiagnosisModalLoading {
  padding: 24px;
  color: rgba(226, 232, 240, 0.58);
  text-align: center;
}

body[data-theme="white"] .patientDiagnosesPanel,
body[data-theme="white"] .patientDiagnosisModal {
  border-color: #cbddec;
  background:
    radial-gradient(circle at 100% 0%, rgba(86, 139, 177, 0.12), transparent 42%),
    #f8fbfd;
  box-shadow: 0 18px 42px rgba(31, 73, 102, 0.1);
}

body[data-theme="white"] .patientDiagnosesHeader h3,
body[data-theme="white"] .patientDiagnosisModalHeader h3,
body[data-theme="white"] .patientDiagnosisCard h4,
body[data-theme="white"] .patientDiagnosesEmpty strong {
  color: #17374e;
}

body[data-theme="white"] .patientDiagnosesHeader p,
body[data-theme="white"] .patientDiagnosisModalHeader p,
body[data-theme="white"] .patientDiagnosisMeta,
body[data-theme="white"] .patientDiagnosisNote {
  color: #607788;
}

body[data-theme="white"] .patientDiagnosisCard,
body[data-theme="white"] .patientDiagnosesEmpty,
body[data-theme="white"] .patientDiagnosisForm input,
body[data-theme="white"] .patientDiagnosisForm select,
body[data-theme="white"] .patientDiagnosisForm textarea {
  border-color: #d7e4ed;
  background: rgba(255, 255, 255, 0.82);
  color: #17374e;
}

body[data-theme="white"] .patientDiagnosesHeaderActions button,
body[data-theme="white"] .patientDiagnosisActions button,
body[data-theme="white"] .patientDiagnosisFormActions button,
body[data-theme="white"] .patientDiagnosisModalHeader > button {
  border-color: #cadce8;
  background: #edf5fa;
  color: #315a76;
}

body[data-theme="white"] .patientDiagnosesHeaderActions .is-primary,
body[data-theme="white"] .patientDiagnosisFormActions .is-primary {
  border-color: #467fa7;
  background: linear-gradient(135deg, #376f98, #568bb1);
  color: #fff;
}

@media (max-width: 900px) {
  .patientDiagnosisCard {
    align-items: flex-start;
    flex-direction: column;
  }

  .patientDiagnosisActions {
    justify-content: flex-start;
    max-width: none;
    width: 100%;
  }
}

@media (max-width: 640px) {
  .patientDiagnosesPanel {
    margin-inline: -2px;
    padding: 16px;
    border-radius: 16px;
  }

  .patientDiagnosesHeader {
    flex-direction: column;
  }

  .patientDiagnosesHeaderActions {
    width: 100%;
  }

  .patientDiagnosesHeaderActions button {
    flex: 1 1 0;
  }

  .patientDiagnosisCard {
    padding: 13px;
  }

  .patientDiagnosisActions {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .patientDiagnosisActions button {
    width: 100%;
  }

  .patientDiagnosisModalOverlay {
    align-items: end;
    padding: 0;
  }

  .patientDiagnosisModal {
    width: 100%;
    max-height: calc(100vh - 24px);
    border-radius: 20px 20px 0 0;
  }

  .patientDiagnosisModalHeader {
    padding: 18px 16px 14px;
  }

  .patientDiagnosisForm {
    grid-template-columns: 1fr;
    padding: 16px;
  }

  .patientDiagnosisForm label,
  .patientDiagnosisForm label.is-wide,
  .patientDiagnosisFormError,
  .patientDiagnosisFormActions {
    grid-column: 1;
  }

  .patientDiagnosisTimeline,
  .patientDiagnosisHistoryList {
    padding: 16px;
  }
}
.appPromptModal {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: grid;
  place-items: center;
  padding: 24px;
  background: rgba(3, 8, 18, 0.66);
  backdrop-filter: blur(10px);
}

.appPromptModal[hidden] {
  display: none !important;
}

.appPromptModalCard {
  position: relative;
  width: min(100%, 460px);
  border-radius: 24px;
  padding: 24px;
  background:
    linear-gradient(
      180deg,
      rgba(255, 255, 255, 0.08),
      rgba(255, 255, 255, 0.03)
    ),
    var(--app-modal-surface, #131b2b);
  border: 1px solid var(--app-modal-border, rgba(147, 70, 232, 0.38));
  box-shadow:
    0 30px 80px rgba(0, 0, 0, 0.42),
    0 0 0 1px rgba(255, 255, 255, 0.04) inset;
  color: var(--app-modal-text, #f5f7ff);
}

.appPromptModalClose {
  position: absolute;
  top: 14px;
  right: 14px;
  width: 38px;
  height: 38px;
  border: 1px solid var(--app-modal-border, rgba(147, 70, 232, 0.38));
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.04);
  color: var(--app-modal-text, #f5f7ff);
  cursor: pointer;
  font-size: 20px;
  line-height: 1;
}

.appPromptModalClose:hover {
  background: rgba(255, 255, 255, 0.08);
}

.appPromptModalBadge {
  width: 56px;
  height: 56px;
  border-radius: 18px;
  display: grid;
  place-items: center;
  margin-bottom: 16px;
  font-size: 26px;
  font-weight: 800;
  background: var(--app-modal-accent-soft, rgba(147, 70, 232, 0.14));
  color: var(--app-modal-accent, #9346e8);
  border: 1px solid var(--app-modal-border, rgba(147, 70, 232, 0.38));
  box-shadow: 0 0 30px var(--app-modal-accent-glow, rgba(147, 70, 232, 0.18));
}

.appPromptModalTitle {
  font-size: 28px;
  line-height: 1.15;
  font-weight: 800;
  margin-bottom: 8px;
}

.appPromptModalText {
  font-size: 15px;
  line-height: 1.55;
  color: var(--app-modal-muted, rgba(235, 240, 255, 0.72));
  margin-bottom: 18px;
}

.appPromptModalLabel {
  display: block;
  margin-bottom: 8px;
  font-size: 13px;
  font-weight: 700;
  color: var(--app-modal-muted, rgba(235, 240, 255, 0.72));
}

.appPromptModalInput {
  width: 100%;
  height: 52px;
  border-radius: 14px;
  border: 1px solid var(--app-modal-border, rgba(147, 70, 232, 0.38));
  background: rgba(7, 12, 24, 0.72);
  color: var(--app-modal-text, #f5f7ff);
  padding: 0 16px;
  font-size: 15px;
  outline: none;
  transition: border-color 0.18s ease, box-shadow 0.18s ease;
}

.appPromptModalInput:focus {
  border-color: var(--app-modal-accent, #9346e8);
  box-shadow: 0 0 0 4px var(--app-modal-accent-soft, rgba(147, 70, 232, 0.14));
}

.appPromptModalError {
  margin-top: 10px;
  padding: 10px 12px;
  border-radius: 12px;
  font-size: 13px;
  line-height: 1.4;
  background: rgba(255, 90, 90, 0.12);
  border: 1px solid rgba(255, 90, 90, 0.24);
  color: #ffb1b1;
}

.appPromptModalActions {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
  margin-top: 20px;
}

.appPromptModalBtn {
  min-width: 128px;
  height: 48px;
  border: 0;
  border-radius: 14px;
  font-size: 15px;
  font-weight: 800;
  cursor: pointer;
  transition: transform 0.16s ease, opacity 0.16s ease, box-shadow 0.16s ease;
}

.appPromptModalBtn:hover {
  transform: translateY(-1px);
}

.appPromptModalBtnSecondary {
  background: rgba(255, 255, 255, 0.08);
  color: var(--app-modal-text, #f5f7ff);
  border: 1px solid rgba(255, 255, 255, 0.08);
}

.appPromptModalBtnPrimary {
  background: linear-gradient(
    135deg,
    var(--app-modal-accent, #9346e8),
    var(--app-modal-accent-2, #7c5cff)
  );
  color: #fff;
  box-shadow: 0 14px 34px var(--app-modal-accent-glow, rgba(147, 70, 232, 0.22));
}

.appPromptModalBtn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
  transform: none;
}

