  min-height: 280px !important;

  flex: 0 0 auto !important;

  box-sizing: border-box !important;

  padding: 26px !important;

  border-radius: 24px !important;

  background:
    linear-gradient(
      180deg,
      rgba(
        255,
        255,
        255,
        0.08
      ),
      rgba(
        255,
        255,
        255,
        0.03
      )
    ),
    var(
      --app-modal-surface,
      #131b2b
    ) !important;

  border:
    1px solid
    var(
      --app-modal-border,
      rgba(
        147,
        70,
        232,
        0.38
      )
    ) !important;

  color:
    var(
      --app-modal-text,
      #f5f7ff
    ) !important;

  opacity: 1 !important;
  visibility: visible !important;

  pointer-events: auto !important;

  box-shadow:
    0 30px 80px
      rgba(
        0,
