/* =========================================================
   PATIENT DIAGNOSES — THEME ADAPTIVE OVERRIDE
   ========================================================= */

.patientDiagnosesPanel,
.patientDiagnosisModal {
  border-color:
    color-mix(
      in srgb,
      var(--accent-color) 28%,
      rgba(255, 255, 255, 0.08)
    );

  background:
    radial-gradient(
      circle at 100% 0%,
      color-mix(
        in srgb,
        var(--accent-color) 14%,
        transparent
      ),
      transparent 42%
    ),
    linear-gradient(
      145deg,
      rgba(15, 22, 40, 0.94),
      rgba(8, 13, 26, 0.96)
    );

  box-shadow:
    0 18px 45px rgba(0, 0, 0, 0.24),
    0 0 0 1px
      color-mix(
        in srgb,
        var(--accent-color) 5%,
        transparent
      )
      inset;
}

.patientDiagnosesHeader h3,
.patientDiagnosisModalHeader h3 {
  color: var(--text-main);
}

.patientDiagnosesHeader p,
.patientDiagnosisModalHeader p,
.patientDiagnosisMeta,
.patientDiagnosisNote,
.patientDiagnosisModalLoading {
  color: var(--text-muted);
}

.patientDiagnosisCard {
  background:
    linear-gradient(
      145deg,
      rgba(255, 255, 255, 0.045),
      rgba(255, 255, 255, 0.02)
    );

  border-color:
    rgba(255, 255, 255, 0.075);
}

.patientDiagnosisCard:hover {
  border-color:
    color-mix(
      in srgb,
      var(--accent-color) 38%,
      rgba(255, 255, 255, 0.08)
    );
}

.patientDiagnosisCard h4 {
  color: var(--text-main);
}

/* Акцентная полоска слева у активной карточки */

.patientDiagnosisCard.status-active {
  border-left:
    3px solid
    var(--accent-color);
}

/* Обычные кнопки */

.patientDiagnosesHeaderActions button,
.patientDiagnosisActions button,
.patientDiagnosisFormActions button,
.patientDiagnosisModalHeader > button {
  border-color:
    rgba(255, 255, 255, 0.1);

  background:
    rgba(255, 255, 255, 0.045);

  color:
    var(--text-main);
}

.patientDiagnosesHeaderActions button:hover,
.patientDiagnosisActions button:hover,
.patientDiagnosisFormActions button:hover,
.patientDiagnosisModalHeader > button:hover {
  border-color:
    color-mix(
      in srgb,
      var(--accent-color) 50%,
      rgba(255, 255, 255, 0.1)
    );

  background:
    color-mix(
      in srgb,
      var(--accent-color) 12%,
      rgba(255, 255, 255, 0.035)
    );

  color:
    var(--text-main);

  box-shadow:
    0 0 16px
      color-mix(
        in srgb,
        var(--accent-color) 13%,
        transparent
      );
}

/* Главная кнопка */

.patientDiagnosesHeaderActions .is-primary,
.patientDiagnosisFormActions .is-primary {
  border-color:
    color-mix(
      in srgb,
      var(--accent-color) 65%,
      transparent
    );

  background:
    linear-gradient(
      135deg,
      var(--accent-color),
      color-mix(
        in srgb,
        var(--accent-color) 72%,
        #000
      )
    );

  color: #fff;

  box-shadow:
    0 8px 22px
      color-mix(
        in srgb,
        var(--accent-color) 25%,
        transparent
      );
}

/* Код диагноза */

.patientDiagnosisCode {
  border-color:
    color-mix(
      in srgb,
      var(--accent-color) 22%,
      rgba(255, 255, 255, 0.08)
    );

  background:
    color-mix(
      in srgb,
      var(--accent-color) 8%,
      rgba(255, 255, 255, 0.03)
    );

  color:
    color-mix(
      in srgb,
      var(--accent-color) 65%,
      #ffffff
    );
}

/* Timeline истории */

.patientDiagnosisTimelineItem > span {
  border-color:
    var(--accent-color);

  background:
    color-mix(
      in srgb,
      var(--accent-color) 10%,
      #101522
    );

  box-shadow:
    0 0 10px
      color-mix(
        in srgb,
        var(--accent-color) 30%,
        transparent
      );
}

.patientDiagnosisTimelineItem::before {
  background:
    color-mix(
      in srgb,
      var(--accent-color) 22%,
      rgba(148, 163, 184, 0.16)
    );
}

/* Инпуты */

.patientDiagnosisForm input,
.patientDiagnosisForm select,
.patientDiagnosisForm textarea {
  background:
    rgba(5, 10, 20, 0.42);

  border-color:
    rgba(255, 255, 255, 0.09);

  color:
    var(--text-main);
}

.patientDiagnosisForm input:focus,
.patientDiagnosisForm select:focus,
.patientDiagnosisForm textarea:focus {
  outline: none;

  border-color:
    color-mix(
      in srgb,
      var(--accent-color) 65%,
      white
    );

  box-shadow:
    0 0 0 3px
      color-mix(
        in srgb,
        var(--accent-color) 13%,
        transparent
      );
}

